window.W2W_BUNDLE={"BUILD_ID.js":"// 构建指纹：回归脚本校验用（tools/regression.js）\nmodule.exports = 'BUILD-1105-main-r1';\n","app.js":"/* 全局入口：状态恢复 + 登录态预热 + 错误上报 */\n/* 注意：BUILD_ID.js 导出的是字符串，解构会得 undefined（提审线票 39 同款事故） */\nconst BUILD_ID = require('./BUILD_ID.js');\nconst user = require('./stores/user');\nconst auth = require('./services/auth');\n\nApp({\n  BUILD_ID,\n  globalData: { justEntered: false },\n  onLaunch() {\n    /* 云开发初始化（v15：图片走云存储 cloud:// 内建通道——安卓/iOS 均不受域名校验） */\n    if (wx.cloud) wx.cloud.init({ env: 'cloudbase-d3giwlyte87aecc2e', traceUser: true });\n    /* 字体换装：思源宋体（Noto Serif SC · OFL 可商用）3500 常用字子集 @ Supabase 桶公共读。\n     * 失败静默回落系统宋栈（fallback 同族，闪替无感）；上线前在 mp 后台把 *.supabase.co 加入 downloadFile 合法域名\n     * （开发期已 project.config.json urlCheck=false）。字形脱落属预期：动态文本缺字回落系统栈。 */\n    if (wx.loadFontFace) {\n      wx.loadFontFace({\n        global: true,\n        family: 'XISong',\n        source: 'url(\"https://vmqqkwrtbsutpbnwnefa.supabase.co/storage/v1/object/public/xinzhiyu/xixi/prod/asset/fonts/noto-serif-sc-400.subset.woff2\")',\n        success: () => console.log('font XISong loaded'),\n        fail: (e) => console.log('font XISong fallback:', e && e.errorMessage)\n      });\n      wx.loadFontFace({\n        global: true,\n        family: 'XISong',\n        desc: { weight: 300 }, /* Light：Display 大标题细体（观夏节奏），粗处仍由 400+合成 */\n        source: 'url(\"https://vmqqkwrtbsutpbnwnefa.supabase.co/storage/v1/object/public/xinzhiyu/xixi/prod/asset/fonts/noto-serif-sc-300.subset.woff2\")',\n        success: () => console.log('font XISong 300 loaded'),\n        fail: (e) => console.log('font XISong 300 fallback:', e && e.errorMessage)\n      });\n    }\n    /* 登录态预热：mock 下本地模拟 token，真实前端换 /api/auth/login */\n    auth.ensureSession().catch(err => {\n      reportErr('launch-auth: ' + err.message);\n    });\n  },\n  onError(msg) {\n    reportErr('app-error: ' + msg);\n  },\n  onUnhandledRejection(res) {\n    reportErr('unhandled: ' + (res.reason && res.reason.message || res.reason));\n  }\n});\n\n/* 最小日志上报：真实前端接 wx.getRealtimeLogManager 或自建日志接口 */\nfunction reportErr(msg) {\n  try {\n    wx.getRealtimeLogManager ? wx.getRealtimeLogManager().error(msg) : null;\n  } catch (e) {}\n  console.error(msg);\n}\n","behaviors/pet-face.js":"/* 西米表情机：待机眨眼/爱心轮换 + 戳一戳反应 + 开心摆动。\n * field = 页面里驱动表情图层的 data 字段名（chat 用 petFace，home 用 xFace）。\n * 页面自己持有定时器清理（onHide/onUnload 调 stopIdleFace）。 */\nmodule.exports = function petFace(field) {\n  return Behavior({\n    data: {},\n    methods: {\n      /* 单次表情切换：face('wow', 1200) */\n      face(n, dur) {\n        this.setData({ [field]: n });\n        if (dur) {\n          clearTimeout(this._faceT);\n          this._faceT = setTimeout(() => this.setData({ [field]: 'base' }), dur);\n        }\n      },\n      /* 待机轮换：每 tick 递增计数，逢 4 上爱心，其余眨眼 */\n      startIdleFace(period) {\n        this.stopIdleFace();\n        this._idleN = 0;\n        this._idleT = setInterval(() => {\n          this._idleN++;\n          const f = this._idleN % 4 === 0 ? 'love' : 'blink';\n          this.face(f, f === 'love' ? 1500 : 1100);\n        }, period || 4200);\n      },\n      stopIdleFace() {\n        clearInterval(this._idleT);\n        clearTimeout(this._faceT);\n      },\n      faceHappy() {\n        this.setData({ petHappy: true, petWiggle: false });\n        this.face('love', 1300);\n        setTimeout(() => this.setData({ petHappy: false }), 750);\n      },\n      facePoked() {\n        this.setData({ petHappy: false, petWiggle: true });\n        this.face('wow', 1200);\n        setTimeout(() => this.setData({ petWiggle: false }), 550);\n      }\n    }\n  });\n};\n","behaviors/tab.js":"/* tab 页同步自定义 tabBar 选中项：工厂绑定本页 tab 下标。\n * 注意：Page 的 behaviors 不保证 onShow 生命周期合并（页面自身 onShow 会覆盖），\n * 所以这里只提供方法，由页面 onShow 里显式调用 this.syncTab()。\n *\n * 2026-10-09 增 setTabHidden：全屏浮层要盖住 tabBar。\n *   自定义 tabBar 由框架单独渲染，`z-index:80` 的浮层**盖不住**它（实测：浮层开着导航条仍露在上面、\n *   还能点走）。甲方原型里浮层是盖住导航的（.overlay z-80 > .tabbar z-40），所以这里按原型行为\n *   把导航整条藏掉，浮层关掉再放出来。grow 页没有浮层，不需要用。\n */\nmodule.exports = function tab(idx) {\n  return Behavior({\n    methods: {\n      syncTab() {\n        if (typeof this.getTabBar === 'function' && this.getTabBar()) this.getTabBar().setData({ selected: idx });\n      },\n      setTabHidden(hidden) {\n        if (typeof this.getTabBar === 'function' && this.getTabBar()) {\n          this.getTabBar().setData({ hidden: !!hidden });\n        }\n      }\n    }\n  });\n};\n","behaviors/toast.js":"module.exports = Behavior({\n  data: { toastShow: false, toastMsg: '' },\n  methods: {\n    showToast(msg) {\n      this.setData({ toastShow: true, toastMsg: msg });\n      clearTimeout(this._tt);\n      this._tt = setTimeout(() => this.setData({ toastShow: false }), 1600);\n    }\n  }\n});\n","components/x-book-card/x-book-card.js":"/* 名家书房卡：样式走全局 .gr-b（app.wxss）。点击由组件内 triggerEvent('press') 上抛。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    item: { type: Object, value: {} },\n    rise: { type: Number, value: 0 }\n  },\n  methods: {\n    onTap() { this.triggerEvent('press'); }\n  }\n});\n","components/x-btn/x-btn.js":"/* 按钮：type 映射现有样式类\n * primary 玫瑰主钮 / glass 玻璃钮 / cta 问卷大钮 / qa 玻璃药丸选项\n * block 撑满 / disabled 置灰禁点 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    type: { type: String, value: 'primary' },\n    block: { type: Boolean, value: false },\n    disabled: { type: Boolean, value: false }\n  },\n  methods: {\n    onTap(e) {\n      if (this.data.disabled) return;\n      this.triggerEvent('tap', e.detail);\n    }\n  }\n});\n","components/x-card/x-card.js":"/* 玻璃卡：rise 入场动画 0-6 级延迟 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    rise: { type: Number, value: 0 }   // 0=无动画 1-6=d1..d6\n  }\n});\n","components/x-chat-input/x-chat-input.js":"/* 聊天输入栏积木：语音/图片按钮（演示态 toast 上抛）+ 输入框 + 发送。\n * 键盘高度由页面（内核）算好，用 kbH 属性传入；输入事件全部上抛。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    value: { type: String, value: '' },\n    kbH: { type: Number, value: 0 }   // 键盘高度（px），0 = 未弹出\n  },\n  methods: {\n    onInput(e) { this.triggerEvent('input', { value: e.detail.value }); },\n    onFocus() { this.triggerEvent('focus'); },\n    onBlur() { this.triggerEvent('blur'); },\n    onKb(e) { this.triggerEvent('kb', { height: e.detail.height }); },\n    onSend() { this.triggerEvent('send'); },\n    onVoice() { this.triggerEvent('voice'); },\n    onPic() { this.triggerEvent('pic'); }\n  }\n});\n","components/x-chat-top/x-chat-top.js":"/* 聊天顶栏积木：返回 / 西米+倾听声波 / 预约咨询。样式自包含（R2 从 app.wxss 迁入，取值=两段主题最终生效值）。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    scrolled: { type: Boolean, value: false }\n  },\n  methods: {\n    onBack() { this.triggerEvent('back'); },\n    onBook() { this.triggerEvent('book'); }\n  }\n});\n","components/x-crisis-card/x-crisis-card.js":"/* 危机干预卡积木（红线级）：文案、热线号、冷静期计时（calmOk 由页面按 modules/crisis.js 的\n * TIMING 控制）全部是正本内容 —— 本积木只做呈现，禁止在此增删文案或改计时逻辑。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    show: { type: Boolean, value: false },\n    calmOk: { type: Boolean, value: false }   // 冷静期结束才可点「我先冷静一下」\n  },\n  methods: {\n    onConsult() { this.triggerEvent('consult'); },\n    onClose() { this.triggerEvent('close'); }\n  }\n});\n","components/x-daily-quote/x-daily-quote.js":"/* 今日一句积木：金句卡 + 分享按钮。样式自包含（第一轮从 app.wxss 迁入）。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    text: { type: String, value: '' },\n    author: { type: String, value: '' },\n    image: { type: String, value: '' },\n    rise: { type: Number, value: 0 }\n  },\n  methods: {\n    onPress() { this.triggerEvent('press'); },\n    onShare() { this.triggerEvent('share'); }\n  }\n});\n","components/x-duo-cards/x-duo-cards.js":"/* 双卡积木：冥想/助眠（可竖排变体）。样式自包含（第一轮从 app.wxss 迁入）。\n * 内核传 items（纯数据）+ col（摆法），选择动作以 key 上抛 select。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    items: { type: Array, value: [] },      // [{ key, img, title, sub }]\n    col: { type: Boolean, value: false }    // true = 竖排（首页右列）\n  },\n  methods: {\n    onSelect(e) { this.triggerEvent('select', { key: e.currentTarget.dataset.key }); }\n  }\n});\n","components/x-gcal/x-gcal.js":"/* 心情日历卡外壳积木（home / moodcal 共用）：玻璃外壳 + 背景图 + 内容插槽。\n * variant 追加类名（'' | 'mcal' | 'mcal mmood'）；点击上抛 press（仅首页绑定）。\n * 内容样式在各自页面的 wxss（首页紧凑卡在 pages/home/home.wxss）。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    variant: { type: String, value: '' },\n    bg: { type: String, value: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/conc-botanic.jpg' }\n  },\n  methods: {\n    onPress() { this.triggerEvent('press'); }\n  }\n});\n","components/x-hero-xixi/x-hero-xixi.js":"/* 西米 hero 积木：表情切换 + 气泡 + 倾听说明。样式自包含（第一轮从 app.wxss 迁入）。\n * 内核只传 face / bubble，交互上抛 poke / chat —— 换风格只改本目录。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    face: { type: String, value: 'base' },   // base | blink | wow | love\n    bubble: { type: String, value: '' },\n    rise: { type: Number, value: 0 }\n  },\n  methods: {\n    onPoke() { this.triggerEvent('poke'); },\n    onChat() { this.triggerEvent('chat'); }\n  }\n});\n","components/x-icon/x-icon.js":"/* 图标：data-uri SVG 已带颜色，name 对应 icon.wxss 变体类 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    name: { type: String, value: '' },      // 例：ic3 / ic22-on / icspark\n    size: { type: Number, value: 32 }       // rpx\n  }\n});\n","components/x-msg/x-msg.js":"/* 聊天气泡：role ai/user；typing 显示三点输入态\n * tags 情绪标签；mem 引用档案标记；hideAv 连续同方隐藏头像 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    role: { type: String, value: 'ai' },\n    text: { type: String, value: '' },\n    tags: { type: Array, value: [] },\n    mem: { type: Boolean, value: false },\n    hideAv: { type: Boolean, value: false },\n    typing: { type: Boolean, value: false },\n    animate: { type: Boolean, value: false }\n  }\n});\n","components/x-navbar/x-navbar.js":"/* 子页导航：标题 + 返回。back: auto(栈返回，失败转 backUrl) | url(直接跳 backUrl)\n * 2026-10-09：跳转改走 utils/nav.js（按页面归属自动选 switchTab/navigateTo）。\n *   原来默认 backUrl 指向首页且硬用 switchTab —— 首页摘掉 tab 后那会静默失败。\n *   默认回落目标改为 tab0「西米」（打开即对话，是新的默认去处）。 */\nconst nav = require('../../utils/nav');\n\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    title: { type: String, value: '' },\n    dark: { type: Boolean, value: false },\n    back: { type: String, value: 'auto' },\n    backUrl: { type: String, value: '/pages/chat/chat' },\n    showBack: { type: Boolean, value: true }\n  },\n  methods: {\n    onBack() {\n      if (this.data.back === 'url') { nav.go(this.data.backUrl); return; }\n      nav.back(this.data.backUrl);\n    }\n  }\n});\n","components/x-orb-pet/x-orb-pet.js":"/* 漂浮西米积木（树洞页）：四表情 + 呼吸/跳跃/摇摆动画 + 键盘避让（kbH 由页面算）。\n * 表情状态由 behaviors/pet-face 工厂驱动（页面内核），本积木只渲染与上抛。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    face: { type: String, value: 'base' },   // base | blink | wow | love\n    peek: { type: Boolean, value: false },\n    happy: { type: Boolean, value: false },\n    wiggle: { type: Boolean, value: false },\n    kbH: { type: Number, value: 0 }\n  },\n  methods: {\n    onPoke() { this.triggerEvent('poke'); }\n  }\n});\n","components/x-ov-avatar/x-ov-avatar.js":"/* 插画头像浮层（甲方排版基准原型 ovAvatar）\n * 12 个线条稿（utils/avatars，自原型 AVS 逐条抄录），选中的索引写进 stores/ximi，\n * 对话页的用户气泡头像 onShow 时读同一份 → 换完对话里同步变（甲方决议 12）。\n * 事件：close · pick {index,name}\n */\nconst D = require('../../utils/me-data');\nconst avatars = require('../../utils/avatars');\nconst ximi = require('../../stores/ximi');\n\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: { show: { type: Boolean, value: false } },\n  data: { t: D.OV_AVATAR, list: [], cur: 0 },\n  observers: {\n    show: function (show) {\n      if (!show) return;\n      const cur = ximi.get('avatar');\n      /* 只在列表为空时构建一次：data-uri 较大，避免每次开浮层重算 */\n      this.setData({ cur: cur, list: this.data.list.length ? this.data.list : avatars.list() });\n    }\n  },\n  methods: {\n    onClose() { this.triggerEvent('close'); },\n    onPick(e) {\n      const i = Number(e.currentTarget.dataset.i);\n      const name = this.data.list[i].name;\n      ximi.set({ avatar: i });\n      this.setData({ cur: i });\n      this.triggerEvent('pick', { index: i, name: name });\n    }\n  }\n});\n","components/x-ov-comp/x-ov-comp.js":"/* 真人陪伴浮层（甲方排版基准原型 ovComp）\n * 三处入口共用：对话页轻入口 / 对话内承接「看看她是谁」/ 我的页卡片\n * 事件：close · consult（底部「看看陪伴师介绍」）\n * 价格文案（¥5,800 / 月起）与后端口径不一致，照原型抄录并登记——见 utils/me-data 头部说明\n */\nconst D = require('../../utils/me-data');\n\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: { show: { type: Boolean, value: false } },\n  data: { t: D.OV_COMP },\n  methods: {\n    onClose() { this.triggerEvent('close'); },\n    onConsult() { this.triggerEvent('consult'); }\n  }\n});\n","components/x-ov-practice/x-ov-practice.js":"/* 练习浮层（四合一）：kind = write | med | breath | oh\n *\n * 为什么合成一个组件：四个浮层共用「全屏壳 + 顶栏（标题/副题/关闭）+ 滚动体」，\n * 差别只在体内，逻辑各自独立且都很小。拆四个组件会多出 12 个文件而不增清晰度。\n *\n * 用途：疗愈页（4 个入口）与西米对话页（剧本分支 x-write / x-breath 也会打开）共用。\n * 文案：全部取自 utils/heal-data.js（甲方原型逐字）。\n * 事件：\n *   close                —— 关闭\n *   lamp   {toast}       —— 该动作要点亮一盏灯（灯海在变化页，计数在 stores/ximi）\n *   said   {text}        —— 书写保存后要往对话里插的一句 AI 回复（对话页消费；疗愈页忽略）\n */\nconst D = require('../../utils/heal-data');\nrequire('../../stores/ximi');\n\nconst TXT = { write: D.WRITE, med: D.MED, breath: D.BREATH, oh: D.OH };\n\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    show: { type: Boolean, value: false },\n    kind: { type: String, value: '' }\n  },\n  data: {\n    t: {},            /* 当前 kind 的文案对象 */\n    /* 呼吸 */\n    bTxt: '', bStep: '', bCls: '',\n    /* OH */\n    ohOpen: false, ohText: '', ohBg: '', ohQ: '',\n    /* 书写 */\n    wr: ''\n  },\n  observers: {\n    'kind, show': function (kind, show) {\n      if (!show) { this.stopBreath(); return; }\n      this.setData({ t: TXT[kind] || {} });\n      if (kind === 'breath') { this.resetBreath(); }\n      if (kind === 'oh') { this.resetOh(); }\n      if (kind === 'write') { this.setData({ wr: '' }); }\n    }\n  },\n  detached() { this.stopBreath(); },\n  methods: {\n    noop() {},\n\n    onClose() {\n      this.stopBreath();\n      this.triggerEvent('close');\n    },\n\n    /* ---------- 呼吸 4-7-8：吸气 4s → 屏住 7s → 呼气 8s，循环 ---------- */\n    resetBreath() {\n      this.stopBreath();\n      this.setData({ bTxt: D.BREATH.ready, bStep: D.BREATH.readyStep, bCls: '' });\n    },\n    stopBreath() {\n      this._breathing = false;\n      clearTimeout(this._bt);\n    },\n    onStartBreath() {\n      if (this._breathing) return;\n      this._breathing = true;\n      this.cycle(0);\n    },\n    onStopBreath() { this.resetBreath(); },\n    cycle(i) {\n      if (!this._breathing) return;\n      const p = D.BREATH.phases[i % 3];\n      this.setData({ bTxt: p.txt, bStep: p.step, bCls: p.cls });\n      this._bt = setTimeout(() => this.cycle(i + 1), p.hold);\n    },\n\n    /* ---------- OH 卡：点开翻面 + 随机一问 ---------- */\n    resetOh() { this.setData({ ohOpen: false, ohText: D.OH.face, ohBg: '', ohQ: D.OH.idle }); },\n    onTapOh() {\n      if (this.data.ohOpen) return;\n      const q = D.OH.q[Math.floor(Math.random() * D.OH.q.length)];\n      this.setData({ ohOpen: true, ohText: D.OH.opened, ohBg: D.OH.openedBg, ohQ: q });\n      this.triggerEvent('lamp', { toast: D.OH.toast });\n    },\n\n    /* ---------- 书写：保存 → 点亮一盏灯 + 回一句 ---------- */\n    onWr(e) { this.setData({ wr: e.detail.value }); },\n    onSaveWrite() {\n      const v = (this.data.wr || '').trim();\n      this.triggerEvent('lamp', { toast: D.WRITE.toast });\n      this.triggerEvent('said', { text: v ? D.WRITE.replyFilled : D.WRITE.replyEmpty });\n      this.triggerEvent('close');\n    },\n\n    /* ---------- 冥想：本轮只做\"选中\"反馈，音频未接（登记待办） ---------- */\n    onTapMed(e) {\n      const h5 = e.currentTarget.dataset.h5;\n      wx.showToast({ title: '音频未接入 · ' + h5, icon: 'none' });\n    }\n  }\n});\n","components/x-pay-sheet/x-pay-sheet.js":"/* 支付弹层：内容块自包含，壳仍走 x-sheet（mask + 面板）。\n * 样式走全局 .pay-*（app.wxss）；演示态文案由 utils/demo.js 管。\n * 支付链路割离中：解除 = 页面 doPay 改调 api.createOrder（见 docs/API-MAP.md #10）。 */\nComponent({\n  options: { styleIsolation: 'apply-shared' },\n  properties: {\n    show: { type: Boolean, value: false },\n    c: { type: Object, value: {} },\n    slotTxt: { type: String, value: '待选择' },\n    paid: { type: Boolean, value: false }\n  },\n  methods: {\n    onClose() { this.triggerEvent('close'); },\n    onPay() { this.triggerEvent('pay'); }\n  }\n});\n","components/x-quote-card/x-quote-card.js":"/* 咨询师感悟卡：样式走全局 .gr-c（app.wxss），与 x-card 同款 apply-shared。\n * 点击由组件内 triggerEvent('press') 上抛，页面 bind:press 接（virtualHost 下标签上的 bindtap 不可靠）。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    item: { type: Object, value: {} },\n    rise: { type: Number, value: 0 }\n  },\n  methods: {\n    onTap() { this.triggerEvent('press'); }\n  }\n});\n","components/x-share-card/x-share-card.js":"/* 用户分享卡：样式走全局 .gr-u（app.wxss）。原页面此卡无点击行为，保持无事件。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    item: { type: Object, value: {} },\n    rise: { type: Number, value: 0 }\n  }\n});\n","components/x-share-sheet/x-share-sheet.js":"/* 金句分享弹层积木：整屏遮罩 + 分享卡 + 保存/关闭。样式自包含（第一轮从 app.wxss 迁入）。\n * 内核只传 show / image / text / author，close / save 上抛（保存动作仍在页面，见 utils/demo.js）。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    show: { type: Boolean, value: false },\n    image: { type: String, value: '' },\n    text: { type: String, value: '' },\n    author: { type: String, value: '' }\n  },\n  methods: {\n    onClose() { this.triggerEvent('close'); },\n    onSave() { this.triggerEvent('save'); },\n    noop() {}\n  }\n});\n","components/x-sheet/x-sheet.js":"/* 底部弹层：mask + 圆角面板；show 控制，点 mask 触发 close 事件 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: { show: { type: Boolean, value: false } },\n  methods: {\n    onClose() { this.triggerEvent('close'); },\n    noop() {}\n  }\n});\n","components/x-toast/x-toast.js":"/* 全局轻提示：配 behaviors/toast.js 使用，页面 wxml 放一行 <x-toast show=\"{{toastShow}}\" msg=\"{{toastMsg}}\"/> */\nComponent({\n  properties: {\n    show: { type: Boolean, value: false },\n    msg: { type: String, value: '' }\n  }\n});\n","components/x-topic-row/x-topic-row.js":"/* 往期主题行：样式走全局 .gr-past（app.wxss）。原页面此行为纯展示（cursor:pointer 无处理），保持无事件。 */\nComponent({\n  options: { styleIsolation: 'apply-shared', virtualHost: true },\n  properties: {\n    item: { type: Object, value: {} },\n    rise: { type: Number, value: 0 }\n  }\n});\n","custom-tab-bar/index.js":"Component({\n  options: { styleIsolation: 'apply-shared' },\n  data: {\n    selected: 0,\n    hidden: false,   /* 全屏浮层打开时由页面 setTabHidden(true) 藏掉（浮层盖不住框架渲染的 tabBar） */\n    /* 顺序 = tab 索引，与 app.json tabBar.list 及 utils/nav.js 的 TABS 三处必须一致\n     * 图标：icximi / icheal / icgrow / icme（烘色，由 tools/gen-tab-icons.py 生成） */\n    list: [\n      { path: 'pages/chat/chat', icon: 'ximi', iconOn: 'ximi-on', text: '西米' },\n      { path: 'pages/heal/heal', icon: 'heal', iconOn: 'heal-on', text: '疗愈' },\n      { path: 'pages/grow/grow', icon: 'grow', iconOn: 'grow-on', text: '变化' },\n      { path: 'pages/me/me', icon: 'me', iconOn: 'me-on', text: '我的' }\n    ]\n  },\n  methods: {\n    switchTab(e) {\n      const { path, index } = e.currentTarget.dataset;\n      wx.switchTab({ url: '/' + path });\n      this.setData({ selected: index });\n    }\n  }\n});\n","modules/crisis.js":"/* 危机干预域模块（红线级）：危机词识别、安抚文案、专业转介与静默期时序。\n * 纯数据+纯函数，无 wx 依赖 —— 后端接通后由服务端下发判定，此模块退化为兜底。\n * 红线：危机场景零商业化、永不推销；文案禁用医疗词（诊断/治疗/治愈/康复）。 */\nconst CRISIS_WORDS = ['想死', '活不下去', '不想活', '自杀', '家暴', '打死我', '割腕', '轻生'];\n\nconst REPLY = '我听到你说「活不下去了」，这一定让你感到极度痛苦。当一个人经历这样的黑暗时刻，产生这些念头是创伤性的反应，这不是你的错。\\n\\n你现在并不孤单。我想让你知道，有很多人经历过类似的黑暗，并且走了出来。我这就为你联系专业支持。';\n\n/* 时序参数（毫秒）：typing 打字态时长 / calm 静默期（期间弹层不可关，防止误触离开支持页） */\nconst TIMING = { typing: 1200, calm: 5000 };\n\nfunction isCrisis(text) {\n  if (!text) return false;\n  return CRISIS_WORDS.some(w => text.includes(w));\n}\n\nmodule.exports = { CRISIS_WORDS, REPLY, TIMING, isCrisis };\n","modules/ximi-script.js":"/* 西米对话剧本（2026-10-09 从甲方排版基准原型移植）\n *\n * 来源：backend/docs/02-设计/甲方排版基准-西米演示-2026-10-09/西米-交互演示-粉蓝水彩版.html\n *      原型的 script 段是一堆 async 函数（内部直接操作 DOM）。此处**改写成纯数据 + 小 runner**：\n *        - 分支 = 数据节点，页面负责渲染（可 jest 直接断言，不需要模拟器）\n *        - 副作用（开浮层/点灯/toast/陪伴承接/切模式）变成声明式字段，由页面执行\n *      文案逐字照抄，未改一字。\n *\n * 节点字段：\n *   say     [{s:'', role:true?}] 或 ['']   —— 要说的台词；role:true = 演练中「他」的气泡\n *   chips   [{t,k,coach}]                  —— 说完后给的选项\n *   coach   true                           —— 进入前先切教练模式（原型 S['sort'] 的 if mode!=='coach'）\n *   confirm {text,yes,no,yesGo,noSay}      —— 轻确认卡（原型 confirmCard）\n *   open    'ovBreath'|'ovWrite'           —— 开浮层\n *   lamp    true                           —— 点亮一盏灯\n *   toast   '...'                          —— 提示\n *   nudge   true                           —— 陪伴承接（全场只出现一次）\n *   wait    毫秒                            —— 台词说完后的停顿（原型 await wait）\n *\n * 红线：**危机分支不走本表**。原型 freeform 里的危机正则与热线号码（12356）不移植，\n *      一律走 modules/crisis.js 的项目基线（热线 400-161-9995）。\n */\n\n/* ---------- 自由输入的兜底分支（原型 freeform 里内联、无 S 键的三条） ---------- */\nconst FREE_NODES = {\n  '__sleepy': {\n    say: ['睡不着的时候，脑子反而最忙。', '先别跟它较劲。要不要试试呼吸？四分钟，把身体先放下来。'],\n    chips: [{ t: '好，试一下', k: 'x-breath' }, { t: '想先说说', k: 'company' }]\n  },\n  '__tired-free': {\n    say: ['嗯，我听见了。', '别急着说清楚，先说出来就行。', '今天最难的是哪一下？'],\n    chips: [{ t: '说不清，就是累', k: 't-vague' }, { t: '有件具体的事', k: 't-specific' }]\n  },\n  '__fallback': {\n    say: ['嗯，我在听。', '再往下说一点——这件事在哪一刻最让你难受？'],\n    chips: [{ t: '有件事想理一理', k: 'sort', coach: true }, { t: '就想说说感受', k: 'company' }]\n  },\n  /* 轻确认卡的「先不用」支线（原型 confirmCard 的 onNo） */\n  '__keep-friend': { say: ['行。那就先不解决它。', '你说，我听着。'] }\n};\n\n/* ---------- 36 条剧本分支 ---------- */\nconst BRANCHES = {\n  /* 累 / 说不清 */\n  'tired': {\n    say: ['嗯，我听见了。', '不用急着说是什么事。累本身，就够说一会儿了。', '今天哪一段最难熬？'],\n    chips: [\n      { t: '说不清，就是累', k: 't-vague' },\n      { t: '有件具体的事', k: 't-specific' },\n      { t: '就想有人陪一会儿', k: 't-company' }\n    ]\n  },\n  't-vague': {\n    say: ['说不清是对的。', '真的累的时候，人是没有力气去分析\"为什么累\"的。',\n      '那就先不说原因。今天有没有哪一刻，你稍微松了一点点？'],\n    chips: [{ t: '有，晚上一个人待着的时候', k: 't-a' }, { t: '没有，一整天都绷着', k: 't-b' }]\n  },\n  't-a': {\n    say: ['那说明你还需要一点\"一个人的时候\"。', '不用多，每天二十分钟就够。', '今晚那二十分钟，你想怎么过？'],\n    chips: [{ t: '我想试试那个呼吸练习', k: 'x-breath' }, { t: '就想躺着什么都不干', k: 'x-rest' }]\n  },\n  'x-breath': {\n    say: ['好。我带你去。', '跟着圆走就行，不用做对。'],\n    wait: 700, open: 'breath'\n  },\n  'x-rest': { say: ['那就躺着。什么都不干也是正经事。', '明天这个时候，我还在这儿。'] },\n  't-b': {\n    say: ['一整天都绷着——那不是你不够放松，是你今天真的没有可以放松的空档。',\n      '不用逼自己现在就松下来。', '要不要先做一轮呼吸？四分钟，什么都不用想。'],\n    chips: [{ t: '好，做一轮', k: 'x-breath' }, { t: '算了，我想说说话', k: 'company' }]\n  },\n  't-specific': {\n    say: ['好，那你挑一件说。', '不用讲前因后果，就说今天最难受的那一下，是什么时候。'],\n    chips: [{ t: '跟我老公有关', k: 'husband' }, { t: '跟孩子有关', k: 'child' }, { t: '跟我自己有关', k: 'self' }]\n  },\n  't-company': {\n    say: ['行，我在。', '你不用非得说什么。想安静一会儿也行，我不催。', '想说话的时候，随便哪句都可以开头。'],\n    chips: [{ t: '今天过得很没意思', k: 'flat' }, { t: '我是不是有点矫情', k: 'selfblame' }]\n  },\n\n  /* 没意思 / 时间 */\n  'flat': {\n    say: ['\"没意思\"这三个字，比\"难过\"更耗人。', '难过是有由头的，没意思是没有。',\n      '最近这种\"没意思\"，是从什么时候开始的？'],\n    chips: [{ t: '有一阵子了', k: 'flat-long' }, { t: '就这几天', k: 'flat-short' }]\n  },\n  'flat-long': {\n    say: ['有一阵子了……那它已经不只是心情了，更像是一种底色。',\n      '这种时候，我建议你别急着\"让自己开心起来\"。',\n      '先把每天的一件事找回来——一件你真的想做、而不是应该做的事。'],\n    nudge: true,\n    chips: [{ t: '我想不出有什么事想做', k: 'sort' }, { t: '有，但我总没时间', k: 'x-time' }]\n  },\n  'flat-short': {\n    say: ['那可能只是这几天太满了。', '不用处理，让它自己过去。', '倒是可以记一下，看看它下次什么时候来。'],\n    chips: [{ t: '好，我去记一下', k: 'x-write' }]\n  },\n  'x-time': {\n    say: ['\"总没时间\"通常不是时间的问题，是那件事排在所有人后面。',\n      '这周挑一件，把它排到别人前面一次试试。', '要不要我陪你把这件小事定下来？'],\n    chips: [{ t: '好', k: 'sort' }]\n  },\n  'x-write': {\n    say: ['我给你开一页纸。', '写多写少都行，主要是写给你自己看的。'],\n    wait: 700, open: 'write'\n  },\n\n  /* 自我责备 */\n  'selfblame': {\n    say: ['不矫情。', '一个人愿意把自己的感受拿出来说，是件挺不容易的事。',\n      '你会觉得矫情，多半是以前有人说你\"想太多\"。'],\n    chips: [{ t: '……你怎么知道', k: 'know' }, { t: '嗯，从小就这样', k: 'growup' }]\n  },\n  'know': {\n    say: ['因为这句话很常见，尤其是在把家里撑起来的人身上。',\n      '撑着的人，最没有资格说累——这是别人给你的规矩，不是事实。', '今天你可以累。']\n  },\n  'growup': {\n    say: ['从小就这样，那这句话在你身上已经待了很多年了。', '今天先不拆它。',\n      '你只试一件事：下次想说\"我是不是矫情\"的时候，把它换成一个陈述句——\"我现在很难受\"。'],\n    chips: [{ t: '好，我试试', k: 'x-lamp' }]\n  },\n  'x-lamp': {\n    say: ['记下了。', '我把这件小事放进你的变化里，明天你还能看到。'],\n    lamp: true, toast: '已记录 · 点亮一盏灯'\n  },\n\n  /* 教练组 */\n  'sort': {\n    coach: true,\n    say: ['先给我三样东西就够了：', '这件事跟谁有关、大概发生了什么、你最想要的结果是什么。',\n      '不用写得整齐，想到什么说什么。'],\n    chips: [\n      { t: '跟我老公，总是为同一件事吵', k: 'husband-sort', coach: true },\n      { t: '跟我婆婆，住一起很难受', k: 'mil-sort', coach: true },\n      { t: '跟孩子，怎么说都不听', k: 'child-sort', coach: true }\n    ]\n  },\n  'advice': {\n    coach: true,\n    say: ['可以。但我要先知道细节，不然给的都是没用的建议。',\n      '先说最近一次——发生了什么，你当时怎么说的，对方什么反应？'],\n    chips: [{ t: '我来说一次最近的', k: 'sort', coach: true }, { t: '太多了，不知道从哪说', k: 'sort', coach: true }]\n  },\n  'longtime': {\n    coach: true,\n    say: ['卡了很久的事，通常不是难在不知道怎么做。', '是难在——每个选项你都不想选。', '说说看，卡在哪一步？'],\n    chips: [{ t: '我知道该做什么，但做不到', k: 'cant-do', coach: true },\n      { t: '我不知道该选哪个', k: 'cant-choose', coach: true }]\n  },\n  'cant-do': {\n    say: ['知道该做但做不到，一般是这件事太大，或者第一次做要付出的代价太高。', '我们把它切小。',\n      '如果只做这件事的第一步，那个第一步是什么？'],\n    chips: [{ t: '开口跟他说', k: 'husband-sort', coach: true }, { t: '先不管了，太累', k: 'tired' }]\n  },\n  'cant-choose': {\n    say: ['选不出来，往往是因为你在拿\"对不对\"衡量。', '换个尺子：哪个选项让你更接近你想成为的那种人？',\n      '说说两个选项分别是什么。'],\n    chips: [{ t: '留还是走', k: 'husband-sort', coach: true }, { t: '说还是忍', k: 'husband-sort', coach: true }]\n  },\n\n  /* 冲突演练主线 */\n  'husband-sort': {\n    say: ['同一件事反复吵，通常不是这件事本身。', '是这件事背后，有个东西一直没被回应。',\n      '我得先知道细节。', '先说最近一次——为了什么事，你当时怎么说的，他什么反应？'],\n    chips: [\n      { t: '演练一下，我该怎么说', k: 'drill-start', coach: true },\n      { t: '我来说说上次的情况', k: 'drill-detail', coach: true }\n    ]\n  },\n  'drill-detail': {\n    say: ['好，你说。', '不用修饰，原话最好——包括他回你的那一句。'],\n    chips: [{ t: '每次我一开口他就说\"你又来了\"', k: 'drill-start', coach: true }]\n  },\n  'drill-start': {\n    drill: true,\n    say: ['好。规则说一遍：', '我来演他，按他平时的样子反应。', '我不会演一个理想的丈夫——那样练了没用。',\n      '你先说第一句。想好了就发给我。'],\n    toast: '演练中 · 用你平时会说的话发给我'\n  },\n  'drill-again': { say: ['来。你先说第一句。', '这次记住：不翻总账，只说这一件。'] },\n  'drill-save': {\n    drillEnd: true,\n    say: ['记下了。', '我把它做成了一张话术卡，放进你的变化里——开口前可以再看一眼。', '明天回来告诉我他怎么回的。'],\n    lamp: true, toast: '话术卡已存 · 点亮一盏灯', wait: 900, nudge: true\n  },\n\n  /* 老公 / 骂 / 孩子 / 自己 / 婆婆 */\n  'husband': {\n    say: ['跟他有关。', '那你现在最想的是——让他明白你，还是让这件事有个结果？'],\n    chips: [{ t: '想让他明白我', k: 'husband-sort', coach: true },\n      { t: '想让这件事别再发生', k: 'husband-sort', coach: true }, { t: '就想骂他一顿', k: 'mad' }]\n  },\n  'mad': {\n    say: ['想骂就骂，在我这儿不用忍着。', '骂完我们再看他那边到底卡在哪。'],\n    chips: [{ t: '算了，骂也没用', k: 'husband-sort', coach: true }]\n  },\n  'child': {\n    say: ['孩子的难，多半不是当下这一件事。', '是\"我说了他也不听\"，一天天堆起来的无力。', '最近一次是哪件事？'],\n    chips: [{ t: '写作业，每天都要吼', k: 'child-hw' }, { t: '不肯跟我说话', k: 'child-quiet' }]\n  },\n  'child-hw': {\n    say: ['每天都要吼——那问题可能不在作业，在这个\"每天\"上。', '吼是有效的，但代价是你们俩都在耗。',\n      '要不要看看有没有别的办法？'],\n    chips: [{ t: '好，帮我理理', k: 'sort', coach: true }, { t: '算了，先这样吧', k: 'x-rest' }]\n  },\n  'child-quiet': {\n    say: ['他不说，不一定是没话说。', '有可能是他试过说，结果被否掉了。',\n      '你最近一次听到他主动说点什么，是什么时候？'],\n    chips: [{ t: '想不起来了', k: 'sort', coach: true }]\n  },\n  'self': {\n    say: ['跟自己有关。', '这挺重要的——很多人说了一圈，最后才敢承认其实是自己的事。', '你想说说吗？'],\n    chips: [{ t: '我觉得我把日子过成这样', k: 'selfblame' }, { t: '我也不知道怎么了', k: 't-vague' }]\n  },\n  'mil-sort': {\n    say: ['同住这件事，难的不是合不来，是没有边界。', '先不急着改善关系。',\n      '我最想知道的是：哪几件事是你绝对不能让步的？'],\n    chips: [{ t: '孩子怎么教', k: 'mil-a', coach: true }, { t: '家里的事谁做主', k: 'mil-a', coach: true }]\n  },\n  'mil-a': {\n    say: ['好，这是原则事——原则事不谈感受，谈安排。', '而且最好不是你去说，是你丈夫去说。',\n      '要不要我帮你理一下，怎么跟他开这个口？'],\n    chips: [{ t: '好，帮我理理', k: 'husband-sort', coach: true }]\n  },\n  'child-sort': {\n    say: ['\"怎么说都不听\"——这句话里有两个信息。', '一是你已经说过很多次了；二是他现在对你说的话有免疫了。',\n      '我们先做一件事：这周只挑一个行为改，其他先放。', '你想先挑哪个？'],\n    chips: [{ t: '写作业', k: 'child-hw', coach: true }, { t: '看手机', k: 'child-hw', coach: true }]\n  },\n\n  'company': {\n    say: ['行，那就先不解决它。', '你说，我听着。']\n  }\n};\n\n/* ⚠ 与原型的**唯一**一处结构性偏差（显式登记，不藏）：\n *   原型里多处芯片写 k:'company'，但 S 表里**没有** S['company'] —— 是悬空键。\n *   它的实际行为会掉进 freeform 兜底，再问一遍「这件事在哪一刻最让你难受？」，形成软循环。\n *   本移植给 company 一个明确收束，文案直接取自原型确认卡「先不用，就想说说」的 onNo 支线\n *   （['行。那就先不解决它。','你说，我听着。']），未自创一字。\n *   tools/__tests__/x-ximi.test.js 里有一条用例专门锁定\"原型 36 键全覆盖 + 仅多这一条\"。 */\n\n/* ---------- 轻确认卡（原型 freeform 的 asksHow 支线） ---------- */\nconst COACH_CONFIRM = {\n  lead: ['听见了。这件事你想说的，我大概明白。'],\n  text: '要不要我帮你理一理？我会问几个具体的，然后给你一个能用的做法。',\n  yes: '好，帮我理理',\n  no: '先不用，就想说说',\n  yesGo: 'sort',\n  noGo: '__keep-friend'\n};\n\n/* ---------- 自由输入的关键词分流（原型 freeform，逐条照抄） ----------\n * 顺序即优先级：asksHow → 婆婆 → 孩子 → 老公 → 累 → 兜底\n * crisis 不在此表（红线：走 modules/crisis.js 的前置过滤） */\nconst FREE_RE = {\n  asksHow: /怎么办|该不该|怎么解决|有什么办法|怎么才能|如何是好|救我/,\n  sleepy: /睡不着|失眠|半夜醒/,\n  tired: /累|烦|难受|委屈|撑不住|崩溃|想哭/,\n  husband: /老公|丈夫|他|伴侣/,\n  mil: /婆婆|婆家/,\n  child: /孩子|儿子|女儿|娃/\n};\n\n/* 自由输入 → 节点键（不含 asksHow，见 route） */\nfunction routeFree(text) {\n  const t = String(text || '');\n  if (FREE_RE.mil.test(t)) return 'mil-sort';\n  if (FREE_RE.child.test(t)) return 'child-sort';\n  if (FREE_RE.husband.test(t)) return 'husband-sort';\n  if (FREE_RE.tired.test(t)) return '__tired-free';\n  return '__fallback';\n}\n\n/* 自由输入的**完整**分流，顺序严格照原型 freeform：\n *   睡不好 → 问怎么办 → 婆婆 → 孩子 → 老公 → 累 → 兜底\n * 返回：\n *   { k: '节点键' }        直接走该节点\n *   { confirm: true }     闺蜜模式下问「要不要帮你理一理」→ 轻确认卡\n * 危机不在本表：红线，由页面用 modules/crisis 在**最前面**拦（原型也是第一个判断）。\n */\nfunction route(text, mode) {\n  const t = String(text || '');\n  if (FREE_RE.sleepy.test(t)) return { k: '__sleepy' };\n  if (FREE_RE.asksHow.test(t)) return mode === 'friend' ? { confirm: true } : { k: 'sort' };\n  return { k: routeFree(t) };\n}\n\n/* ---------- 演练：按你发的话选他的一种反应 + 点评 ----------\n * 逐条照抄原型 drillReply（防御式 / 示弱式 / 沉默式三套） */\nconst DRILL = {\n  defensive: {\n    re: /你总是|你从来|你每次都|凭什么|你就不能|为什么你/,\n    role: '你又来了。\\n我上班一天回来，你就不能让我清静会儿？',\n    review: [\n      '（回到我）刚才那句，我作为他会立刻竖起来——因为开头是\"你总是\"。',\n      '这三个字一出来，后面说什么他都听不见了。',\n      '换一个开头：只说这一次、只说一件事，从\"我\"起头。',\n      '比如：「昨天你答应孩子的事没做到，我一个人应付了一晚上，挺难的。」',\n      '再来一次？'\n    ]\n  },\n  soft: {\n    re: /我|觉得|希望|有点|挺/,\n    role: '……我没说不做啊。\\n你别什么事都上纲上线行不行？',\n    review: [\n      '（回到我）这次他没炸，但开始躲了——\"上纲上线\"是他把话题推开的方式。',\n      '这时候别追着讲道理，把话题拉回具体的一件事：',\n      '「我不是说你这个人的问题。就是昨天那一件——你答应了的。」',\n      '一次只谈一件。他才能接得住。',\n      '再来一次？'\n    ]\n  },\n  silent: {\n    re: null,\n    role: '嗯。\\n（他没说话，低头看手机）',\n    review: [\n      '（回到我）他沉默了。沉默不是同意，是在等这件事过去。',\n      '沉默的时候，加一句\"邀请\"会好一点——',\n      '「我不是要吵，我就是想让你知道我一个人有点扛不住。」',\n      '再来一次？'\n    ]\n  }\n};\n\nfunction drillReply(text) {\n  const t = String(text || '');\n  if (DRILL.defensive.re.test(t)) return DRILL.defensive;\n  if (DRILL.soft.re.test(t)) return DRILL.soft;\n  return DRILL.silent;\n}\n\n/* 演练收尾的两个选项（原型 runDrill 尾部 askChips） */\nconst DRILL_CHIPS = [\n  { t: '好，再来一次', k: 'drill-again', coach: true },\n  { t: '记下来，我明天试试', k: 'drill-save', coach: true }\n];\n\n/* ---------- 按小时问候（原型 greetByHour，逐字照抄） ---------- */\nfunction greetByHour(hour) {\n  const h = typeof hour === 'number' ? hour : new Date().getHours();\n  if (h >= 5 && h < 11) return '早。今天不用起得很急。';\n  if (h >= 11 && h < 14) return '中午了，先歇一会儿。';\n  if (h >= 14 && h < 18) return '下午了，还撑得住吗？';\n  if (h >= 18 && h < 21) return '天快黑了，今天可以到这儿。';\n  if (h >= 21 && h < 24) return '这会儿安静下来了。';\n  return '还没睡。我在。';\n}\n\n/* 开场白（原型 init 里的 setTimeout 那句） */\nconst OPENING = '我在。\\n今天想从哪儿说起都行——或者直接点下面一个词。';\n\n/* 两组静态芯片（首页第一屏）——原型是写死在 HTML 里的「先说说」/「想解决点什么」 */\nconst CHIPS_FRIEND = [\n  { t: '今天有点累', k: 'tired' },\n  { t: '有件事堵着', k: 't-specific' },\n  { t: '就想找人说说话', k: 't-company' }\n];\nconst CHIPS_COACH = [\n  { t: '有件事想理一理', k: 'sort', coach: true },\n  { t: '帮我出出主意', k: 'advice', coach: true },\n  { t: '一件事卡了好久', k: 'longtime', coach: true }\n];\n\n/* 模式切换时的应答（原型 switchMode 的 byUser 分支） */\nconst MODE_SAY = {\n  coach: ['好，那我们把这件事理清楚。'],\n  friend: ['好，先不想办法了。你说，我听着。']\n};\nconst PLACEHOLDER = { friend: '想到哪，说到哪…', coach: '说说具体的情况…' };\n\n/* 陪伴承接（原型 companionNudge，全场只出现一次） */\nconst NUDGE = {\n  text: '另外说一句——这件事如果想找个真人一起走，陪伴师每周固定时间在。你在这里说过的，她都接得上，不用从头讲。',\n  yes: '看看她是谁',\n  no: '先不用'\n};\n\nmodule.exports = {\n  BRANCHES: BRANCHES,\n  FREE_NODES: FREE_NODES,\n  COACH_CONFIRM: COACH_CONFIRM,\n  FREE_RE: FREE_RE,\n  routeFree: routeFree,\n  route: route,\n  DRILL: DRILL,\n  drillReply: drillReply,\n  DRILL_CHIPS: DRILL_CHIPS,\n  greetByHour: greetByHour,\n  OPENING: OPENING,\n  CHIPS_FRIEND: CHIPS_FRIEND,\n  CHIPS_COACH: CHIPS_COACH,\n  MODE_SAY: MODE_SAY,\n  PLACEHOLDER: PLACEHOLDER,\n  NUDGE: NUDGE\n};\n","pages/cdetail/cdetail.js":"const toast = require('../../behaviors/toast');\nconst api = require('../../utils/api');\nconst demo = require('../../utils/demo');\nPage({\n  behaviors: [toast],\n  data: {\n    c: {}, slots: [], pickedIdx: -1, slotTxt: '待选择', payShow: false, paid: false\n  },\n  onLoad() {\n    const id = require('../../stores/user').get('counselorId') || 'c1';\n    api.fetchCounselorDetail(id).then(c => {\n      this._c = c;\n      this.setData({ c, slots: c.slots });\n    });\n  },\n  pickSlot(e) {\n    const i = +e.currentTarget.dataset.i;\n    this.setData({ pickedIdx: i });\n    require('../../stores/user').set({ pickedSlot: this.data.slots[i] });\n  },\n  openPay() {\n    this.setData({\n      paid: false,\n      slotTxt: this.data.pickedIdx >= 0 ? this.data.slots[this.data.pickedIdx] : this.data.slots[0] + '（默认）',\n      payShow: true\n    });\n  },\n  closePay() { this.setData({ payShow: false }); },\n  doPay() {\n    /* 真实前端：api.createOrder(id, slot) → wx.requestPayment(payParams)\n       mock 模式直接走成功态演示 */\n    const slot = require('../../stores/user').get('pickedSlot') || this.data.slots[0];\n    api.createOrder(this.data.c.id, slot).then(() => {\n      this.setData({ paid: true });\n      this._t = setTimeout(() => {\n        this.setData({ payShow: false });\n        this.showToast(demo.t('payDone'));\n      }, 2100);\n    });\n  },\n  onUnload() { clearTimeout(this._t); }\n});\n","pages/chat/chat.js":"/* 西米（对话页 · tab0 · 打开即对话）\n *\n * 来源：甲方排版基准原型。三处要点：\n *   1) 剧本引擎在 modules/ximi-script（36 分支纯数据），本文件只做「渲染 + 时序」\n *   2) **危机链路原样保留**：crisis.isCrisis 前置 → crisis.REPLY → 卡 + calmOk 延迟解锁。\n *      原型里的危机文案与热线号码（12356）**未移植**，一律走项目基线（modules/crisis.js）\n *   3) 布局用 flex 兄弟：滚动区在输入条**上方**结束。\n *      原型是 .composer 绝对定位盖在滚动区上（最后 74px 永久遮住，末排选项点不到）——\n *      那个缺陷在真实小程序里必须不发生，所以这里从结构上避开，而不是靠 padding 兜。\n *\n * 键盘避让（COMPAT 铁律 7）：adjust-position=false + bindkeyboardheightchange，\n *   键盘高度直接改 chat-root 的 padding-bottom，输入条仍是 flex 兄弟，不留遮挡层。\n */\nconst SC = require('../../modules/ximi-script');\nconst crisis = require('../../modules/crisis');\nconst avatars = require('../../utils/avatars');\nconst ximi = require('../../stores/ximi');\nconst user = require('../../stores/user');\nconst toast = require('../../behaviors/toast');\nconst tab = require('../../behaviors/tab');\n\nPage({\n  behaviors: [toast, tab(0)],\n  data: {\n    greet: SC.greetByHour(),\n    heroImg: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/art-feat.jpg',\n    mode: 'friend',\n    ph: SC.PLACEHOLDER.friend,\n    msgs: [],\n    typing: false,\n    chipsFriend: SC.CHIPS_FRIEND,\n    chipsCoach: SC.CHIPS_COACH,\n    nudge: null,\n    inputVal: '',\n    kbH: 0,\n    scrollTo: '',\n    crisisShow: false,\n    calmOk: false,\n    ov: '',\n    ovShow: false,\n    avStyle: ''\n  },\n\n  onLoad() {\n    this._id = 0;\n    this._timers = [];\n    this._busy = false;\n    this._drill = false;\n    this._nudged = false;\n    this._dead = false;\n    /* 用户气泡头像：读共享态（我的页换头像后回来要跟着变） */\n    this.setData({ avStyle: this.avOf(ximi.get('avatar')), heroImg: this.heroByHour() });\n    this.later(() => this.push({ type: 'msg', role: 'ai', text: SC.OPENING }), 800);\n  },\n  onShow() {\n    this.syncTab();\n    const i = ximi.get('avatar');\n    if (this._avIdx !== i) { this._avIdx = i; this.setData({ avStyle: this.avOf(i) }); }\n    /* 危机卡解锁定时器防丢：拨号/切后台可能吃掉一次 later——回见补排（提审线二轮修复同款） */\n    if (this.data.crisisShow && !this.data.calmOk) this.later(() => this.setData({ calmOk: true }), crisis.TIMING.calm);\n  },\n  onUnload() { this._dead = true; this.clearTimers(); },\n\n  /* 大景按小时换：白天=雾山，入夜=月色（同一批本地资产） */\n  heroByHour() {\n    const h = new Date().getHours();\n    return (h >= 6 && h < 18) ? 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/art-feat.jpg' : 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/art-sleep.jpg';\n  },\n\n  avOf(i) { return (avatars.list()[i] || avatars.list()[0]).style; },\n  later(fn, ms) {\n    const id = setTimeout(() => { if (!this._dead) fn(); }, ms);\n    this._timers.push(id);\n    return id;\n  },\n  clearTimers() { this._timers.forEach(clearTimeout); this._timers = []; this._busy = false; },\n  wait(ms) { return new Promise(res => this.later(res, ms)); },\n  scrollBottom() {\n    const last = this.data.msgs[this.data.msgs.length - 1];\n    this.setData({ scrollTo: this.data.typing ? 'mT' : ('m' + (last ? last.id : 0)) });\n  },\n\n  /* ---------- 渲染原语 ---------- */\n  push(item) {\n    const msgs = this.data.msgs;\n    const m = Object.assign({ id: this._id++ }, item);\n    /* 同一方连续发言只显示一次头像（原型 hideAv 同义） */\n    if (m.type === 'msg' && m.role === 'ai' && msgs.length\n      && msgs[msgs.length - 1].type === 'msg' && msgs[msgs.length - 1].role === 'ai') m.hideAv = true;\n    msgs.push(m);\n    this.setData({ msgs: msgs, typing: false });\n    this.scrollBottom();\n    return m;\n  },\n  say(lines, isRole) {\n    return lines.reduce((p, line) => p.then(() => new Promise(res => {\n      this.setData({ typing: true });\n      this.scrollBottom();\n      this.later(() => {\n        this.push({ type: 'msg', role: isRole ? 'role' : 'ai', text: line });\n        this.later(res, 180);\n      }, 430 + Math.min(line.length * 22, 900));\n    })), Promise.resolve());\n  },\n\n  /* ---------- 剧本 runner ---------- */\n  runBranch(key) {\n    if (this._busy) return Promise.resolve();\n    this._busy = true;\n    const node = SC.BRANCHES[key] || SC.FREE_NODES[key];\n    const done = (v) => { this._busy = false; return v; };\n    if (!node) return done(this.runBranch('__fallback'));\n\n    let chain = Promise.resolve();\n    /* coach 节点：先静默切模式 + 补一句（原型 S['sort'] 的 if mode!=='coach'） */\n    if (node.coach && this.data.mode !== 'coach') {\n      chain = chain.then(() => this.setMode('coach')).then(() => this.say(SC.MODE_SAY.coach));\n    }\n    if (node.say) chain = chain.then(() => this.say(node.say));\n    if (node.wait) chain = chain.then(() => this.wait(node.wait));\n    if (node.drill) chain = chain.then(() => { this._drill = true; });\n    if (node.drillEnd) chain = chain.then(() => { this._drill = false; });\n    if (node.lamp) chain = chain.then(() => this.lightLamp(node.toast));\n    if (node.toast && !node.lamp) chain = chain.then(() => this.showToast(node.toast));\n    if (node.open) chain = chain.then(() => this.setData({ ov: node.open, ovShow: true }));\n    if (node.nudge) chain = chain.then(() => this.showNudge());\n    if (node.chips) chain = chain.then(() => this.push({ type: 'chips', items: node.chips }));\n    return chain.then(done, done);\n  },\n\n  /* ---------- 模式 ---------- */\n  setMode(m) {\n    this.setData({ mode: m, ph: SC.PLACEHOLDER[m] });\n    return Promise.resolve();\n  },\n  onMode(e) {\n    const m = e.currentTarget.dataset.m;\n    if (m === this.data.mode || this._busy) return;\n    this._busy = true;\n    const done = () => { this._busy = false; };\n    this.setMode(m).then(() => this.say(SC.MODE_SAY[m])).then(done, done);\n  },\n\n  /* ---------- 用户输入 ---------- */\n  onInput(e) { this.setData({ inputVal: e.detail.value }); },\n  onKb(e) { this.setData({ kbH: (e.detail && e.detail.height) || 0 }); },\n  onBlur() { this.setData({ kbH: 0 }); },\n  onInputFocus() { this.scrollBottom(); },\n\n  send() {\n    const v = (this.data.inputVal || '').trim();\n    if (!v) return;\n    if (this._busy) return;\n    this.setData({ inputVal: '' });\n    this.push({ type: 'msg', role: 'user', text: v });\n    /* 红线：危机词最优先，且不进剧本表 */\n    if (crisis.isCrisis(v)) { this.triggerCrisis(); return; }\n    /* 演练中：任何话都当\"你说的第一句\" */\n    if (this._drill) { this.runDrill(v); return; }\n    const r = SC.route(v, this.data.mode);\n    if (r.confirm) { this.askCoach(); return; }\n    this.runBranch(r.k);\n  },\n\n  /* 静态芯片（首屏「先说说」/「想解决点什么」） */\n  onChip(e) {\n    const k = e.currentTarget.dataset.k;\n    const t = e.currentTarget.dataset.t;\n    if (this._busy) return;\n    this.push({ type: 'msg', role: 'user', text: t });\n    this.runBranch(k);\n  },\n  /* 剧本里给出的选项行 */\n  onPick(e) {\n    const gid = e.currentTarget.dataset.gid;\n    const k = e.currentTarget.dataset.k;\n    const t = e.currentTarget.dataset.t;\n    const msgs = this.data.msgs.filter(m => !(m.type === 'chips' && m.id === gid));\n    this.setData({ msgs: msgs });\n    this.push({ type: 'msg', role: 'user', text: t });\n    this.runBranch(k);\n  },\n\n  /* ---------- 轻确认卡（原型 confirmCard） ---------- */\n  askCoach() {\n    this._busy = true;\n    const done = () => { this._busy = false; };\n    this.say(SC.COACH_CONFIRM.lead).then(() => {\n      this.push({ type: 'confirm', text: SC.COACH_CONFIRM.text, yes: SC.COACH_CONFIRM.yes, no: SC.COACH_CONFIRM.no });\n      done();\n    }, done);\n  },\n  onConfirmYes(e) {\n    const id = e.currentTarget.dataset.gid;\n    this.setData({ msgs: this.data.msgs.filter(m => !(m.type === 'confirm' && m.id === id)) });\n    /* 静默切教练（byUser=false 不说话），再进 sort。\n       注意：这里**不能**先置 _busy —— runBranch 首行就查 _busy，先置了它会直接返回，\n       卡片消失而教练分支不启动（真机取图时抓到的 bug）。busy 交给 runBranch 自己管。 */\n    this.setMode('coach').then(() => this.runBranch(SC.COACH_CONFIRM.yesGo));\n  },\n  onConfirmNo(e) {\n    const id = e.currentTarget.dataset.gid;\n    this.setData({ msgs: this.data.msgs.filter(m => !(m.type === 'confirm' && m.id === id)) });\n    this._busy = true;\n    const done = () => { this._busy = false; };\n    this.say(SC.FREE_NODES[SC.COACH_CONFIRM.noGo].say).then(done, done);\n  },\n\n  /* ---------- 冲突演练（原型 runDrill） ---------- */\n  runDrill(text) {\n    const r = SC.drillReply(text);\n    this._busy = true;\n    const done = () => { this._busy = false; };\n    this.setData({ typing: true });\n    this.scrollBottom();\n    this.later(() => {\n      this.push({ type: 'msg', role: 'role', text: r.role });\n      this.later(() => {\n        this.say(r.review).then(() => {\n          this.push({ type: 'chips', items: SC.DRILL_CHIPS });\n          done();\n        }, done);\n      }, 420);\n    }, 760);\n  },\n\n  /* ---------- 点亮一盏灯（与变化页共用计数） ---------- */\n  lightLamp(msg) {\n    ximi.lightOne();\n    if (msg) this.showToast(msg);\n  },\n\n  /* ---------- 陪伴承接（全场只出现一次） ---------- */\n  showNudge() {\n    if (this._nudged) return;\n    this._nudged = true;\n    this.push({ type: 'nudge', text: SC.NUDGE.text, yes: SC.NUDGE.yes, no: SC.NUDGE.no });\n  },\n  onNudgeYes(e) {\n    const id = e.currentTarget.dataset.gid;\n    this.setData({ msgs: this.data.msgs.filter(m => !(m.type === 'nudge' && m.id === id)) });\n    this.setData({ ov: 'comp', ovShow: true });\n    this.setTabHidden(true);\n  },\n  onNudgeNo(e) {\n    const id = e.currentTarget.dataset.gid;\n    this.setData({ msgs: this.data.msgs.filter(m => !(m.type === 'nudge' && m.id === id)) });\n  },\n\n  /* ---------- 浮层（西米页会用到：呼吸 / 书写 / 陪伴） ---------- */\n  openOv(e) { this.setData({ ov: e.currentTarget.dataset.kind, ovShow: true }); this.setTabHidden(true); },\n  closeOv() { this.setData({ ovShow: false }); this.setTabHidden(false); },\n  onOvLamp(e) { this.lightLamp(e.detail.toast); },\n  /* 书写浮层写完 → 往对话里回一句（原型 setTimeout 700 后 bubble） */\n  onOvSaid(e) {\n    this._busy = true;\n    const done = () => { this._busy = false; };\n    this.later(() => this.say([e.detail.text]).then(done, done), 700);\n  },\n\n  /* ---------- 危机（红线：逻辑与文案一律不动） ---------- */\n  triggerCrisis() {\n    this._busy = true;\n    this.setData({ typing: true });\n    this.scrollBottom();\n    this.later(() => {\n      this.push({ type: 'msg', role: 'ai', text: crisis.REPLY });\n      this.setData({ crisisShow: true, calmOk: false });\n      this._busy = false;\n      this.later(() => this.setData({ calmOk: true }), crisis.TIMING.calm);\n    }, crisis.TIMING.typing);\n  },\n  closeCrisis() {\n    if (!this.data.calmOk) return;\n    this.setData({ crisisShow: false });\n  },\n  crisisConsult() {\n    this.setData({ crisisShow: false });\n    this.navConsult();\n  },\n  /* 真人陪伴入口（首页轻入口 / 浮层底部按钮）统一走这里；\n     当前是演示页（后端 consultants 无读取接口），保持原跳转 */\n  navConsult() { require('../../utils/nav').go('/pages/consultants/consultants'); },\n\n  onScroll(e) {\n    const over = e.detail.scrollTop > 8;\n    if (over !== this.data.scrolled) this.setData({ scrolled: over });\n  }\n});\n","pages/consultants/consultants.js":"const tab = require('../../behaviors/tab');\nconst api = require('../../utils/api');\nPage({\n  behaviors: [tab(2)],\n  onShow() { this.syncTab(); },\n  data: { list: [], direction: '婚姻信任修复' },\n  onLoad() {\n    api.fetchCounselors().then(list => this.setData({ list }));\n  },\n  goDetail(e) {\n    require('../../stores/user').set({ counselorId: e.currentTarget.dataset.id });\n    wx.navigateTo({ url: '/pages/cdetail/cdetail' });\n  }\n});\n","pages/content/content.js":"const toast = require('../../behaviors/toast');\nconst demo = require('../../utils/demo');\nconst CD = require('../../utils/content-data');\nconst tab = require('../../behaviors/tab');\nconst WD = ['日','一','二','三','四','五','六'];\nPage({\n  behaviors: [toast, tab(1)],\n  data: {\n    weekRange: '', nbCount: 3,\n    columns: CD.columns, shares: CD.shares, books: CD.books, past: CD.past,\n    jnlShow: false, jnlSent: false, jnlText: '', chipIdx: -1,\n    chips: ['平静','有点累','说不清','想被夸夸','一点开心'],\n    jnlDate: '', jnlDateFull: ''\n  },\n  onLoad() {\n    const now = new Date();\n    const dow = (now.getDay() + 6) % 7;\n    const f = d => (d.getMonth() + 1) + '月' + d.getDate() + '日';\n    const mon = new Date(now); mon.setDate(now.getDate() - dow);\n    const sun = new Date(now); sun.setDate(now.getDate() - dow + 6);\n    this.setData({\n      weekRange: f(mon) + ' – ' + f(sun),\n      jnlDate: (now.getMonth() + 1) + '月' + now.getDate() + '日 周' + WD[now.getDay()],\n      jnlDateFull: (now.getMonth() + 1) + '月' + now.getDate() + '日 · 星期' + WD[now.getDay()]\n    });\n  },\n  onShow() {\n    this.syncTab();\n  },\n  openJnl() { this.setData({ jnlShow: true, jnlSent: false }); },\n  closeJnl() { this.setData({ jnlShow: false }); },\n  pickChip(e) { this.setData({ chipIdx: +e.currentTarget.dataset.i }); },\n  onJnlText(e) { this.setData({ jnlText: e.detail.value }); },\n  sendJnl() {\n    if (!this.data.jnlText.trim()) { this.showToast('先写一句吧，哪怕一句也好'); return; }\n    this.setData({ jnlSent: true, nbCount: 4 });\n    this.showToast('已放进你的手记');\n  },\n  closeCrisis() {\n    if (!this.data.calmOk) return;\n    this.setData({ crisisShow: false });\n  },\n  crisisConsult() {\n    this.setData({ crisisShow: false });\n    wx.navigateTo({ url: '/pages/consultants/consultants', fail: () => {} });\n  },\n  onShareAppMessage() {\n    /* 分享公开内容（本周主题/文章卡），不带任何用户手记数据 */\n    return {\n      title: '每日成长 · ' + (this.data.columns[0] ? this.data.columns[0].title : '把心事说给懂你的人听'),\n      path: '/pages/content/content',\n      imageUrl: '/images/xixi-3d.jpg'\n    };\n  },\n  onShareTimeline() {\n    return { title: '西米 · 每日成长 —— 把心事说给懂你的人听', query: '', imageUrl: '/images/xixi-3d.jpg' };\n  },\n  toastArt() { this.showToast(demo.t('article')); },\n  toastCol() { this.showToast(demo.t('column')); },\n  toastBook() { this.showToast(demo.t('book')); }\n});\n","pages/grow/grow.js":"/* 变化页（2026-10-09 新建 · 甲方排版基准）\n * 结构：顶栏（第 N 天）→ 雾光灯海 → 三数格 → 生成月度灯海图 → 最近时间线\n *\n * 灯海与灯数：**和对话页/疗愈页共用 stores/ximi.litLamps**\n *   —— 在别处点亮一盏，回到本页会看到那一盏亮起来（甲方决议「记录即点亮」）。\n *   位置/大小/闪烁节奏按原型是随机生成（每次进入重排），故本页自己造。\n * 数值全部是演示值（后端无灯海/话术卡域），见 utils/grow-data 头部说明。\n */\nconst D = require('../../utils/grow-data');\nconst ximi = require('../../stores/ximi');\nconst toast = require('../../behaviors/toast');\nconst tab = require('../../behaviors/tab');\n\nPage({\n  behaviors: [toast, tab(2)],\n  data: {\n    head: D.HEAD,\n    lamp: D.LAMP,\n    lamps: [],\n    lit: D.LAMP.on,\n    stats: D.STATS,\n    poster: D.POSTER,\n    secRecent: D.SEC_RECENT,\n    timeline: D.TIMELINE,\n    pct: 0\n  },\n  onLoad() { this.buildLamps(ximi.get('litLamps')); },\n  onShow() {\n    this.syncTab();\n    const lit = ximi.get('litLamps');\n    if (lit !== this.data.lit) this.buildLamps(lit);\n  },\n\n  /* 46 盏灯：位置/大小/闪烁随机（同原型）；前 lit 盏为亮 */\n  buildLamps(lit) {\n    const total = D.LAMP.total;\n    const lamps = [];\n    for (let i = 0; i < total; i++) {\n      const on = i < lit;\n      const size = on ? 12 + Math.random() * 18 : 8;\n      lamps.push({\n        i: i,\n        on: on,\n        style: 'left:' + (6 + Math.random() * 88).toFixed(2) + '%;'\n          + 'top:' + (10 + Math.random() * 66).toFixed(2) + '%;'\n          + 'width:' + size.toFixed(1) + 'rpx;height:' + size.toFixed(1) + 'rpx;'\n          + 'animation-duration:' + (2.4 + Math.random() * 3).toFixed(2) + 's;'\n          + 'animation-delay:' + (Math.random() * 2).toFixed(2) + 's'\n      });\n    }\n    this.setData({ lamps: lamps, lit: lit, pct: Math.min(100, Math.round(lit / total * 100)) });\n  },\n\n  /* 生成海报：原型是 toast 两连 + 点亮一盏（真海报未接，登记待办） */\n  onPoster() {\n    this.showToast(D.POSTER.toast1);\n    this._t = setTimeout(() => {\n      this.showToast(D.POSTER.toast2);\n      if (ximi.get('litLamps') < D.LAMP.total) this.buildLamps(ximi.lightOne());\n    }, 1400);\n  },\n  onTimeline() { this.showToast('完整记录待接 · 后端暂无灯海域'); }\n});\n","pages/heal/heal.js":"/* 疗愈页（2026-10-09 新建 · 甲方排版基准）\n * 结构：顶栏 → 承接条 → 练一练（2×2 类目，开四个练习浮层）→ 学一学（分类 + 3 门课）\n * 数据：utils/heal-data（甲方原型逐字）\n * 交互：类目开浮层；浮层内的动作通过 lamp 事件 → stores/ximi 灯数 +1（变化页读同一份）\n */\nconst D = require('../../utils/heal-data');\nconst ximi = require('../../stores/ximi');\nconst toast = require('../../behaviors/toast');\nconst tab = require('../../behaviors/tab');\n\nPage({\n  behaviors: [toast, tab(1)],\n  data: {\n    hero: D.HERO,\n    head: D.HEAD,\n    rec: D.REC,\n    secPractice: D.SEC_PRACTICE,\n    cats: D.CATS,\n    secCourse: D.SEC_COURSE,\n    filters: D.COURSE_FILTERS,\n    filterIdx: 0,\n    courses: D.COURSES,\n    ov: '',\n    ovShow: false\n  },\n  onShow() { this.syncTab(); },\n\n  openOv(e) {\n    this.setData({ ov: e.currentTarget.dataset.kind, ovShow: true });\n    this.setTabHidden(true);\n  },\n  closeOv() { this.setData({ ovShow: false }); this.setTabHidden(false); },\n\n  /* 浮层里发生了一次「记录」（呼吸/书写/OH 卡）→ 点亮一盏灯 */\n  onLamp(e) {\n    ximi.lightOne();\n    this.showToast(e.detail.toast || '已记录 · 点亮一盏灯');\n  },\n  /* 书写浮层要往对话里回一句：疗愈页看不到对话，改用 toast 提示它已记下 */\n  onSaid() {\n    this.showToast('已记下 · 去西米那儿看看它怎么回你');\n  },\n\n  onFilter(e) {\n    this.setData({ filterIdx: e.currentTarget.dataset.i });\n  },\n  /* 课程购买未接（后端无课程域，甲方只给了 3 门内容）——登记待办，不做假流程 */\n  onCourse() {\n    this.showToast('课程详情待接 · 后端暂无课程域');\n  }\n});\n","pages/home/home.js":"const mood = require('../../utils/mood');\nconst petFaceB = require('../../behaviors/pet-face');\nconst demo = require('../../utils/demo');\nconst api = require('../../utils/api');\nconst toast = require('../../behaviors/toast');\nconst tab = require('../../behaviors/tab');\nconst nav = require('../../utils/nav');\nconst POKES = ['西米蹭了蹭你 ◡̈','西米绕着你转了一圈','被你戳得晃了晃','西米眨了眨眼','再戳我就要飘走啦','西米听见了你的召唤','我在，一直都在'];\nconst MOOD_REPLY = { '平静':'平静很好 · 今天也稳稳的','委屈':'委屈就说出来 · 西米听着','焦虑':'先深呼吸一下 · 我在','烦躁':'烦躁倒给我 · 就不硌你了','难过':'抱抱你 · 难过不用藏' };\nPage({\n  behaviors: [toast, tab(0), petFaceB('xFace')],\n  data: {\n    bubTxt: '', xFace: 'base', careOn: false,\n    qTxt: '', qAu: '', qImg: '', qTxtShare: '',\n    gcDay: '', gcYM: '', todayMood: '', todayFace: '', streak: 6,\n    shareShow: false, entering: false,\n    /* 双卡内容：语义留在页（内核），外观在 x-duo-cards 积木 —— 换风格不动这里 */\n    duoCards: [\n      { key: 'meditate', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/scenery-songya.jpg', title: '冥想呼吸', sub: '3 分钟 · 平复情绪' },\n      { key: 'sleep', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/art-sleep.jpg', title: '助眠安睡', sub: '白噪音 · 睡前陪伴' }\n    ]\n  },\n  onLoad() {\n    const h = new Date().getHours();\n    const greet = h < 5 ? '夜深了' : h < 11 ? '早上好' : h < 14 ? '中午好' : h < 18 ? '下午好' : '晚上好';\n    this._bubs = [greet + '呀，{n}～','今天也辛苦啦','想我了就戳戳我','心里有事？说给我听','喝口水，慢慢来','我在呢，不急','今天照顾好自己了吗','风吹过来的时候，我也在'];\n    this._bi = 0;\n    this.renderBub();\n    /* 金句：mock 按日期轮换，真实前端走 GET /api/daily-quote */\n    api.fetchDailyQuote().then(q => {\n      this.setData({ qTxt: '「' + q.text + '」', qAu: q.author, qImg: q.image, qTxtShare: '「' + q.text + '」' });\n    });\n    /* 心情日历 */\n    this._cal = mood.calendar();\n    this.renderGc();\n  },\n  onShow() {\n    this.syncTab();\n    const app = getApp();\n    this.setData({ careOn: require('../../stores/user').get('careOn') });\n    if (app.globalData.justEntered) {\n      app.globalData.justEntered = false;\n      this.setData({ entering: true });\n      this._te = setTimeout(() => this.setData({ entering: false }), 800);\n    }\n    this._tb = setInterval(() => { this._bi = (this._bi + 1) % this._bubs.length; this.renderBub(); }, 5000);\n    this.startIdleFace(4000);\n    this._cal = mood.calendar();\n    this.renderGc();\n  },\n  onUnload() { clearInterval(this._tb); this.stopIdleFace(); clearTimeout(this._te); },\n  onHide() { clearInterval(this._tb); this.stopIdleFace(); },\n  renderBub() { this.setData({ bubTxt: this._bubs[this._bi].replace('{n}', require('../../stores/user').get('nickname') || '小美') }); },\n  renderGc() {\n    const cal = this._cal;\n    const mi = cal.hist[cal.today], n = mi != null ? mood.NAMES[mi] : null;\n    this.setData({\n      gcDay: cal.today, gcYM: cal.ym,\n      todayMood: n || '', todayFace: mood.faceUri(n || mood.NAMES[0]),\n      streak: this._streak7 ? 7 : 6\n    });\n  },\n  pokeXixi() {\n    this.facePoked();\n    this.showToast(POKES[Math.floor(Math.random() * POKES.length)]);\n  },\n  goChat() { nav.go('/pages/chat/chat'); },\n  goMoodcal() { wx.navigateTo({ url: '/pages/moodcal/moodcal' }); },\n  goSleep() { wx.navigateTo({ url: '/pages/sleep/sleep' }); },\n  meditate() { this.showToast(demo.t('meditate')); },\n  /* 双卡选择：积木只报 key，语义分派留在页（内核） */\n  onDuoSelect(e) {\n    const k = e.detail && e.detail.key;\n    if (k === 'meditate') this.meditate();\n    else if (k === 'sleep') this.goSleep();\n  },\n  openShare() { this.setData({ shareShow: true }); },\n  /* 转发：默认带金句文案 */\n  onShareAppMessage() {\n    return {\n      title: this.data.qTxt + ' —— 西米 · AI情感陪伴',\n      path: '/pages/home/home',\n      imageUrl: this.data.qImg\n    };\n  },\n  onShareTimeline() {\n    return { title: this.data.qTxt + ' —— 西米 · AI情感陪伴', query: '', imageUrl: this.data.qImg };\n  },\n  closeShare() { this.setData({ shareShow: false }); },\n  saveShare() { this.setData({ shareShow: false }); this.showToast(demo.t('shareSave')); },\n  noop() {}\n});\n","pages/launch/launch.js":"Page({\n  data: { exiting: false },\n  onLoad() {\n    this._t1 = setTimeout(() => this.setData({ exiting: true }), 2350);\n    this._t2 = setTimeout(() => wx.redirectTo({ url: '/pages/onboard/onboard' }), 2600);\n  },\n  onUnload() { clearTimeout(this._t1); clearTimeout(this._t2); }\n});\n","pages/me/me.js":"/* 我的（2026-10-09 按甲方排版基准重写）\n * 结构：资料头（头像可换）→ 雾光能量卡 → 真人陪伴卡 → 4 行设置 → 两个浮层\n *\n * 与旧版差异（登记进报告）：旧「我的」的年度陪跑会员卡、生理期关怀签在新排版里没有对应位置，\n *   本页不再呈现（旧版在 git 历史里，未丢）。\n * 头像：选中的索引写 stores/ximi，对话页 onShow 读同一份 → 换完对话里的头像同步变。\n * 数值：全部按原型（688/年、1500 能量、932 已用），与后端 ENERGY_MAX=100 的冲突见 utils/me-data 头部。\n */\nconst D = require('../../utils/me-data');\nconst avatars = require('../../utils/avatars');\nconst ximi = require('../../stores/ximi');\nconst user = require('../../stores/user');\nconst toast = require('../../behaviors/toast');\nconst tab = require('../../behaviors/tab');\n\nPage({\n  behaviors: [toast, tab(3)],\n  data: {\n    name: D.PROFILE.name,\n    sub: D.PROFILE.sub,\n    link: D.PROFILE.link,\n    avSrc: '',\n    energy: D.ENERGY,\n    companion: D.COMPANION,\n    rows: D.ROWS,\n    avShow: false,\n    compShow: false\n  },\n  onShow() {\n    this.syncTab();\n    this.render();\n  },\n  render() {\n    const i = ximi.get('avatar');\n    if (this._av !== i || !this.data.avSrc) {\n      this._av = i;\n      this.setData({ avSrc: avatars.srcOf(avatars.NAMES[i]) || avatars.srcOf(avatars.NAMES[0]) });\n    }\n    const nick = user.get('nickname');\n    if (nick && nick !== this.data.name) this.setData({ name: nick });\n  },\n\n  openAvatar() { this.setData({ avShow: true }); this.setTabHidden(true); },\n  closeAvatar() { this.setData({ avShow: false }); this.setTabHidden(false); },\n  onPick(e) {\n    this.render();\n    this.setData({ avShow: false });\n    this.setTabHidden(false);\n    this.showToast(D.OV_AVATAR.toast + e.detail.name);\n  },\n\n  openComp() { this.setData({ compShow: true }); this.setTabHidden(true); },\n  closeComp() { this.setData({ compShow: false }); this.setTabHidden(false); },\n  onConsult() {\n    this.setData({ compShow: false });\n    require('../../utils/nav').go('/pages/consultants/consultants');\n  },\n\n  /* 设置行：第 1 行换头像；其余三行原型无行为，本轮 toast 占位（登记待办） */\n  onRow(e) {\n    const k = e.currentTarget.dataset.k;\n    if (k === 'avatar') { this.openAvatar(); return; }\n    const map = { profile: '我的资料', relation: '关系档案', remind: '提醒设置' };\n    this.showToast(map[k] + ' · 待接');\n  },\n  onPay() {\n    this.showToast('能量充值待接 · 后端配额模型未拍板');\n  }\n});\n","pages/moodcal/moodcal.js":"const mood = require('../../utils/mood');\nconst api = require('../../utils/api');\nconst toast = require('../../behaviors/toast');\nconst nav = require('../../utils/nav');\nconst MOOD_REPLY = { '平静':'平静很好 · 今天也稳稳的','委屈':'委屈就说出来 · 西米听着','焦虑':'先深呼吸一下 · 我在','烦躁':'烦躁倒给我 · 就不硌你了','难过':'抱抱你 · 难过不用藏' };\nPage({\n  behaviors: [toast],\n  data: {},\n  onLoad() {\n    const cal = mood.calendar();\n    this._cal = cal;\n    this.setData({\n      monthTitle: cal.monthTitle, weekCap: cal.weekCap,\n      cells: cal.cells, week: cal.week,\n      colors: mood.GCM, colorsArr: Object.keys(mood.GCM).map(k => mood.GCM[k]),\n      faces: mood.NAMES.map(n => mood.faceUri(n)),\n      moods: mood.NAMES,\n      selMood: cal.hist[cal.today],\n      streak: 6\n    });\n  },\n  pickMood(e) {\n    const i = +e.currentTarget.dataset.m;\n    this._cal.hist[this._cal.today] = i;\n    wx.setStorageSync(mood.moodKey(), i);\n    api.saveMood(i);\n    this.setData({ selMood: i, streak: 7 });\n    this.showToast(MOOD_REPLY[mood.NAMES[i]] || '打卡成功');\n  },\n  goBack() { nav.back('/pages/home/home'); }\n});\n","pages/onboard/onboard.js":"/**\n * 首次进入问卷（重写版 v2，2026-10-07）\n *\n * 背景：原实现触发 IDE 模拟器页面构建失败（wx://not-found，20+ 轮实验未定位；\n * 同 IDE 主线项目同路径正常），按工程止损纪律重写本文件。\n * wxml/wxss 沿用 614bffa 已验证版本（视觉与动画类零改动），本 js 严格按其\n * 数据契约实现：step 对象 / selArr 数组 / titleChars / typedTitle / hearts /\n * fxWipe / fxBlinds / pageIn / envOpen / envSealed / envFlutter / envCenter /\n * envFly / wrapOut / safeOn / ctaShake / shakeIdx。\n * 题目走 api.fetchOnboardQuestions()，失败兜底内置题集。\n */\nconst api = require('../../utils/api');\nconst user = require('../../stores/user');\nconst nav = require('../../utils/nav');\n\nconst FALLBACK = [\n  { type: 'multi', max: 3, label: '当前困扰 · 多选，最多 3 项', title: '最近，哪些事让你想找人说说？', sub: '选最接近的就好，之后可改。', skip: '暂时不想说', note: '我在听。',\n    opts: ['伴侣沟通不顺', '婚姻出现变化', '对关系感到不安', '家庭/亲子压力', '情绪起伏大', '工作生活压力大', '失眠、想太多', '孤独、没人理解', '想更了解自己', '只是想说说话'] },\n  { type: 'multi', max: 2, label: '陪伴偏好 · 多选，最多 2 项', title: '你希望西米怎么陪你？', sub: '没有标准答案，我会边聊边调。', skip: '还不确定，先聊聊', note: '慢慢来。',\n    opts: ['先听我说完', '帮我把事理清楚', '帮我看见真实感受', '一起想想怎么办', '提醒我注意安全与边界', '需要时联系真人咨询师', '还不确定，先聊聊'] },\n  { type: 'single', label: '关系阶段 · 单选，可跳过', title: '你目前大致处在哪个阶段？', sub: '只用来更好理解你，不会替你做关系决定。', skip: '暂时不想说', note: '谢谢你愿意说。',\n    opts: ['单身 / 暂无稳定关系', '恋爱 / 稳定交往', '已婚 / 共同生活', '分居、离婚或关系变动中', '情况比较复杂', '暂时不想说'] },\n  { type: 'single', label: '当前情绪 · 单选', title: '此刻感受更接近？', sub: '选最接近的一项即可。', skip: '说不清楚', note: '辛苦了。',\n    opts: ['比较平静', '有些委屈', '焦虑不安', '生气烦躁', '疲惫无力', '难过想哭', '感到绝望', '说不清楚'] },\n  { type: 'name', label: '怎么称呼 · 可选', title: '我可以怎么叫你？', sub: '不用真名，只用于陪伴称呼。', skip: '暂时不设置', note: '很高兴认识你。' }\n];\nconst OB_FX = ['wipe', 'blinds', 'zoom', 'zoom'];\nconst SAFE_MOOD = '感到绝望';\n\nPage({\n  data: {\n    steps: [],\n    cur: 0,\n    step: FALLBACK[0],\n    stepNo: '01', skipTxt: FALLBACK[0].skip, note: FALLBACK[0].note,\n    metaLab: 'CHECKED', maxLab: ' / 3', cnt: 0,\n    ctaHide: false, ctaDis: true, ctaTxt: '继 续', ctaShake: false,\n    selArr: [], name: '', chipOn: false, shakeIdx: -1,\n    titleChars: [], typedTitle: '',\n    envOpen: false, envSealed: false, envFlutter: false, envCenter: false, envFly: false, wrapOut: false,\n    safeOn: false, hearts: [], fxWipe: false, fxBlinds: false, pageIn: '', busy: false\n  },\n\n  onLoad() {\n    this._answers = {};\n    this._sel = [];\n    this._name = '';\n    this._timers = [];\n    api.fetchOnboardQuestions()\n      .then(steps => this.start(steps))\n      .catch(() => this.start(FALLBACK));\n  },\n  onUnload() { this._timers.forEach(t => clearTimeout(t)); },\n  later(fn, ms) { const id = setTimeout(fn, ms); this._timers.push(id); return id; },\n\n  start(steps) {\n    const list = steps && steps.length ? steps : FALLBACK;\n    this.setData({ steps: list });\n    this.loadStep(0, '');\n  },\n\n  /* ---------- 步进渲染（严格输出 wxml 契约字段） ---------- */\n  loadStep(idx, pageIn) {\n    const st = this.data.steps[idx] || FALLBACK[idx];\n    const prev = this._answers[idx] || [];\n    const selArr = (st.opts || []).map(o => prev.indexOf(o) >= 0);\n    this._sel = selArr.map((v, i) => (v ? i : -1)).filter(i => i >= 0);\n    this._name = st.type === 'name' ? (prev[0] || '') : '';\n    clearInterval(this._tw);\n    let titleChars = [];\n    if (idx === 0) titleChars = st.title.split('').map((c, k) => ({ c, d: k * 32 }));\n    this.setData({\n      cur: idx, step: st,\n      stepNo: idx < 9 ? '0' + (idx + 1) : String(idx + 1),\n      skipTxt: st.skip || '跳过', note: st.note || '',\n      metaLab: st.type === 'multi' ? 'CHECKED' : st.type === 'single' ? 'SINGLE CHOICE' : 'OPTIONAL',\n      maxLab: st.type === 'multi' ? ' / ' + st.max : '',\n      cnt: this._sel.length,\n      ctaHide: st.type === 'single',\n      ctaTxt: st.type === 'name' ? '开 启 陪 伴' : '继 续',\n      ctaDis: st.type === 'multi' ? this._sel.length === 0 : st.type === 'name' ? !this._name : false,\n      selArr, name: this._name, chipOn: false, shakeIdx: -1,\n      titleChars, typedTitle: '', pageIn: pageIn || '',\n      envOpen: this._sel.length > 0\n    });\n    if (idx === 3) this.typewrite(st.title);\n    this.later(() => this.setData({ pageIn: '' }), 700);\n  },\n  typewrite(text) {\n    let i = 0;\n    this.setData({ typedTitle: '' });\n    this._tw = setInterval(() => {\n      if (i < text.length) { i++; this.setData({ typedTitle: text.slice(0, i) }); }\n      else clearInterval(this._tw);\n    }, 85);\n  },\n\n  /* ---------- 信封状态 ---------- */\n  envOpenNow() { this.setData({ envOpen: true, envSealed: false }); },\n  envFlutter() {\n    this.setData({ envFlutter: true });\n    this.later(() => this.setData({ envFlutter: false }), 600);\n  },\n  envSeal() {\n    this.setData({ envOpen: false, envSealed: true });\n    this.later(() => this.setData({ envSealed: false }), 520);\n  },\n\n  /* ---------- 选项（wxml: pickOpt data-k） ---------- */\n  pickOpt(e) {\n    if (this.data.busy) return;\n    const k = +e.currentTarget.dataset.k;\n    const st = this.data.steps[this.data.cur];\n    if (st.type === 'single') {\n      const selArr = st.opts.map((o, i) => i === k);\n      this._sel = [k];\n      this._answers[this.data.cur] = [st.opts[k]];\n      this.setData({ selArr, cnt: 1 });\n      this.envFlutter();\n      if (st.opts[k] === SAFE_MOOD) {\n        this.setData({ busy: true });\n        this.later(() => { this.setData({ busy: false, safeOn: true }); }, 520);\n        return;\n      }\n      this.setData({ busy: true });\n      this.later(() => { this.setData({ busy: false }); this.next(); }, 620);\n      return;\n    }\n    const selArr = this.data.selArr.slice();\n    if (selArr[k]) {\n      selArr[k] = false;\n      this._sel = this._sel.filter(i => i !== k);\n    } else {\n      if (this._sel.length >= st.max) {\n        this.setData({ shakeIdx: k });\n        this.later(() => this.setData({ shakeIdx: -1 }), 600);\n        return;\n      }\n      selArr[k] = true;\n      this._sel.push(k);\n      this.envOpenNow();\n    }\n    this._answers[this.data.cur] = this._sel.map(i => st.opts[i]);\n    this.setData({ selArr, cnt: this._sel.length, ctaDis: this._sel.length === 0 });\n  },\n\n  /* ---------- 昵称（wxml: onName/commitName/quickName） ---------- */\n  onName(e) {\n    const v = (e.detail.value || '').trim();\n    this._name = v;\n    this.setData({ name: v, chipOn: false, ctaDis: !v });\n  },\n  commitName() {\n    if (!this.data.name.trim()) return;\n    this.setData({ name: this.data.name.trim() });\n  },\n  quickName() {\n    const on = !this.data.chipOn;\n    this._name = on ? '小美' : '';\n    this.setData({ chipOn: on, name: this._name, ctaDis: !on });\n    if (on) this.envOpenNow();\n  },\n\n  /* ---------- footbar（wxml: ctaTap/skip/goBack） ---------- */\n  ctaTap() {\n    if (this.data.busy) return;\n    const st = this.data.steps[this.data.cur];\n    if (st.type === 'multi' && this._sel.length === 0) { this.shakeCta(); return; }\n    if (st.type === 'name') {\n      if (!this.data.name.trim()) { this.shakeCta(); return; }\n      this._answers[4] = [this.data.name.trim()];\n      this.next();\n      return;\n    }\n    if (st.type === 'multi') {\n      this.envSeal();\n      this.later(() => this.next(), 120);\n    }\n  },\n  shakeCta() {\n    this.setData({ ctaShake: true });\n    this.later(() => this.setData({ ctaShake: false }), 600);\n  },\n  skip() {\n    if (this.data.busy) return;\n    this.envFlutter();\n    this.next();\n  },\n  goBack() {\n    if (this.data.busy || this.data.cur === 0) return;\n    this.loadStep(this.data.cur - 1, 'zoomIn');\n  },\n\n  /* ---------- 步进转场（wxml: fxWipe/fxBlinds/pageIn） ---------- */\n  next() {\n    if (this.data.busy) return;\n    if (this.data.cur >= this.data.steps.length - 1) { this.finish(); return; }\n    this.setData({ busy: true, envOpen: false });\n    const fx = OB_FX[this.data.cur];\n    const nextIdx = this.data.cur + 1;\n    if (fx === 'wipe') {\n      this.setData({ fxWipe: true });\n      this.later(() => this.loadStep(nextIdx, ''), 430);\n      this.later(() => this.setData({ fxWipe: false, busy: false }), 950);\n    } else if (fx === 'blinds') {\n      this.setData({ fxBlinds: true });\n      this.later(() => this.loadStep(nextIdx, ''), 750);\n      this.later(() => this.setData({ fxBlinds: false, busy: false }), 1400);\n    } else {\n      this.loadStep(nextIdx, 'zoomIn');\n      this.later(() => this.setData({ busy: false }), 700);\n    }\n  },\n\n  /* ---------- 完成（wxml: envCenter/envFly/wrapOut/hearts） ---------- */\n  finish() {\n    if (this.data.busy) return;\n    this.setData({ busy: true, note: '收到啦。', envOpen: true });\n    this._answers[4] = this._name ? [this._name] : [];\n    user.set({ obAnswers: this._answers, nickname: this._name || '小美' });\n    api.submitOnboard(this._answers).catch(() => {});\n    this.later(() => this.setData({ wrapOut: true }), 300);\n    this.later(() => this.setData({ envCenter: true }), 600);\n    this.later(() => this.setData({\n      hearts: [\n        { dx: -88, rr: -26, delay: 0 },\n        { dx: 0, rr: 0, delay: 0.18 },\n        { dx: 88, rr: 26, delay: 0.36 }\n      ]\n    }), 1550);\n    this.later(() => this.setData({ envFly: true }), 2550);\n    this.later(() => wx.redirectTo({ url: '/pages/summary/summary' }), 3370);\n  },\n\n  /* ---------- 安全卡（wxml: safeOk/safeConsult） ---------- */\n  safeOk() {\n    this.setData({ safeOn: false });\n    this.later(() => this.next(), 260);\n  },\n  safeConsult() {\n    this.setData({ safeOn: false });\n    nav.go('/pages/consultants/consultants');\n  }\n});\n","pages/prediag/prediag.js":"const api = require('../../utils/api');\nconst nav = require('../../utils/nav');\nPage({\n  data: { msgs: [], typing: true, opts: [], progress: [true, false, false, false, false], gen: false },\n  onLoad() { this._step = 0; this._id = 0; this._running = true; this._timers = []; this._answers = [];\n    api.fetchPrediagQuestions().then(qs => {\n      this._qs = qs;\n      this.later(() => {\n        this.addMsg('ai', qs[0].q);\n        this.setData({ opts: qs[0].opts, typing: false });\n        this._running = false;\n      }, 700);\n    });\n  },\n  onUnload() { this._timers.forEach(clearTimeout); },\n  later(fn, ms) { const id = setTimeout(fn, ms); this._timers.push(id); return id; },\n  addMsg(role, text) {\n    const msgs = this.data.msgs;\n    let hideAv = false;\n    if (role === 'ai' && msgs.length && msgs[msgs.length - 1].role === 'ai') hideAv = true;\n    msgs.push({ id: this._id++, role, text, hideAv });\n    this.setData({ msgs });\n    wx.pageScrollTo({ scrollTop: 99999, duration: 300 });\n  },\n  answer(e) {\n    if (this._running) return;\n    this._running = true;\n    const text = e.currentTarget.dataset.t;\n    this.addMsg('user', text); /* 2026-10-09 修：x-msg 认 'user'，传 'me' 会渲染成 AI 样式 */\n    this._answers.push(text);\n    this._step++;\n    const prog = this.data.progress.map((_, i) => i < this._step);\n    this.setData({ opts: [], progress: prog });\n    if (this._step >= this._qs.length) {\n      this.later(() => {\n        this.setData({ gen: true });\n        wx.pageScrollTo({ scrollTop: 99999, duration: 300 });\n        /* 提交答卷 → 报告存 globalData 供 report 页读取 */\n        api.submitPrediagAnswers(this._answers).then(res => {\n          require('../../stores/user').set({ report: res.report });\n          this.later(() => wx.redirectTo({ url: '/pages/report/report' }), 1200);\n        });\n      }, 400);\n      return;\n    }\n    this.setData({ typing: true });\n    this.later(() => {\n      this.addMsg('ai', this._qs[this._step].q);\n      this.setData({ opts: this._qs[this._step].opts, typing: false });\n      this._running = false;\n    }, 850);\n  },\n  goBack() { nav.back('/pages/chat/chat'); }\n});\n","pages/report/report.js":"const nav = require('../../utils/nav');\n\nPage({\n  data: { report: {} },\n  onLoad() {\n    /* 报告来自预诊断提交（globalData），直接刷新时用默认演示数据兜底 */\n    const user = require('../../stores/user');\n    const r = user.get('report') || {\n      emotions: ['焦虑', '愤怒', '迷茫'],\n      conflict: '婚姻信任危机 —— 发现配偶疑似暧昧信息，尚未证实，处于「想求证又怕摊牌」的僵持状态，伴随持续的情绪内耗。',\n      goal: '稳定当前情绪，梳理应对策略，评估关系走向。',\n      urgency: { level: 0.55, label: '中度 · 建议尽快' },\n      direction: '婚姻信任修复 · 出轨创伤疗愈方向咨询师'\n    };\n    this.setData({ report: r });\n  },\n  goConsultants() { nav.go('/pages/consultants/consultants'); }\n});\n","pages/sleep/sleep.js":"const toast = require('../../behaviors/toast');\nconst demo = require('../../utils/demo');\nPage({\n  behaviors: [toast],\n  data: { playingIdx: -1 },\n  play(e) {\n    this.setData({ playingIdx: +e.currentTarget.dataset.i });\n    this.showToast(demo.t('audio'));\n  },\n  mall() { this.showToast(demo.t('mall')); }\n});\n","pages/summary/summary.js":"const TROUBLE_SHORT = { '伴侣沟通不顺':'伴侣沟通','婚姻出现变化':'婚姻变化','对关系感到不安':'关系中的不安','家庭/亲子压力':'家庭和亲子压力','情绪起伏大':'情绪压力','工作生活压力大':'工作生活压力','失眠、想太多':'睡眠困扰','孤独、没人理解':'孤独感','想更了解自己':'自我探索','只是想说说话':'倾诉的需要' };\nconst MOOD_PHRASE = { '比较平静':'此刻比较平静','有些委屈':'现在有些委屈','焦虑不安':'现在有些焦虑不安','生气烦躁':'现在有点烦躁','疲惫无力':'现在很疲惫','难过想哭':'现在心里难过','感到绝望':'现在正经历很难的时刻','说不清楚':'感受还有些说不清楚' };\nconst PREF_PHRASE = { '先听我说完':'先听你说完','帮我把事理清楚':'帮你把事理清楚','帮我看见真实感受':'陪你看见真实感受','一起想想怎么办':'陪你一起想办法','提醒我注意安全与边界':'提醒你注意安全与边界','需要时联系真人咨询师':'需要时帮你联系真人咨询师','还不确定，先聊聊':'先轻松聊聊' };\nconst PREF_SHORT = { '帮我把事理清楚':'帮你理清' };\nconst nav = require('../../utils/nav');\n\nPage({\n  data: { title: '', desc: '' },\n  onLoad() {\n    const user = require('../../stores/user'), a = user.get('obAnswers') || {};\n    const troubles = a[0] || [], prefer = a[1] || [], mood = (a[3] || [])[0] || '';\n    const name = (a[4] || [])[0] || '你';\n    if ((a[4] || [])[0]) require('../../stores/user').set({ nickname: (a[4] || [])[0] });\n    const t = troubles.map(x => TROUBLE_SHORT[x] || x);\n    const tTxt = t.length ? ('最近你主要在经历' + t.slice(0, 2).join('和') + (t.length > 2 ? '等方面的困扰' : '')) : '最近你想找个人说说话';\n    const mTxt = mood ? ('，' + (MOOD_PHRASE[mood] || '现在有些' + mood)) : '';\n    let pTxt = '；我会先按你的节奏陪你，不急着下结论';\n    if (prefer.length) {\n      pTxt = '；你希望' + (PREF_PHRASE[prefer[0]] || prefer[0]) +\n        (prefer[1] ? ('，再' + (PREF_SHORT[prefer[1]] || PREF_PHRASE[prefer[1]] || prefer[1])) : '');\n    }\n    this.setData({\n      title: name + '，我大致了解了',\n      desc: tTxt + mTxt + pTxt + '。我们不用一次解决所有事，从你现在最想说的开始就好。'\n    });\n  },\n  toChat() { nav.go('/pages/chat/chat'); },\n  toHome() { nav.go('/pages/home/home'); }\n});\n","services/auth.js":"/* ============================================================\n * 登录态服务：wx.login → code2Session → token\n * - ensureSession(): 有未过期 token 直接复用，否则静默重登\n * - authedRequest(): 带自动重登的请求（401 重登一次再试）\n * USE_MOCK 下全部本地模拟，页面无需感知\n * ============================================================ */\nconst user = require('../stores/user');\n\nconst TTL = 6 * 24 * 3600 * 1000; // token 有效期 6 天\n\nfunction _mockLogin() {\n  return Promise.resolve({ token: 'mock-token-' + Date.now(), userId: 'mock-user' });\n}\n\n/* 真实前端：POST /api/auth/login { code } → { token, userId } */\nfunction code2Session() {\n  return new Promise((resolve, reject) => {\n    wx.login({\n      success(res) {\n        if (!res.code) { reject(new Error('wx.login 无 code')); return; }\n        /* 函数内 require：避免 auth ↔ api 循环依赖（api 顶层不引 auth） */\n        const api = require('../utils/api');\n        if (api.USE_MOCK) { resolve(_mockLogin()); return; }\n        api.rawRequest('/api/auth/login', 'POST', { code: res.code })\n          .then(resolve).catch(reject);\n      },\n      fail: reject\n    });\n  });\n}\n\nfunction ensureSession(force) {\n  const { token, tokenAt } = user.get();\n  if (!force && token && tokenAt && Date.now() - tokenAt < TTL) {\n    return Promise.resolve(token);\n  }\n  return code2Session().then(res => {\n    user.set({ token: res.token, userId: res.userId, tokenAt: Date.now() });\n    return res.token;\n  });\n}\n\n/* 带 token 的请求；401 强制重登一次后重试 */\nfunction authedRequest(path, method, data) {\n  return ensureSession().then(() => {\n    const api = require('../utils/api');\n    return api.rawRequest(path, method, data, user.get('token'));\n  }).catch(err => {\n    if (err && /401|token/i.test(err.message || '')) {\n      return ensureSession(true).then(() => {\n        const api = require('../utils/api');\n        return api.rawRequest(path, method, data, user.get('token'));\n      });\n    }\n    throw err;\n  });\n}\n\nmodule.exports = { ensureSession, authedRequest };\n","stores/user.js":"/* ============================================================\n * 用户状态 store —— 全局状态唯一入口\n * 之前散在 app.globalData 的字段全部收拢到这里：\n *   nickname / obAnswers / careOn / report / counselorId / pickedSlot\n * 内存态 + storage 持久化同步；页面不再直接碰 globalData\n * ============================================================ */\nconst KEY = 'xixi_user_state';\n\nconst state = {\n  nickname: '小美',\n  obAnswers: null,     // 问卷答卷 {0:[..],...}\n  careOn: false,       // 生理期关怀授权\n  report: null,        // 预诊断报告\n  counselorId: '',     // 当前查看的咨询师\n  pickedSlot: '',      // 已选预约时段\n  token: '',           // 登录态（services/auth 维护）\n  userId: ''\n};\n\n/* 启动时从 storage 恢复可持久化字段 */\nfunction restore() {\n  try {\n    const saved = wx.getStorageSync(KEY);\n    if (saved) {\n      ['nickname', 'careOn', 'token', 'userId'].forEach(k => {\n        if (saved[k] !== undefined && saved[k] !== '') state[k] = saved[k];\n      });\n    }\n  } catch (e) {}\n}\nrestore();\n\n/* 持久化白名单（report/答卷等大对象或会话态不落盘） */\nconst PERSIST = ['nickname', 'careOn', 'token', 'userId'];\n\nfunction set(patch) {\n  Object.assign(state, patch);\n  const saved = {};\n  PERSIST.forEach(k => { saved[k] = state[k]; });\n  try { wx.setStorageSync(KEY, saved); } catch (e) {}\n  return state;\n}\n\nfunction get(key) {\n  return key ? state[key] : state;\n}\n\nmodule.exports = { get, set, state };\n","stores/ximi.js":"/* 西米演示态的跨页共享（2026-10-09 新增）\n *\n * 为什么单独开一个 store：这三项要在页面之间同步，写进任一页的 data 都会不同步——\n *   - avatar    我的页换头像 → 变化页/对话页的用户气泡头像要跟着变（原型 setAvatar 同步全部 .uav）\n *   - litLamps  对话页/疗愈页点亮一盏灯 → 变化页灯海要加一盏（原型 lightOneLamp 同一份计数）\n *   - nudgeShown 陪伴承接全场只出现一次（原型 companionShown）\n *\n * 与 stores/user 的分工：user 存\"关于这个人的\"（昵称/答案/会员/token，要持久化上报）；\n * 本 store 存\"演示进度\"（灯数/头像/承接是否已出现），只落本地存储，不上报。\n */\nconst KEY = 'xixi_ximi_state';\nconst DEFAULTS = {\n  avatar: 0,        /* 插画头像索引 0-11（utils/avatars 的 NAMES 顺序） */\n  litLamps: 18,     /* 已点亮的灯数，起点 18 = 甲方原型的演示值 */\n  nudgeShown: false /* 陪伴承接是否已出现过 */\n};\n\n/* **只有头像落盘**（那是用户偏好）；灯数与承接是会话态。\n * 2026-10-09 细节轮修正：原先三项一起落盘，结果演示值跨启动累积——我跑几轮冒烟后灯数从 18 涨到 27，\n * 用户会看到\"别人的灯\"。灯数现在每次启动回到 18，会话内点亮照常 +1（演示要的即时反馈保留）。\n * 接真实记录域后，这个数应改为从数据算，而不是本地累加。 */\nconst PERSIST_KEYS = ['avatar'];\n\nlet state = Object.assign({}, DEFAULTS);\ntry {\n  const saved = wx.getStorageSync(KEY);\n  if (saved && typeof saved === 'object') {\n    PERSIST_KEYS.forEach(k => { if (saved[k] !== undefined) state[k] = saved[k]; });\n  }\n} catch (e) { /* 首次运行无存储，用默认值 */ }\n\nfunction persist() {\n  const out = {};\n  PERSIST_KEYS.forEach(k => { out[k] = state[k]; });\n  try { wx.setStorageSync(KEY, out); } catch (e) { /* 存储失败不阻断交互 */ }\n}\n\nfunction get(k) { return k === undefined ? state : state[k]; }\n\nfunction set(patch) {\n  state = Object.assign(state, patch || {});\n  persist();\n  return state;\n}\n\n/* 点亮一盏灯：返回点亮后的总数（供页面直接显示） */\nfunction lightOne() {\n  state.litLamps += 1;\n  persist();\n  return state.litLamps;\n}\n\n/* 演示复位（变化页「生成海报」等场景不需要复位；留给自测与截图脚本用） */\nfunction reset() {\n  state = Object.assign({}, DEFAULTS);\n  persist();\n  return state;\n}\n\nmodule.exports = { get: get, set: set, lightOne: lightOne, reset: reset, DEFAULTS: DEFAULTS };\n","tools/__tests__/x-batch2.test.js":"/* 第二批模块化单测：content-data 数据模块 + 4 张卡片组件 + x-pay-sheet\n *\n * 说明：share/book/topic 三卡的 wxml 保留原页面的「相邻 <text> 无空白」写法（渲染逐字节\n * 不变是硬要求），miniprogram-simulate 的 wcc transform 对这种结构会抛错，故这三卡在 jest\n * 里只测定义层（属性声明 + press 上抛），渲染由模拟器冒烟（文本转储逐字节比对）覆盖。\n * 渲染能跑通的 quote/pay-sheet 照常做 render 断言（与 x-toast/x-sheet 测试同款）。\n *\n * 注：content-data 未做医疗词扫描 —— 内容页文案含既有职称「婚姻家庭治疗师」与\n * cdetail 的「诊断报告」，均为既定演示文案；红线扫描对象是 AI/危机文案（modules/crisis）。 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst ROOT = path.join(__dirname, '../..');\n\nconst QUOTE_ID = simulate.load(C('x-quote-card'));\nconst SHEET_ID = simulate.load(C('x-sheet'));\nconst PAY_ID = simulate.load(C('x-pay-sheet'), { usingComponents: { 'x-sheet': SHEET_ID } });\n\n/* 取组件定义（不渲染）：stub 掉全局 Component 后隔离重新执行（否则命中 simulate 的模块缓存） */\nconst captured = [];\nglobal.Component = obj => { captured.push(obj); return obj; };\njest.isolateModules(() => {\n  require(ROOT + '/components/x-quote-card/x-quote-card.js');\n  require(ROOT + '/components/x-share-card/x-share-card.js');\n  require(ROOT + '/components/x-book-card/x-book-card.js');\n  require(ROOT + '/components/x-topic-row/x-topic-row.js');\n  require(ROOT + '/components/x-pay-sheet/x-pay-sheet.js');\n});\nconst [quoteDef, shareDef, bookDef, topicDef, payDef] = captured;\n\nconst CD = require('../../utils/content-data');\n\ndescribe('utils/content-data', () => {\n  test('四个列表齐全，条数与原页面硬编码一致', () => {\n    expect(CD.columns).toHaveLength(2);\n    expect(CD.shares).toHaveLength(3);\n    expect(CD.books).toHaveLength(3);\n    expect(CD.past).toHaveLength(3);\n  });\n  test('引号字符保真（转义还原后与原 wxml 一致）', () => {\n    expect(CD.books[1].quote).toContain(\"就是'走了'，'去了'，'不在了'\");\n    expect(CD.shares[1].text).toContain('把\"随便\"换成了\"我建议\"');\n    expect(CD.columns[0].quote).toContain('害怕一旦说\"不\"');\n    expect(CD.past[0].count).toBe('8 篇 ›');\n  });\n});\n\ndescribe('卡片组件定义层（4 张同构）', () => {\n  test('都声明 item / rise 属性，且 rise 默认 0', () => {\n    for (const d of [quoteDef, shareDef, bookDef, topicDef]) {\n      expect(d.properties.item.type).toBe(Object);\n      expect(d.properties.rise.type).toBe(Number);\n      expect(d.properties.rise.value).toBe(0);\n    }\n  });\n  test('virtualHost + apply-shared（全局 .gr-* 样式生效的前提）', () => {\n    for (const d of [quoteDef, shareDef, bookDef, topicDef]) {\n      expect(d.options.virtualHost).toBe(true);\n      expect(d.options.styleIsolation).toBe('apply-shared');\n    }\n  });\n  test('可点卡（quote/book）onTap 上抛 press；无点卡（share/topic）不定义 onTap', () => {\n    for (const d of [quoteDef, bookDef]) {\n      let evt = null;\n      d.methods.onTap.call({ triggerEvent: n => { evt = n; } });\n      expect(evt).toBe('press');\n    }\n    expect(shareDef.methods).toBeUndefined();\n    expect(topicDef.methods).toBeUndefined();\n  });\n});\n\ndescribe('x-quote-card（render 断言）', () => {\n  test('渲染字段 + rise 拼 class', () => {\n    const c = simulate.render(QUOTE_ID, { item: CD.columns[0], rise: 3 });\n    const html = c.dom.innerHTML;\n    expect(html).toContain('main--gr-c');\n    expect(html).toContain('main--rise');\n    expect(html).toContain('main--d3');\n    expect(html).toContain('沈若云');\n    expect(html).toContain('国家二级心理咨询师');\n    expect(html).toContain('3天前');\n  });\n});\n\ndescribe('x-pay-sheet', () => {\n  test('未支付态渲染订单表单；pay / close 上抛', () => {\n    let pays = 0, closes = 0;\n    const c = simulate.render(PAY_ID, {\n      show: true,\n      c: { name: '沈若云', price: 599, avatar: 'https://vmqqkwrtbsutpbnwnefa.supabase.co/storage/v1/object/public/xinzhiyu/xixi/prod/asset/art/avatar-c1.jpg' },\n      slotTxt: '明天 10:00（默认）',\n      paid: false\n    });\n    const html = c.dom.innerHTML;\n    expect(html).toContain('确认订单');\n    expect(html).toContain('沈若云 · 单次咨询');\n    expect(html).toContain('¥599');\n    expect(html).toContain('明天 10:00（默认）');\n    expect(html).toContain('微信支付');\n    c.addEventListener('pay', () => pays++);\n    c.addEventListener('close', () => closes++);\n    c.instance.onPay();\n    c.instance.onClose();\n    expect(pays).toBe(1);\n    expect(closes).toBe(1);\n  });\n  test('已支付态切换成功面板', () => {\n    const c = simulate.render(PAY_ID, { show: true, c: { name: '沈若云', price: 599 }, paid: true });\n    expect(c.dom.innerHTML).toContain('支付成功');\n    expect(c.dom.innerHTML).not.toContain('确认订单');\n  });\n  test('定义层：show/c/slotTxt/paid 属性齐备', () => {\n    expect(Object.keys(payDef.properties).sort()).toEqual(['c', 'paid', 'show', 'slotTxt']);\n  });\n});\n","tools/__tests__/x-btn.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-btn', () => {\n  test('renders and behaves correctly', () => {\nlet fired = 0;\nconst comp = simulate.render(X_BTN_ID, { type: 'primary', block: true, disabled: true });\ncomp.addEventListener('tap', () => fired++);\ncomp.querySelector('.btn').dispatchEvent('tap');\nexpect(fired).toBe(0);\nexpect(comp.dom.innerHTML).toContain('width:100%');\nconst comp2 = simulate.render(X_BTN_ID, { type: 'primary' });\nexpect(comp2.dom.innerHTML).toContain('btn-primary');\n\n  });\n});\n","tools/__tests__/x-card.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-card', () => {\n  test('renders and behaves correctly', () => {\nconst comp = simulate.render(X_CARD_ID, { rise: 3 });\nexpect(comp.dom.innerHTML).toContain('rise');\nexpect(comp.dom.innerHTML).toContain('d3');\n\n  });\n});\n","tools/__tests__/x-icon.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-icon', () => {\n  test('renders and behaves correctly', () => {\nconst comp = simulate.render(X_ICON_ID, { name: 'ic30f', size: 48 });\nexpect(comp.dom.innerHTML).toContain('ic30f');\nexpect(comp.dom.innerHTML).toContain('width:48');\n\n  });\n});\n","tools/__tests__/x-modules.test.js":"/* x-toast 组件单测 + 新模块（demo/crisis/tab/pet-face）单测 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst TOAST_ID = simulate.load(C('x-toast'));\n\nconst demo = require('../../utils/demo');\nconst crisis = require('../../modules/crisis');\n\n/* Behavior 工厂在 jest 环境下需要 stub 全局 Behavior() */\nglobal.Behavior = obj => obj;\nconst tab = require('../../behaviors/tab');\nconst petFaceB = require('../../behaviors/pet-face');\n\ndescribe('x-toast', () => {\n  test('hidden by default, shows with msg', () => {\n    const t = simulate.render(TOAST_ID, { show: false, msg: '' });\n    expect(t.dom.innerHTML).toBe('');\n    t.setData({ msg: '已放进你的手记' });\n    expect(t.dom.innerHTML).toContain('已放进你的手记');\n    expect(t.dom.innerHTML).not.toContain('show');\n    t.setData({ show: true });\n    expect(t.dom.innerHTML).toContain('main--toast main--show');\n  });\n});\n\ndescribe('utils/demo', () => {\n  test('registry covers detach list keys with 演示态 wording', () => {\n    expect(demo.t('voice')).toContain('演示版');\n    expect(demo.t('article')).toBe('文章详情 · 演示版');\n    expect(demo.t('pay')).toContain('暂未开放支付');\n  });\n  test('unknown key passthrough (no silent swallow)', () => {\n    expect(demo.t('随便什么')).toBe('随便什么');\n  });\n});\n\ndescribe('modules/crisis', () => {\n  test('word list is the single source (api.js re-exports it)', () => {\n    const api = require('../../utils/api');\n    expect(api.CRISIS_WORDS).toBe(crisis.CRISIS_WORDS);\n  });\n  test('isCrisis detects redline phrases', () => {\n    expect(crisis.isCrisis('我真的活不下去了')).toBe(true);\n    expect(crisis.isCrisis('今天有点累')).toBe(false);\n    expect(crisis.isCrisis('')).toBe(false);\n    expect(crisis.isCrisis(null)).toBe(false);\n  });\n  test('reply avoids medical words and offers professional referral (redline)', () => {\n    for (const w of ['诊断', '治疗', '治愈', '康复', '症状', '患者']) {\n      expect(crisis.REPLY).not.toContain(w);\n    }\n    expect(crisis.REPLY).toContain('专业支持');\n  });\n  test('calm timing exists (crisis sheet not instantly dismissible)', () => {\n    expect(crisis.TIMING.calm).toBeGreaterThanOrEqual(3000);\n  });\n});\n\ndescribe('behaviors/tab', () => {\n  test('factory binds index; page onShow calls syncTab explicitly', () => {\n    const b = tab(2);\n    const calls = [];\n    const ctx = { getTabBar: () => ({ setData: p => calls.push(p) }), ...b.methods };\n    ctx.syncTab();\n    expect(calls).toEqual([{ selected: 2 }]);\n  });\n  test('no tabBar (non-tab page) is a no-op', () => {\n    const b = tab(0);\n    const ctx = { getTabBar: () => null, ...b.methods };\n    expect(() => ctx.syncTab()).not.toThrow();\n  });\n});\n\ndescribe('behaviors/pet-face', () => {\n  jest.useFakeTimers();\n  test('face() switches field then returns to base', () => {\n    const b = petFaceB('xFace');\n    const data = { xFace: 'base' };\n    const ctx = {\n      data,\n      setData(p) { Object.assign(data, p); }\n    };\n    b.methods.face.call(ctx, 'wow', 1000);\n    expect(data.xFace).toBe('wow');\n    jest.advanceTimersByTime(1100);\n    expect(data.xFace).toBe('base');\n  });\n  test('idle loop animates, self-recovers and stop clears', () => {\n    const b = petFaceB('petFace');\n    const data = { petFace: 'base' };\n    const ctx = { data, setData(p) { Object.assign(data, p); }, ...b.methods };\n    b.methods.startIdleFace.call(ctx, 100);\n    jest.advanceTimersByTime(100);\n    expect(data.petFace).toBe('blink'); // 轮换已启动\n    jest.advanceTimersByTime(300); // 第 4 tick：逢 4 上爱心\n    expect(data.petFace).toBe('love');\n    b.methods.stopIdleFace.call(ctx);\n    const snap = data.petFace;\n    jest.advanceTimersByTime(1000);\n    expect(data.petFace).toBe(snap); // 停止后不再轮换\n  });\n});\n","tools/__tests__/x-msg.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-msg', () => {\n  test('renders and behaves correctly', () => {\nconst ai = simulate.render(X_MSG_ID, { role: 'ai', text: '我在听', tags: ['焦虑'], mem: true });\nexpect(ai.dom.innerHTML).toContain('我在听');\nexpect(ai.dom.innerHTML).toContain('emo-tags');\nexpect(ai.dom.innerHTML).toContain('已引用你的档案记忆');\nconst user = simulate.render(X_MSG_ID, { role: 'user', text: '我累了' });\nexpect(user.dom.innerHTML).toContain('我累了');\nexpect(user.dom.innerHTML).not.toContain('avatar-ai');\nconst typing = simulate.render(X_MSG_ID, { role: 'ai', typing: true });\nexpect(typing.dom.innerHTML).toContain('--typing');\n\n  });\n});\n","tools/__tests__/x-navbar.test.js":"/* 组件单测（官方 miniprogram-simulate）；每组件独立文件避免 wcc 产物全局作用域冲突 */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-navbar', () => {\n  test('renders and behaves correctly', () => {\nconst comp = simulate.render(X_NAVBAR_ID, { title: '咨询师详情' });\nexpect(comp.dom.innerHTML).toContain('咨询师详情');\nexpect(comp.dom.innerHTML).toContain('pg-back');\nexpect(comp.dom.innerHTML).toContain('top-fade');\nconst dark = simulate.render(X_NAVBAR_ID, { title: '失眠关怀专区', dark: true });\nexpect(dark.dom.innerHTML).toContain('--dark');\n\n  });\n});\n","tools/__tests__/x-round1.test.js":"/* 第一轮积木单测：x-hero-xixi / x-daily-quote / x-duo-cards / x-share-sheet\n *\n * 说明：这四块的 wxml 含「相邻 <text>/<image> 无空白」结构（与原页面一致，保真需要），\n * miniprogram-simulate 的 wcc transform 对此会抛错 → 本文件测定义层（options/属性/事件），\n * 渲染由 tools/smoke-batch2.js 的文本转储逐字节比对 + 截图目验覆盖（与 x-batch2 同策略）。 */\nconst path = require('path');\nconst ROOT = path.join(__dirname, '../..');\n\nconst captured = [];\nglobal.Component = obj => { captured.push(obj); return obj; };\njest.isolateModules(() => {\n  require(ROOT + '/components/x-hero-xixi/x-hero-xixi.js');\n  require(ROOT + '/components/x-daily-quote/x-daily-quote.js');\n  require(ROOT + '/components/x-duo-cards/x-duo-cards.js');\n  require(ROOT + '/components/x-share-sheet/x-share-sheet.js');\n});\nconst [heroDef, quoteDef, duoDef, sheetDef] = captured;\n\nconst fire = (def, method, e) => {\n  const got = [];\n  def.methods[method].call({ triggerEvent: (n, d) => got.push([n, d]) }, e);\n  return got;\n};\n\ndescribe('第一轮积木 · 约定一致性', () => {\n  test('四块都是 virtualHost + apply-shared（无多余节点、全局原语可用）', () => {\n    for (const d of [heroDef, quoteDef, duoDef, sheetDef]) {\n      expect(d.options.virtualHost).toBe(true);\n      expect(d.options.styleIsolation).toBe('apply-shared');\n    }\n  });\n  test('属性齐备（内核与外壳的唯一契约面）', () => {\n    expect(Object.keys(heroDef.properties).sort()).toEqual(['bubble', 'face', 'rise']);\n    expect(Object.keys(quoteDef.properties).sort()).toEqual(['author', 'image', 'rise', 'text']);\n    expect(Object.keys(duoDef.properties).sort()).toEqual(['col', 'items']);\n    expect(Object.keys(sheetDef.properties).sort()).toEqual(['author', 'image', 'show', 'text']);\n  });\n});\n\ndescribe('第一轮积木 · 事件上抛（内核唯一入口）', () => {\n  test('hero：poke / chat', () => {\n    expect(fire(heroDef, 'onPoke')[0][0]).toBe('poke');\n    expect(fire(heroDef, 'onChat')[0][0]).toBe('chat');\n  });\n  test('今日一句：press（整卡）/ share（分享钮）', () => {\n    expect(fire(quoteDef, 'onPress')[0][0]).toBe('press');\n    expect(fire(quoteDef, 'onShare')[0][0]).toBe('share');\n  });\n  test('双卡：select 带 key，语义分派留在页', () => {\n    const got = fire(duoDef, 'onSelect', { currentTarget: { dataset: { key: 'sleep' } } });\n    expect(got[0][0]).toBe('select');\n    expect(got[0][1]).toEqual({ key: 'sleep' });\n  });\n  test('分享弹层：close / save', () => {\n    expect(fire(sheetDef, 'onClose')[0][0]).toBe('close');\n    expect(fire(sheetDef, 'onSave')[0][0]).toBe('save');\n  });\n});\n","tools/__tests__/x-round2.test.js":"/* 第二轮积木单测：x-chat-top / x-chat-input / x-orb-pet / x-crisis-card\n * 策略同前：这些块含相邻 <text>/<image> 结构（保真需要），simulate 渲染不了 → 测定义层与事件，\n * 渲染由 tools/smoke-batch2.js 的截图 + 文本转储覆盖。 */\nconst path = require('path');\nconst ROOT = path.join(__dirname, '../..');\n\nconst captured = [];\nglobal.Component = obj => { captured.push(obj); return obj; };\njest.isolateModules(() => {\n  require(ROOT + '/components/x-chat-top/x-chat-top.js');\n  require(ROOT + '/components/x-chat-input/x-chat-input.js');\n  require(ROOT + '/components/x-orb-pet/x-orb-pet.js');\n  require(ROOT + '/components/x-crisis-card/x-crisis-card.js');\n});\nconst [topDef, inputDef, orbDef, crisisDef] = captured;\n\nconst fire = (def, m, e) => {\n  const got = [];\n  def.methods[m].call({ triggerEvent: (n, d) => got.push([n, d]) }, e);\n  return got;\n};\n\ndescribe('第二轮积木 · 约定一致性', () => {\n  test('四块都是 virtualHost + apply-shared', () => {\n    for (const d of [topDef, inputDef, orbDef, crisisDef]) {\n      expect(d.options.virtualHost).toBe(true);\n      expect(d.options.styleIsolation).toBe('apply-shared');\n    }\n  });\n  test('属性齐备（内核与外壳的唯一契约面）', () => {\n    expect(Object.keys(topDef.properties).sort()).toEqual(['scrolled']);\n    expect(Object.keys(inputDef.properties).sort()).toEqual(['kbH', 'value']);\n    expect(Object.keys(orbDef.properties).sort()).toEqual(['face', 'happy', 'kbH', 'peek', 'wiggle']);\n    expect(Object.keys(crisisDef.properties).sort()).toEqual(['calmOk', 'show']);\n  });\n});\n\ndescribe('第二轮积木 · 事件上抛', () => {\n  test('顶栏：back / book', () => {\n    expect(fire(topDef, 'onBack')[0][0]).toBe('back');\n    expect(fire(topDef, 'onBook')[0][0]).toBe('book');\n  });\n  test('输入栏：input 带 value、kb 带 height，其余原样上抛', () => {\n    expect(fire(inputDef, 'onInput', { detail: { value: 'abc' } })[0]).toEqual(['input', { value: 'abc' }]);\n    expect(fire(inputDef, 'onKb', { detail: { height: 320 } })[0]).toEqual(['kb', { height: 320 }]);\n    for (const [m, name] of [['onSend', 'send'], ['onVoice', 'voice'], ['onPic', 'pic'], ['onFocus', 'focus'], ['onBlur', 'blur']]) {\n      expect(fire(inputDef, m)[0][0]).toBe(name);\n    }\n  });\n  test('漂浮西米：poke', () => {\n    expect(fire(orbDef, 'onPoke')[0][0]).toBe('poke');\n  });\n  test('危机卡：consult / close（文案与冷静期不在本层，正本在 modules/crisis.js 与页面）', () => {\n    expect(fire(crisisDef, 'onConsult')[0][0]).toBe('consult');\n    expect(fire(crisisDef, 'onClose')[0][0]).toBe('close');\n  });\n});\n","tools/__tests__/x-round3.test.js":"/* 第三轮积木单测：x-gcal（心情日历卡外壳，home / moodcal 共用） */\nconst path = require('path');\nconst ROOT = path.join(__dirname, '../..');\n\nconst captured = [];\nglobal.Component = obj => { captured.push(obj); return obj; };\njest.isolateModules(() => {\n  require(ROOT + '/components/x-gcal/x-gcal.js');\n});\nconst [gcalDef] = captured;\n\ndescribe('x-gcal · 共用外壳积木', () => {\n  test('virtualHost + apply-shared；属性 variant / bg', () => {\n    expect(gcalDef.options.virtualHost).toBe(true);\n    expect(gcalDef.options.styleIsolation).toBe('apply-shared');\n    expect(Object.keys(gcalDef.properties).sort()).toEqual(['bg', 'variant']);\n    /* v15 起图源走 cloud:// 文件 ID（Supabase 直链在安卓真机被域名校验拦截的历史教训） */\n    expect(gcalDef.properties.bg.value).toMatch(/^cloud:\\/\\/cloudbase-d3giwlyte87aecc2e\\./);\n    expect(gcalDef.properties.bg.value).toContain('conc-botanic');\n  });\n  test('variant 默认空（首页紧凑卡），可传 \"mcal\" / \"mcal mmood\"', () => {\n    expect(gcalDef.properties.variant.value).toBe('');\n  });\n  test('点击上抛 press（仅首页绑定，moodcal 不绑不触发）', () => {\n    const got = [];\n    gcalDef.methods.onPress.call({ triggerEvent: n => got.push(n) });\n    expect(got).toEqual(['press']);\n  });\n});\n","tools/__tests__/x-sheet.test.js":"/* 组件单测（官方 miniprogram-simulate） */\nconst path = require('path');\nconst simulate = require('/tmp/mpci/node_modules/miniprogram-simulate');\nconst C = name => path.join(__dirname, '../../components/' + name + '/' + name);\nconst X_ICON_ID = simulate.load(C('x-icon'));\nconst X_BTN_ID = simulate.load(C('x-btn'));\nconst X_CARD_ID = simulate.load(C('x-card'));\nconst X_SHEET_ID = simulate.load(C('x-sheet'));\nconst X_MSG_ID = simulate.load(C('x-msg'));\nconst X_NAVBAR_ID = simulate.load(C('x-navbar'));\n\ndescribe('x-sheet', () => {\n  test('renders and behaves correctly', () => {\n    let closed = 0;\n    const comp = simulate.render(X_SHEET_ID, { show: false });\n    expect(comp.dom.innerHTML).not.toContain('--sheet main--show');\n    comp.setData({ show: true });\n    expect(comp.dom.innerHTML).toContain('--sheet main--show');\n    comp.addEventListener('close', () => closed++);\n    comp.instance.onClose();   /* bindtap 同一入口，行为等价 */\n    expect(closed).toBe(1);\n  });\n});\n","tools/__tests__/x-ximi.test.js":"/* 西米剧本/数据模块用例（2026-10-09 随四页一并新增）\n *\n * 重点不是覆盖率，而是**盯住甲方原型里出现过的两类缺陷**：\n *   1) 芯片指向不存在的分支（原型的静态芯片 data-k 没有任何绑定，点了没反应）\n *   2) 危机文案/热线被顺手抄进剧本表（红线：必须只走 modules/crisis）\n * 其余是可测的纯逻辑：分流顺序、演练三套反应、按小时问候、数据条数。\n */\nconst SC = require('../../modules/ximi-script');\nconst crisis = require('../../modules/crisis');\nconst heal = require('../../utils/heal-data');\nconst grow = require('../../utils/grow-data');\nconst me = require('../../utils/me-data');\nconst avatars = require('../../utils/avatars');\n\n/* 节点全集：BRANCHES + FREE_NODES */\nconst KEYS = Object.keys(SC.BRANCHES).concat(Object.keys(SC.FREE_NODES));\n\n/* 甲方原型 S[] 的 36 个键，逐个写死：少一个都说明移植漏了 */\nconst PROTO_KEYS = ('tired t-vague t-a x-breath x-rest t-b t-specific t-company flat flat-long flat-short ' +\n  'x-time x-write selfblame know growup x-lamp sort advice longtime cant-do cant-choose husband-sort ' +\n  'drill-detail drill-start drill-again drill-save husband mad child child-hw child-quiet self ' +\n  'mil-sort mil-a child-sort').split(' ');\n\ndescribe('西米剧本：分支连通性', () => {\n  test('原型 36 条分支一条不少', () => {\n    expect(PROTO_KEYS.length).toBe(36);\n    expect(PROTO_KEYS.filter(k => !SC.BRANCHES[k])).toEqual([]);\n  });\n\n  test('补的第 37 条是 company（原型该键悬空，本移植给了明确收束 —— 见模块头注）', () => {\n    const extra = Object.keys(SC.BRANCHES).filter(k => PROTO_KEYS.indexOf(k) < 0);\n    expect(extra).toEqual(['company']);\n  });\n\n  test('每个节点的 chips 的 k 都能落到一个存在的节点上', () => {\n    const bad = [];\n    Object.keys(SC.BRANCHES).forEach(k => {\n      const chips = SC.BRANCHES[k].chips || [];\n      chips.forEach(c => { if (KEYS.indexOf(c.k) < 0) bad.push(k + ' → ' + c.k); });\n    });\n    expect(bad).toEqual([]);\n  });\n\n  test('两组静态芯片（首屏「先说说」「想解决点什么」）的 k 都能落地', () => {\n    const bad = SC.CHIPS_FRIEND.concat(SC.CHIPS_COACH)\n      .filter(c => KEYS.indexOf(c.k) < 0)\n      .map(c => c.t + ' → ' + c.k);\n    expect(bad).toEqual([]);\n  });\n\n  test('演练收尾芯片的 k 都能落地', () => {\n    const bad = SC.DRILL_CHIPS.filter(c => KEYS.indexOf(c.k) < 0).map(c => c.k);\n    expect(bad).toEqual([]);\n  });\n\n  test('每个节点至少说了话或开了浮层（不许有哑节点）', () => {\n    const dead = KEYS.filter(k => {\n      const n = SC.BRANCHES[k] || SC.FREE_NODES[k];\n      return !(n.say || n.open || n.lamp || n.toast || n.confirm);\n    });\n    expect(dead).toEqual([]);\n  });\n});\n\ndescribe('西米剧本：红线（危机不进剧本表）', () => {\n  test('剧本模块内不含危机热线号码', () => {\n    const src = JSON.stringify(SC);\n    expect(src).not.toMatch(/12356/);          /* 甲方原型的号码 */\n    expect(src).not.toMatch(/400-161-9995/);   /* 项目基线也不该被复制进来 */\n  });\n\n  test('危机词不会把用户分流进普通分支（由页面用 crisis 前置拦截）', () => {\n    /* 剧本表里不应出现\"不想活/自杀\"这类词——它们只属于 modules/crisis */\n    const src = JSON.stringify(SC);\n    expect(src).not.toMatch(/不想活|自杀|去死/);\n    expect(crisis.isCrisis('我不想活了')).toBe(true);\n  });\n});\n\ndescribe('西米剧本：自由输入分流顺序（照原型 freeform）', () => {\n  const { route } = SC;\n  test('睡不好优先于「怎么办」', () => {\n    expect(route('睡不着怎么办', 'friend').k).toBe('__sleepy');\n  });\n  test('「怎么办」在闺蜜模式 → 轻确认卡', () => {\n    expect(route('我到底该怎么办', 'friend')).toEqual({ confirm: true });\n  });\n  test('「怎么办」在教练模式 → 直接进 sort', () => {\n    expect(route('我到底该怎么办', 'coach').k).toBe('sort');\n  });\n  test('婆婆 → 孩子 → 老公 → 累 → 兜底 的优先级', () => {\n    expect(route('婆婆住一起很难受', 'friend').k).toBe('mil-sort');\n    expect(route('孩子不听话', 'friend').k).toBe('child-sort');\n    expect(route('老公不理我', 'friend').k).toBe('husband-sort');\n    expect(route('今天有点累', 'friend').k).toBe('__tired-free');\n    expect(route('今天天气不错', 'friend').k).toBe('__fallback');\n  });\n  test('婆婆优先于孩子（同句都出现时按原型顺序）', () => {\n    expect(route('婆婆说我孩子带得不好', 'friend').k).toBe('mil-sort');\n  });\n});\n\ndescribe('西米剧本：冲突演练三套反应', () => {\n  test('开头「你总是」→ 防御式 + 点评点出这三个字', () => {\n    const r = SC.drillReply('你从来都不管孩子写作业');\n    expect(r.role).toMatch(/你又来了/);\n    expect(r.review.join('')).toMatch(/你总是/);\n  });\n  test('从「我」起头 → 他躲开（上纲上线）', () => {\n    const r = SC.drillReply('我觉得有点累，希望你能帮我一下');\n    expect(r.role).toMatch(/上纲上线/);\n  });\n  test('其他（含沉默）→ 低头看手机那套', () => {\n    const r = SC.drillReply('今天下雨了');\n    expect(r.role).toMatch(/低头看手机/);\n    expect(r.review.join('')).toMatch(/沉默/);\n  });\n});\n\ndescribe('西米剧本：按小时问候（六个时段）', () => {\n  test('边界值与文案', () => {\n    expect(SC.greetByHour(5)).toBe('早。今天不用起得很急。');\n    expect(SC.greetByHour(11)).toBe('中午了，先歇一会儿。');\n    expect(SC.greetByHour(14)).toBe('下午了，还撑得住吗？');\n    expect(SC.greetByHour(18)).toBe('天快黑了，今天可以到这儿。');\n    expect(SC.greetByHour(21)).toBe('这会儿安静下来了。');\n    expect(SC.greetByHour(2)).toBe('还没睡。我在。');\n  });\n  test('不传参数也能拿到一句（用当前时间）', () => {\n    expect(typeof SC.greetByHour()).toBe('string');\n  });\n});\n\ndescribe('疗愈数据', () => {\n  test('四类目各自指向一个练习浮层 kind', () => {\n    expect(heal.CATS.map(c => c.kind)).toEqual(['write', 'med', 'breath', 'oh']);\n    expect(heal.CATS.every(c => c.bgc && c.h4 && c.p)).toBe(true);\n  });\n  test('呼吸 4-7-8 三相时长与原型一致', () => {\n    expect(heal.BREATH.phases.map(p => p.hold)).toEqual([4100, 7000, 8100]);\n  });\n  test('课程只落甲方给的 3 门（其余 9 门不编造）', () => {\n    expect(heal.COURSES.length).toBe(3);\n    expect(heal.SEC_COURSE.x).toBe('全部课程 12 门');\n  });\n  test('OH 卡 5 问（不解读，只问）', () => {\n    expect(heal.OH.q.length).toBe(5);\n  });\n  test('冥想 4 段', () => {\n    expect(heal.MED.list.length).toBe(4);\n  });\n});\n\ndescribe('变化数据', () => {\n  test('灯海 46 盏 / 起点 18 盏亮', () => {\n    expect(grow.LAMP.total).toBe(46);\n    expect(grow.LAMP.on).toBe(18);\n  });\n  test('三数格与时间线', () => {\n    expect(grow.STATS.map(s => s.v)).toEqual(['12', '3', '7']);\n    expect(grow.TIMELINE.length).toBe(3);\n  });\n});\n\ndescribe('我的数据', () => {\n  test('四行设置，第一行是换头像', () => {\n    expect(me.ROWS.length).toBe(4);\n    expect(me.ROWS[0].key).toBe('avatar');\n  });\n  test('能量卡按原型数值（与后端模型冲突已在文件头登记）', () => {\n    expect(me.ENERGY.amt).toBe('688');\n    expect(me.ENERGY.max).toBe(1500);\n    expect(me.ENERGY.used).toBe(932);\n  });\n  test('陪伴浮层四得 + 三问 + 一句可停', () => {\n    expect(me.OV_COMP.gains.length).toBe(4);\n    expect(me.OV_COMP.bullets.length).toBe(3);\n    expect(me.OV_COMP.note).toMatch(/随时可以停/);\n  });\n});\n\ndescribe('插画头像', () => {\n  test('12 个，名字与原型一致', () => {\n    expect(avatars.NAMES).toEqual(['月', '云', '叶', '花', '贝', '山', '星', '鸟', '雨', '阳', '浪', '灯']);\n  });\n  test('每个头像项 = 名字 + 渐变底 bg + cloud:// 帧源 src（v15 起走云存储 image 直读）', () => {\n    avatars.list().forEach(a => {\n      expect(a.name).toBeTruthy();\n      expect(a.bg).toMatch(/linear-gradient/);\n      expect(a.src).toMatch(/^cloud:\\/\\/cloudbase-d3giwlyte87aecc2e\\./);\n      expect(a.src).toMatch(/xixi-art\\/avatar-/);\n    });\n  });\n});\n","tools/check-assets.js":"/* 包内容物资产断言：上传前的硬门。命中任一即退出码 1。\n * 用法：node tools/check-assets.js [小程序目录，默认仓库根]\n *\n * 1. 包内禁止 .webp —— iOS 真机不渲染 webp（主线 2026-10-11 三连踩定案：\n *    提审线曾带 27 张包内 webp，真机走查即成片空白图）。网络图/包内图一律 jpg/png。\n * 2. 代码引用的本地图片必须真实存在 —— 引用悬空在开发者工具里常静默空白，\n *    真机才暴露；此断言把「空白图」拦在上传前。\n */\nconst fs = require('fs');\nconst path = require('path');\n\nconst ROOT = path.resolve(process.argv[2] || path.join(__dirname, '..'));\n\nconst cfg = JSON.parse(fs.readFileSync(path.join(ROOT, 'project.config.json'), 'utf8'));\nconst ignores = ((cfg.packOptions || {}).ignore || [])\n  .filter((it) => it.type === 'folder')\n  .map((it) => it.value.replace(/\\/$/, ''));\n\nfunction walk(dir, out) {\n  for (const name of fs.readdirSync(dir)) {\n    if (name === '.git' || name === 'node_modules') continue;\n    const abs = path.join(dir, name);\n    const rel = path.relative(ROOT, abs);\n    if (ignores.some((ig) => rel === ig || rel.startsWith(ig + '/'))) continue;\n    const st = fs.statSync(abs);\n    if (st.isDirectory()) walk(abs, out);\n    else out.push({ rel, abs });\n  }\n  return out;\n}\n\nconst files = walk(ROOT, []);\nconst problems = [];\n\n/* 1. webp 禁令 */\nconst webp = files.filter((f) => /\\.webp$/i.test(f.rel));\nfor (const f of webp) problems.push(`${f.rel}: 包内 webp（iOS 真机不渲染，一律 jpg/png）`);\n\n/* 2. 代码引用的本地图片必须存在（wxml/js/wxss 全扫；跳过 {{}} 数据绑定命中） */\nconst imgRefs = [];\nfor (const f of files) {\n  if (!/\\.(wxml|js|wxss)$/.test(f.rel)) continue;\n  const src = fs.readFileSync(f.abs, 'utf8');\n  for (const m of src.matchAll(/['\"(](\\/images\\/[^'\")?]+?\\.(?:jpg|jpeg|png|webp))['\")]/g)) {\n    if (m[1].includes('{{')) continue; /* 数据绑定路径静态不可判，交由运行时 */\n    imgRefs.push({ from: f.rel, to: m[1] });\n  }\n  /* 网络图 webp 同罪（字面量可查；动态拼接走人工真机走查） */\n  for (const m of src.matchAll(/https?:\\/\\/[^'\"\\s)]+?\\.webp/gi)) {\n    problems.push(`${f.rel}: 引用网络 webp ${m[0]}`);\n  }\n}\nfor (const r of imgRefs) {\n  if (!fs.existsSync(path.join(ROOT, r.to))) problems.push(`${r.from}: 引用不存在的图片 ${r.to}`);\n}\n\n/* 3. 动态拼接的图片集必须有完整成员（静态正则查不到拼接点——双轴审查盲区实证：\n *    quotes q1..q8 全仓唯一引用是 `'/images/quotes/q' + n + '.jpg'`） */\n/* main 线图源走 cloud:// 文件 ID + 包内静态图，无动态拼接集；新增拼接图集时在此登记 */\nconst DYNAMIC_SETS = [];\nfor (const s of DYNAMIC_SETS) {\n  for (let i = 1; i <= s.count; i++) {\n    const p = `${s.prefix}${i}${s.ext}`;\n    if (!fs.existsSync(path.join(ROOT, p))) problems.push(`动态图片集缺成员 ${p}`);\n  }\n}\n\n/* 3.5 拼接图片路径断言（票 105/106 双盲区加固）：'/images/...'+x 拼出的图路径\n *    逃过第 2 步字面量扫描；凡出现「/images/ 前缀串 + 拼接」或「同行 /images/+图片后缀拼接」\n *    必须登记 DYNAMIC_SETS 或改字面量，否则拦下。webp 拼接无论前缀一律拦（webp 禁令）。 */\nfor (const f of files) {\n  if (!/\\.(js|wxml)$/.test(f.rel)) continue;\n  const src = fs.readFileSync(f.abs, 'utf8');\n  for (const line of src.split('\\n')) {\n    if (line.indexOf('/images/') < 0 || line.indexOf('+') < 0) continue;\n    if (/\\{\\{/.test(line)) continue; /* wxml 数据绑定交由运行时/真机 */\n    const prefixConcat = /['\"]\\/images\\/[^'\"]*['\"]\\s*\\+/.test(line);\n    const suffixImg = /\\+\\s*['\"][^'\"]*\\.(?:jpg|jpeg|png|webp)['\"]/i.test(line);\n    const webpConcat = /\\+\\s*['\"][^'\"]*\\.webp['\"]/i.test(line);\n    if (webpConcat) problems.push(`${f.rel}: 拼接 webp 路径（webp 禁令）→ ${line.trim().slice(0, 90)}`);\n    else if (prefixConcat && suffixImg) problems.push(`${f.rel}: 拼接图片路径需登记 DYNAMIC_SETS 或改字面量 → ${line.trim().slice(0, 90)}`);\n  }\n}\n\nif (problems.length) {\n  console.error('✗ 资产断言未通过：');\n  for (const p of problems) console.error('  - ' + p);\n  process.exit(1);\n}\nconsole.log(`✓ 资产断言通过（0 webp；${imgRefs.length} 处引用 + ${DYNAMIC_SETS.length} 组动态集全部存在）`);\n","tools/check-demo-leak.js":"/* 演示态泄漏断言：上传前的硬门。命中任一即退出码 1。\n * 用法：node tools/check-demo-leak.js [小程序目录，默认仓库根]\n *\n * 口径（对照项目 P0 教训：提审包静默携带演示数据/虚假文案）：\n *  1. 演示适配器（utils/adapters/demo.js）只能被 utils/domains/ 引用；\n *    页面/组件/app 直连演示数据即泄漏。诚实演示态的口径是「数据层带 demo 标记，\n *    页面如实标注」，不是让页面各取所需。\n *  2. 零容忍字符串：任何「不会产生真实扣款」类支付免责文案与「测试环境/测试包」\n *    标记不得出现在包内任何文件——它们只该存在于仓库外的构建口径里。\n *    注意：「演示」「示例」本身是设计内的诚实标注（示例名单、示例资料），\n *    不在本断言词表；词表只收「泄漏特征」，不收「诚实标注」。\n */\nconst fs = require('fs');\nconst path = require('path');\n\nconst ROOT = path.resolve(process.argv[2] || path.join(__dirname, '..'));\n/* 目录级口径：utils/adapters/ 下任何演示适配器只许被 utils/domains/ 引用——\n * 按文件名单点白名单可被「克隆 demo2.js」绕过（双轴审查反例） */\nconst DEMO_ADAPTER_DIR = /^utils\\/adapters\\//;\nconst DEMO_HOSTS = /^utils\\/domains\\//;\nconst BANNED = ['不会产生真实扣款', '不会真实扣款', '演示版，不会', '测试环境', '测试包',\n  '不产生任何费用', '不产生费用', '仅供体验'];\n/* 「假数据」只许出现在演示适配器目录自己的注释里 */\nconst FAKE_DATA_ALLOW = /^utils\\/adapters\\//;\nconst SKIP_DIRS = new Set(['.git', 'node_modules', 'tools', 'docs', 'tests']);\n\nfunction walk(dir, out) {\n  for (const name of fs.readdirSync(dir)) {\n    if (SKIP_DIRS.has(name)) continue;\n    const abs = path.join(dir, name);\n    const st = fs.statSync(abs);\n    if (st.isDirectory()) walk(abs, out);\n    else if (/\\.(wxml|js|json|wxss)$/.test(name)) out.push({ rel: path.relative(ROOT, abs), abs });\n  }\n  return out;\n}\n\nconst problems = [];\nconst files = walk(ROOT, []);\n\nfor (const f of files) {\n  const rel = f.rel.replace(/\\\\/g, '/');\n  const src = fs.readFileSync(f.abs, 'utf8');\n  if (/\\.(js)$/.test(rel)) {\n    for (const m of src.matchAll(/require\\(\\s*['\"]([^'\"]+)['\"]\\s*\\)|from\\s+['\"]([^'\"]+)['\"]/g)) {\n      const spec = (m[1] || m[2] || '').replace(/^\\.\\//, '');\n      const resolved = spec.startsWith('.') ? path.posix.normalize(path.posix.join(path.posix.dirname(rel), spec)) : spec;\n      if (DEMO_ADAPTER_DIR.test(resolved.replace(/\\.js$/, '')) && !DEMO_HOSTS.test(rel)) {\n        problems.push(`${rel}: 直连演示适配器（utils/adapters/* 只能经 utils/domains/ 取数）`);\n      }\n    }\n  }\n  for (const w of BANNED) {\n    if (src.includes(w)) problems.push(`${rel}: 命中泄漏文案「${w}」`);\n  }\n  if (!FAKE_DATA_ALLOW.test(rel) && src.includes('假数据')) {\n    problems.push(`${rel}: 命中「假数据」（只许在演示适配器自身出现）`);\n  }\n}\n\nif (problems.length) {\n  console.error('✗ 演示态泄漏断言未通过：');\n  for (const p of problems) console.error('  - ' + p);\n  process.exit(1);\n}\nconsole.log(`✓ 演示态泄漏断言通过（扫描 ${files.length} 文件）`);\n","tools/probe-runtime.js":"/* main 线运行时走查探针：逐页落地 + 截图 + 存储残留断言。\n * 与 release 线 tools/probe-runtime.js 同源；差异：main 无 frame 骨架机制（无 frameTop\n * 断言），页面清单为四页 IA（含 heal/grow）。出处：pre-submit-r1 第七轮（票 43）。\n * 前置：`cli auto --project <本目录> --auto-port 9500`；用法：NODE_PATH=/tmp/mpci/node_modules PORT=9500 node tools/probe-runtime.js\n */\nconst automator = require('miniprogram-automator');\nconst fs = require('fs');\nconst path = require('path');\nconst sleep = ms => new Promise(r => setTimeout(r, ms));\n\nconst PORT = process.env.PORT || '9500';\nconst SHOTS = process.env.SHOTS || '/tmp/shots-main';\nconst PAGES = [\n  ['launch', '/pages/launch/launch', 2800],\n  ['onboard', '/pages/onboard/onboard', 2200],\n  ['summary', '/pages/summary/summary', 1800],\n  ['home', '/pages/home/home', 3200],\n  ['chat', '/pages/chat/chat', 4200],\n  ['heal', '/pages/heal/heal', 2600],\n  ['grow', '/pages/grow/grow', 2600],\n  ['prediag', '/pages/prediag/prediag', 1800],\n  ['report', '/pages/report/report', 2000],\n  ['consultants', '/pages/consultants/consultants', 2000],\n  ['cdetail', '/pages/cdetail/cdetail', 1800],\n  ['sleep', '/pages/sleep/sleep', 1800],\n  ['content', '/pages/content/content', 2200],\n  ['me', '/pages/me/me', 2200],\n  ['moodcal', '/pages/moodcal/moodcal', 1800],\n];\n\n(async () => {\n  const mp = await automator.connect({ wsEndpoint: `ws://127.0.0.1:${PORT}` });\n  fs.mkdirSync(SHOTS, { recursive: true });\n  let pass = 0, fail = 0;\n  const log = (ok, name, msg) => { console.log(ok ? '✓' : '✗', name, msg || ''); ok ? pass++ : fail++; };\n\n  for (const [name, route, wait] of PAGES) {\n    try {\n      await mp.reLaunch(route);\n      await sleep(wait);\n      const cur = await mp.currentPage();\n      const landed = cur && cur.path;\n      const okLanding = landed === route.slice(1) ||\n        (name === 'launch' && (landed === 'pages/onboard/onboard' || landed === 'pages/home/home'));\n      if (!okLanding) { log(false, name, '落地失败: ' + landed); continue; }\n      const shot = path.join(SHOTS, `probe-${name}.png`);\n      await mp.screenshot({ path: shot });\n      log(true, name, `→ ${path.basename(shot)}`);\n    } catch (e) {\n      log(false, name, e.message.slice(0, 60));\n    }\n  }\n\n  /* 图片通道：主包不应再有本地 webp；cloud:// 引用的组件数据由截图目验 */\n  try {\n    const hasWebp = fs.readdirSync(path.join(__dirname, '../images')).filter(f => /\\.webp$/i.test(f));\n    if (hasWebp.length) log(false, 'images', '包内 webp 残留: ' + hasWebp.join(','));\n    else log(true, 'images', '包内 0 webp（cloud:// 渲染看截图目验）');\n  } catch (e) { log(false, 'images', e.message.slice(0, 50)); }\n\n  try {\n    await mp.reLaunch('/pages/me/me');\n    await sleep(1200);\n    const keys = await mp.evaluate(() => JSON.stringify(wx.getStorageInfoSync().keys));\n    const list = JSON.parse(keys).filter(k => k.indexOf('xixi_') === 0);\n    console.log('storage xixi_* keys:', list.join(', ') || '(none)');\n  } catch (e) { log(false, 'storage', e.message.slice(0, 60)); }\n\n  await mp.disconnect();\n  console.log(`\\n${pass} 通过 / ${fail} 失败`);\n  process.exit(fail ? 1 : 0);\n})().catch(e => { console.error('FATAL:', e.message); process.exit(1); });\n","tools/regression.js":"/* ============================================================\n * 全流程回归走查（项目资产，勿放 /tmp）\n * 用法：先 `cli auto --project <root> --auto-port <PORT>` 开自动化，\n *       然后 PORT=9500 node tools/regression.js\n * 连接后会校验页面里注入的 BUILD_ID，防止\"测的不是改的\"\n * ============================================================ */\nconst automator = require('/tmp/mpci/node_modules/miniprogram-automator');\nconst fs = require('fs');\nconst path = require('path');\nconst sleep = ms => new Promise(r => setTimeout(r, ms));\n\nconst ROOT = path.join(__dirname, '..');\nconst PORT = process.env.PORT || '9500';\nconst SHOTS = process.env.SHOTS || '/tmp/shots';\n\n/* 构建指纹：改动任何页面文件后手动 +1，或让 CI 注入。\n * 相对 require 按本文件所在目录（tools/）解析，必须 ../（同提审线票 39） */\nconst BUILD_ID = require('../BUILD_ID.js');\n\n(async () => {\n  const mp = await automator.connect({ wsEndpoint: `ws://127.0.0.1:${PORT}` });\n  fs.mkdirSync(SHOTS, { recursive: true });\n  let pass = 0, fail = 0;\n\n  const shot = async name => {\n    await sleep(600);\n    try { await mp.screenshot({ path: `${SHOTS}/${name}.png` }); pass++; console.log('📷', name); }\n    catch (e) { fail++; console.log('✗', name, e.message.slice(0, 50)); }\n  };\n  const cur = async () => (await mp.pageStack()).map(p => p.path).pop();\n\n  /* 指纹校验：往任意页 evaluate 读 BUILD_ID（app.js 挂的） */\n  try {\n    const injected = await mp.evaluate(() => getApp().BUILD_ID);\n    if (injected !== BUILD_ID) {\n      console.error(`✗ 构建指纹不一致！IDE 运行的是 ${injected}，本地是 ${BUILD_ID}。请重启 IDE 实例再测。`);\n      process.exit(2);\n    }\n    console.log('✓ 构建指纹一致:', BUILD_ID);\n  } catch (e) {\n    console.error('✗ 无法读取构建指纹（IDE 实例异常或 BUILD_ID 未注入）:', e.message.slice(0, 60));\n    process.exit(2);\n  }\n\n  console.log('起点:', await cur());\n  await shot('00-onboard');\n  /* …流程同 /tmp 版 walk.js：问卷→汇总→tab 页→子页…（保持人工可读） */\n  await mp.disconnect();\n  console.log(`\\n${pass} 通过 / ${fail} 失败`);\n  process.exit(fail ? 1 : 0);\n})().catch(e => { console.error('FATAL:', e.message); process.exit(1); });\n","utils/api.js":"/* ============================================================\n * API 层（真实前端接入点）\n * - USE_MOCK=true  时全部走本地 mock 数据（当前演示模式）\n * - USE_MOCK=false 时走 wx.request，按下方注释的接口契约返回\n * 接后端只需：改 BASE_URL、USE_MOCK=false、按契约实现服务端\n * ============================================================ */\n\nconst BASE_URL = 'https://api.example.com'; // TODO: 换成真实网关\nconst USE_MOCK = true;\n\n/* ---------- 通用请求封装 ---------- */\nfunction rawRequest(path, method = 'GET', data = {}, token = '') {\n  return new Promise((resolve, reject) => {\n    wx.request({\n      url: BASE_URL + path,\n      method,\n      data,\n      header: { 'content-type': 'application/json', ...(token ? { Authorization: 'Bearer ' + token } : {}) },\n      success(res) {\n        if (res.statusCode >= 200 && res.statusCode < 300) resolve(res.data);\n        else reject(new Error('HTTP ' + res.statusCode + ': ' + JSON.stringify(res.data)));\n      },\n      fail: reject\n    });\n  });\n}\n\nfunction request(path, method = 'GET', data = {}) {\n  if (USE_MOCK) return Promise.reject(new Error('USE_MOCK=true，未走网络：' + path));\n  const user = require('../stores/user');\n  return new Promise((resolve, reject) => {\n    wx.request({\n      url: BASE_URL + path,\n      method,\n      data,\n      header: { 'content-type': 'application/json', ...(user.get('token') ? { Authorization: 'Bearer ' + user.get('token') } : {}) },\n      success(res) {\n        if (res.statusCode >= 200 && res.statusCode < 300) resolve(res.data);\n        else reject(new Error('HTTP ' + res.statusCode + ': ' + JSON.stringify(res.data)));\n      },\n      fail: reject\n    });\n  });\n}\nconst delay = (ms, val) => new Promise(r => setTimeout(() => r(val), ms));\n\n/* ============================================================\n * 1. 问卷（onboard）→ 提交答卷\n * 契约：POST /api/onboard  body: { answers: {0:[..],1:[..],...} }\n *       返回 { userId, nickname }\n * ============================================================ */\nfunction submitOnboard(answers) {\n  if (USE_MOCK) return delay(200, { userId: 'mock-user', nickname: (answers[4] || [])[0] || '小美' });\n  return request('/api/onboard', 'POST', { answers });\n}\n\n/* ============================================================\n * 1.5 问卷题目\n * 契约：GET /api/onboard/questions → Step[]（结构同本地 OB_STEPS）\n * ============================================================ */\nconst OB_STEPS = [\n  { type: 'multi', max: 3, label: '当前困扰 · 多选，最多 3 项', title: '最近，哪些事让你想找人说说？', sub: '选最接近的就好，之后可改。', skip: '暂时不想说', note: '我在听。',\n    opts: ['伴侣沟通不顺', '婚姻出现变化', '对关系感到不安', '家庭/亲子压力', '情绪起伏大', '工作生活压力大', '失眠、想太多', '孤独、没人理解', '想更了解自己', '只是想说说话'] },\n  { type: 'multi', max: 2, label: '陪伴偏好 · 多选，最多 2 项', title: '你希望西米怎么陪你？', sub: '没有标准答案，我会边聊边调。', skip: '还不确定，先聊聊', note: '慢慢来。',\n    opts: ['先听我说完', '帮我把事理清楚', '帮我看见真实感受', '一起想想怎么办', '提醒我注意安全与边界', '需要时联系真人咨询师', '还不确定，先聊聊'] },\n  { type: 'single', label: '关系阶段 · 单选，可跳过', title: '你目前大致处在哪个阶段？', sub: '只用来更好理解你，不会替你做关系决定。', skip: '暂时不想说', note: '谢谢你愿意说。',\n    opts: ['单身 / 暂无稳定关系', '恋爱 / 稳定交往', '已婚 / 共同生活', '分居、离婚或关系变动中', '情况比较复杂', '暂时不想说'] },\n  { type: 'single', label: '当前情绪 · 单选', title: '此刻感受更接近？', sub: '选最接近的一项即可。', skip: '说不清楚', note: '辛苦了。',\n    opts: ['比较平静', '有些委屈', '焦虑不安', '生气烦躁', '疲惫无力', '难过想哭', '感到绝望', '说不清楚'] },\n  { type: 'name', label: '怎么称呼 · 可选', title: '我可以怎么叫你？', sub: '不用真名，只用于陪伴称呼。', skip: '暂时不设置', note: '很高兴认识你。' }\n];\nfunction fetchOnboardQuestions() {\n  if (USE_MOCK) return delay(100, OB_STEPS);\n  return request('/api/onboard/questions').catch(() => OB_STEPS); /* 接口缺席时兜底内置题集 */\n}\n\n/* ============================================================\n * 2. AI 树洞（chat）\n * 契约：\n *   GET  /api/chat/script            → 开场剧本 ScriptLine[]\n *   POST /api/chat/message {text}    → { reply, tags?, mem?, crisis? }\n * crisis=true 时前端弹危机干预卡\n * ============================================================ */\nconst CHAT_SCRIPT = [\n  { role: 'ai', text: '下午好，{name}。我在这里，今天过得怎么样？慢慢说，不着急。 🌷' },\n  { role: 'user', text: '昨天我又翻了他手机，什么都没翻到，可我就是安心不下来' },\n  { role: 'ai', text: '听起来你现在很焦虑，还带着一点自我怀疑——明明没有找到什么，心却更慌了。在信任被动摇过之后，这种「不踏实」是很多人都会经历的，这不是你敏感。\\n\\n我好奇的是，如果用一个词形容你现在最想要的，那会是什么？', tags: ['焦虑', '不安'] },\n  { role: 'user', text: '确定性吧。我不想再猜了，太累了' },\n  { role: 'ai', text: '我记得你提过，你们结婚十年了，孩子也8岁了。十年的感情，让你想要的是一个答案，而不是一场输赢，对吗？\\n\\n在摊牌之前，也许可以先想清楚一件事：你希望那次谈话，把你们带向哪里。如果想有人陪你把利弊一条条梳理清楚，我可以帮你预约擅长婚姻信任方向的咨询师。', tags: ['疲惫', '渴望确定'], mem: true }\n];\nconst CHAT_REPLIES = [\n  '嗯，我在听。这种反反复复的猜测最消耗人了——你一个人扛了这么久，真的很不容易。\\n\\n如果此刻只做一件让自己松一口气的小事，你会想到什么？',\n  '能感觉到你说这些的时候，心里是又委屈又疲惫的。任何人在你的处境里，都会有这样的感受。\\n\\n我们先把「他有没有」放一放。你有多久没有好好睡过一觉、好好吃过一顿饭了？',\n  '谢谢你愿意把这些说给我听。能看出来，你心里其实已经在慢慢有答案了，只是还需要一点力量去确认它。\\n\\n如果下周的今天，你希望自己的生活是什么样子？'\n];\n/* 危机词唯一正本在 modules/crisis.js；此处 re-export 保持旧引用兼容 */\nconst { CRISIS_WORDS } = require('../modules/crisis');\n\nfunction fetchChatScript() {\n  if (USE_MOCK) return delay(100, CHAT_SCRIPT);\n  return request('/api/chat/script');\n}\nfunction sendChatMessage(text) {\n  /* 前端兜底：危机词本地也拦一层（不能只依赖服务端）；文案正本见 modules/crisis.js */\n  const crisis = require('../modules/crisis').isCrisis(text);\n  if (USE_MOCK) {\n    return delay(1300, crisis\n      ? { reply: require('../modules/crisis').REPLY, crisis: true }\n      : { reply: CHAT_REPLIES[Math.floor(Math.random() * CHAT_REPLIES.length)] });\n  }\n  return request('/api/chat/message', 'POST', { text });\n}\n\n/* ============================================================\n * 3. AI 预诊断（prediag）\n * 契约：\n *   GET  /api/prediag/questions → Question[] { q, opts[] }\n *   POST /api/prediag/answers { answers: string[] }\n *       → { report: Report }（结构见下方 MOCK_REPORT）\n * ============================================================ */\nconst PREDIAG_QUESTIONS = [\n  { q: '在为你匹配最合适的咨询师之前，我想先了解几个关键信息，这样能让你的咨询更高效。\\n\\n你们目前的婚姻状态是怎样的？', opts: ['正在冷战', '刚发现出轨迹象', '已经分居', '其他情况'] },\n  { q: '谢谢你愿意告诉我这些。这件事大概发生多久了？', opts: ['一周内', '一个月内', '半年以内', '已经超过半年'] },\n  { q: '嗯，我明白了。那你现在最困扰、最想解决的问题是什么？', opts: ['信任崩塌走不出来', '情绪内耗很严重', '担心影响孩子', '不知道该不该继续'] },\n  { q: '好的。你希望通过这次咨询，达到什么样的目标？', opts: ['修复这段关系', '看清方向再做决定', '先让自己情绪稳定', '学会保护自己和孩子'] },\n  { q: '最后一个问题——之前有没有尝试过其他方式来解决？', opts: ['自己看书调整过', '找朋友倾诉过', '做过心理咨询', '还没有尝试过'] }\n];\nconst MOCK_REPORT = {\n  emotions: ['焦虑', '愤怒', '迷茫'],\n  conflict: '婚姻信任危机 —— 发现配偶疑似暧昧信息，尚未证实，处于「想求证又怕摊牌」的僵持状态，伴随持续的情绪内耗。',\n  goal: '稳定当前情绪，梳理应对策略，评估关系走向。',\n  urgency: { level: 0.55, label: '中度 · 建议尽快' },\n  direction: '婚姻信任修复 · 出轨创伤疗愈方向咨询师'\n};\n\nfunction fetchPrediagQuestions() {\n  if (USE_MOCK) return delay(100, PREDIAG_QUESTIONS);\n  return request('/api/prediag/questions');\n}\nfunction submitPrediagAnswers(answers) {\n  if (USE_MOCK) return delay(600, { report: MOCK_REPORT });\n  return request('/api/prediag/answers', 'POST', { answers });\n}\n\n/* ============================================================\n * 4. 咨询师（consultants / cdetail）\n * 契约：\n *   GET /api/counselors?direction=xxx → Counselor[]\n *   GET /api/counselors/:id           → CounselorDetail\n *   Counselor: { id, name, badge?, avatar, title, tags[], price, priceUnit, rating, cases, recommend? }\n *   CounselorDetail: { ...Counselor, stats:[{n,label}×3], background, tags[], slots[] }\n * ============================================================ */\nconst COUNSELORS = [\n  { id: 'c1', name: '沈若云', badge: 'TOP', avatar: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-c1.jpg', recommend: true,\n    title: '国家二级心理咨询师 · 婚姻治疗 12 年', tags: ['出轨创伤', '信任修复'],\n    price: 599, priceUnit: '/40分钟', rating: '4.9', cases: '案例 1200+' },\n  { id: 'c2', name: '林晚', avatar: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-c2.jpg',\n    title: '婚姻家庭咨询师 · 8 年', tags: ['夫妻沟通', '情绪疗愈'],\n    price: 399, priceUnit: '/40分钟', rating: '4.8', cases: '案例 860+' },\n  { id: 'c3', name: '陈静姝', avatar: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-c3.jpg',\n    title: '应用心理学硕士 · 婚姻危机干预 15 年', tags: ['婚姻危机', '女性成长'],\n    price: 799, priceUnit: '/40分钟', rating: '5.0', cases: '案例 2000+' }\n];\nconst COUNSELOR_DETAIL = {\n  id: 'c1', name: '沈若云', avatar: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-c1.jpg',\n  title: '国家二级心理咨询师 · 婚姻家庭治疗师',\n  stats: [ { n: '12年', label: '从业经验' }, { n: '1200+', label: '咨询案例' }, { n: '4.9', label: '用户评分' } ],\n  background: '华东师范大学心理学硕士，中德班婚姻家庭治疗连续培训项目成员。专注出轨创伤修复与夫妻信任重建，累计个案时长 6000+ 小时。',\n  tags: ['出轨创伤', '信任修复', '夫妻沟通', '情绪稳定'],\n  slots: ['明天 10:00', '明天 14:30', '周三 19:00', '周四 20:00', '周五 21:00'],\n  price: 599\n};\n\nfunction fetchCounselors() {\n  if (USE_MOCK) return delay(200, COUNSELORS);\n  return request('/api/counselors');\n}\nfunction fetchCounselorDetail(id) {\n  if (USE_MOCK) return delay(200, COUNSELOR_DETAIL);\n  return request('/api/counselors/' + id);\n}\n\n/* ============================================================\n * 5. 首页金句\n * 契约：GET /api/daily-quote → { text, author, image }\n * image 为图片 URL（当前 mock 给本地路径）\n * ============================================================ */\nconst HOME_QUOTES = [\n  ['我们曾如此期盼外界的认可，到最后才知道，世界是自己的，与他人毫无关系。', '—— 杨绛', 'q1'],\n  ['爱自己，是终身浪漫的开始。', '—— 王尔德', 'q2'],\n  ['温柔不是妥协，是见过风雨之后的选择。', '—— 西米', 'q3'],\n  ['你照顾了所有人，也要记得被自己照顾。', '—— 西米', 'q4'],\n  ['真正的强大，是允许自己偶尔不强大。', '—— 西米', 'q5'],\n  ['人间烟火气，最抚凡人心。', '—— 汪曾祺', 'q6'],\n  ['把日子过成自己喜欢的样子，什么时候开始都不晚。', '—— 西米', 'q7'],\n  ['愿你成为自己的太阳，无需凭借谁的光。', '—— 西米', 'q8']\n];\nfunction fetchDailyQuote() {\n  if (USE_MOCK) {\n    const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 864e5);\n    const q = HOME_QUOTES[dayOfYear % HOME_QUOTES.length];\n    /* 票 105：quotes 目录不存在且 webp 已退役（iOS 不渲染）——分享卡用包内真实存在的西米形象图\n     * （分享 imageUrl 不支持 cloud://，须包内 jpg/png） */\n    return delay(100, { text: q[0], author: q[1], image: '/images/xixi-3d.jpg' });\n  }\n  return request('/api/daily-quote');\n}\n\n/* ============================================================\n * 6. 支付（cdetail → 微信支付）\n * 契约：POST /api/orders { counselorId, slot }\n *       → { orderId, payParams }  payParams 传给 wx.requestPayment\n * ============================================================ */\nfunction createOrder(counselorId, slot) {\n  if (USE_MOCK) return delay(300, { orderId: 'mock-' + Date.now(), payParams: null });\n  return request('/api/orders', 'POST', { counselorId, slot });\n}\n/* 真实支付调用示例（接后端后在 cdetail.doPay 里改用）：\n * const { payParams } = await createOrder(cid, slot);\n * wx.requestPayment({ ...payParams, success, fail });\n */\n\n/* ---------- 心情打卡（本地即可，后续可同步云端） ---------- */\nfunction saveMood(moodIndex) {\n  if (USE_MOCK) return Promise.resolve();\n  return request('/api/mood', 'POST', { date: '2026-10-06', mood: moodIndex }); // TODO: 用真实日期\n}\n\nmodule.exports = {\n  USE_MOCK, BASE_URL, request, rawRequest, fetchOnboardQuestions, FALLBACK_STEPS: OB_STEPS,\n  submitOnboard,\n  fetchChatScript, sendChatMessage, CRISIS_WORDS,\n  fetchPrediagQuestions, submitPrediagAnswers,\n  fetchCounselors, fetchCounselorDetail,\n  fetchDailyQuote,\n  createOrder, saveMood\n};\n","utils/avatars.js":"/* 插画头像（12 个）：线条稿 SVG data-uri + 水彩渐变底\n *\n * 来源：甲方排版基准原型（AVS / AVNAME 数组，逐条照抄，未改一笔）\n * 用法：WXML 内联 style ——\n *   style=\"background:{{av.art}} center/58% no-repeat, {{av.bg}}\"\n *   注意 url() 不带引号：WXML style 属性里的双引号会截断（同 utils/mood.js 的既有约定）\n * SVG 必带 width/height（真机铁律 3：data-uri SVG 缺 width 会在 iOS 显示空白）\n */\nconst NAMES = ['月', '云', '叶', '花', '贝', '山', '星', '鸟', '雨', '阳', '浪', '灯'];\n\n/* 线条稿内层（原样） */\nconst ART = {\n  '月': '<path d=\"M25.4 27.2a10 10 0 1 1-6.9-15.9 8.4 8.4 0 0 0 6.9 15.9z\" stroke=\"#8E4058\"/><path d=\"M29 9.5v3.4M27.3 11.2h3.4\" stroke=\"#6E8CA8\"/>',\n  '云': '<path d=\"M12.4 26.6h14.8a5 5 0 0 0 .5-10 7.6 7.6 0 0 0-14.4-2 5.4 5.4 0 0 0-.9 12z\" stroke=\"#6E8CA8\"/>',\n  '叶': '<path d=\"M12 28.4c-.6-9.4 4.6-14.4 15.6-14.4.6 9.4-4.6 15-15.6 14.4z\" stroke=\"#5F8570\"/><path d=\"M12 28.4c3.2-4.4 7.4-7.4 12.4-9.6\" stroke=\"#5F8570\"/>',\n  '花': '<circle cx=\"20\" cy=\"20\" r=\"2.6\" stroke=\"#B0576E\"/><path d=\"M20 17.4c-2-2.8-1.6-5.6 0-5.6s2 2.8 0 5.6zM22.6 20c2.8-2 5.6-1.6 5.6 0s-2.8 2-5.6 0zM20 22.6c2 2.8 1.6 5.6 0 5.6s-2-2.8 0-5.6zM17.4 20c-2.8 2-5.6 1.6-5.6 0s2.8-2 5.6 0z\" stroke=\"#B0576E\"/>',\n  '贝': '<path d=\"M9.4 25.6a10.6 10.6 0 0 1 21.2 0z\" stroke=\"#A8764F\"/><path d=\"M20 15v10.6M14.4 17.2l2.8 8.4M25.6 17.2l-2.8 8.4\" stroke=\"#A8764F\"/>',\n  '山': '<path d=\"M8 28.6l7-10.4 4.6 6.2L25 14l7 14.6z\" stroke=\"#4E7360\"/><circle cx=\"27.4\" cy=\"11.6\" r=\"2.2\" stroke=\"#4E7360\"/>',\n  '星': '<path d=\"M20 9.2l3.2 6.9 7.6.9-5.6 5.1 1.5 7.5-6.7-3.8-6.7 3.8 1.5-7.5-5.6-5.1 7.6-.9z\" stroke=\"#7B6EA0\"/>',\n  '鸟': '<path d=\"M11 22.4c2.6-3.6 5-5.2 7.6-5.2 2 0 3.2 1.2 4.4 3.2M23 20.4c1.4-2 2.6-3.2 4.4-3.2 2.6 0 5 1.6 7.6 5.2\" stroke=\"#6E8CA8\"/><path d=\"M18.6 20.4c1-2.6 2.2-4.2 4.4-5.4 1.6 1 2.6 2.6 3.4 5.4\" stroke=\"#6E8CA8\"/>',\n  '雨': '<path d=\"M16 12.4c2 3.6 3 5.6 3 7.3a3 3 0 0 1-6 0c0-1.7 1-3.7 3-7.3z\" stroke=\"#6E8CA8\"/><path d=\"M25.2 20.4c1.6 2.8 2.4 4.4 2.4 5.8a2.4 2.4 0 0 1-4.8 0c0-1.4.8-3 2.4-5.8z\" stroke=\"#6E8CA8\"/>',\n  '阳': '<circle cx=\"20\" cy=\"20\" r=\"6\" stroke=\"#C08A3E\"/><path d=\"M20 8.4v3M20 28.6v3M8.4 20h3M28.6 20h3M11.6 11.6l2.1 2.1M26.3 26.3l2.1 2.1M28.4 11.6l-2.1 2.1M13.7 26.3l-2.1 2.1\" stroke=\"#C08A3E\"/>',\n  '浪': '<path d=\"M9 16.4c2.5-2 5-2 7.5 0s5 2 7.5 0 5-2 7.5 0M9 24.4c2.5-2 5-2 7.5 0s5 2 7.5 0 5-2 7.5 0\" stroke=\"#5D89A6\"/>',\n  '灯': '<path d=\"M20 9.6c4.6 0 7.6 4.6 7.6 9.6s-3.4 8.6-7.6 8.6-7.6-3.6-7.6-8.6S15.4 9.6 20 9.6z\" stroke=\"#B0576E\"/><path d=\"M20 27.8v3.4M16.4 31.2h7.2M20 6.4v3.2\" stroke=\"#B0576E\"/>',\n};\n\n/* 水彩渐变底（原样） */\nconst BG = {\n  '月': 'linear-gradient(150deg,#EDF3F8,#C9DBE8)',\n  '云': 'linear-gradient(150deg,#F4F7FA,#DDE7EF)',\n  '叶': 'linear-gradient(150deg,#EFF6F1,#D8E8DC)',\n  '花': 'linear-gradient(150deg,#FDF0F4,#F2D8E1)',\n  '贝': 'linear-gradient(150deg,#FCF1EA,#F3DFD0)',\n  '山': 'linear-gradient(150deg,#EEF2F0,#CFDCD6)',\n  '星': 'linear-gradient(150deg,#F5F2FA,#DCD6EA)',\n  '鸟': 'linear-gradient(150deg,#F3F6FA,#D6E2EC)',\n  '雨': 'linear-gradient(150deg,#EDF4F8,#CDDFEA)',\n  '阳': 'linear-gradient(150deg,#FEF5E9,#FBE3C9)',\n  '浪': 'linear-gradient(150deg,#EBF3F7,#C6DCE8)',\n  '灯': 'linear-gradient(150deg,#FDF3E6,#F6DFC6)',\n};\n\nfunction b64(s) {\n  const CH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';\n  let out = '', buf = '';\n  for (let i = 0; i < s.length; i++) {\n    buf += String.fromCharCode(s.charCodeAt(i));\n    while (buf.length >= 3) {\n      const b = [buf.charCodeAt(0), buf.charCodeAt(1), buf.charCodeAt(2)];\n      out += CH[b[0] >> 2] + CH[((b[0] & 3) << 4) | (b[1] >> 4)] + CH[((b[1] & 15) << 2) | (b[2] >> 6)] + CH[b[2] & 63];\n      buf = buf.slice(3);\n    }\n  }\n  if (buf.length === 1) out += CH[buf.charCodeAt(0) >> 2] + CH[(buf.charCodeAt(0) & 3) << 4] + '==';\n  else if (buf.length === 2) {\n    const b = [buf.charCodeAt(0), buf.charCodeAt(1)];\n    out += CH[b[0] >> 2] + CH[((b[0] & 3) << 4) | (b[1] >> 4)] + CH[(b[1] & 15) << 2] + '=';\n  }\n  return out;\n}\n\n/* v13b：头像资产桶化——12 幅插画已光栅化为 webp 入 Supabase（data-uri 在部分 webview 不渲染） */\n/* v15：头像走微信云存储 cloud fileID（image 组件直读，不经域名校验） */\n\nvar AV_FILES = [\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-01.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-02.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-03.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-04.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-05.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-06.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-07.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-08.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-09.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-10.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-11.png\",\n  \"cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-12.png\"\n];\nfunction srcOf(name) {\n  const i = NAMES.indexOf(name);\n  return AV_FILES[i] || AV_FILES[0];\n}\n\n/* 列表项：供头像浮层 wx:for 用（含「和我对话里的头像同步」所需的一切） */\nfunction list() {\n  return NAMES.map(function (n) { return { name: n, bg: BG[n], src: srcOf(n) }; });\n}\n\nmodule.exports = { NAMES: NAMES, BG: BG, srcOf: srcOf, list: list };\n","utils/content-data.js":"/* 成长页列表内容：咨询师感悟 / 用户分享 / 名家书房 / 往期主题的唯一出处。\n * 原先硬编码在 content.wxml，抽成纯数据无 wx 依赖 —— 换 UI 壳可直接搬走。\n * 改文案只改这里；页面只负责渲染。 */\nconst columns = [\n  {\n    avatar: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-c1.jpg',\n    name: '沈若云',\n    title: '国家二级心理咨询师',\n    quote: '「讨好型的人不是善良，是害怕——害怕一旦说\"不\"，就失去被爱的资格。经营关系的第一步，是允许别人对你失望。」',\n    date: '3天前'\n  },\n  {\n    avatar: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/avatar-c2.jpg',\n    name: '周砚秋',\n    title: '婚姻家庭治疗师',\n    quote: '「职场里九成的内耗，来自把别人的课题背在自己身上。分清\"他的事\"和\"我的事\"，是中年人最省心的能力。」',\n    date: '5天前'\n  }\n];\n\nconst shares = [\n  {\n    initial: '梨', bg: '#E8CBD3', color: '#A96678',\n    name: '阿梨', time: '今天',\n    text: '38岁，结婚11年。昨天第一次拒绝了婆婆临时带娃的要求，紧张得手心出汗，但说完之后，天没塌。原来边界感是练出来的。',\n    likes: 236, comments: 41, forwards: 12\n  },\n  {\n    initial: '麦', bg: '#D5DCC9', color: '#7C8F6E',\n    name: '麦田', time: '昨天',\n    text: '部门例会照着文章里的方法，把\"随便\"换成了\"我建议\"。被采纳的那一刻突然明白：温柔和没主见，从来不是一回事。',\n    likes: 189, comments: 23, forwards: 8\n  },\n  {\n    initial: '转', bg: '#D9CFE6', color: '#8D7FB8',\n    name: '42岁的转身', time: '3天前',\n    text: '打卡第21天。以前每天睡前反复想白天说错的话，现在写下来三行字就睡。安睡不是别人给的，是自己肯放过自己。',\n    likes: 412, comments: 56, forwards: 31\n  }\n];\n\nconst books = [\n  {\n    title: '《宽松的婚姻》',\n    author: '周国平 · 散文',\n    quote: '\"与开放的婚姻相比，宽松的婚姻或许是一个较为可行的方案。\"'\n  },\n  {\n    title: '《走到人生边上》',\n    author: '杨绛 · 商务印书馆 2007',\n    quote: '\"我已经走到人生的边缘上，再往前去，就是\\'走了\\'，\\'去了\\'，\\'不在了\\'。九十六岁的自问自答，谈生死、灵魂与人生的价值。\"'\n  },\n  {\n    title: '《蔡康永的说话之道》',\n    author: '蔡康永 · 2010',\n    quote: '\"别人赞美你一句，你回一句赞美，这就叫社交。\"'\n  }\n];\n\nconst past = [\n  { title: '婚姻里的沟通修复', count: '8 篇 ›' },\n  { title: '独处的能力', count: '6 篇 ›' },\n  { title: '和青春期的孩子相处', count: '7 篇 ›' }\n];\n\nmodule.exports = { columns, shares, books, past };\n","utils/demo.js":"/* 演示态集中管理：所有「演示版/暂未开放」提示的唯一出处。\n * 后端接通时：把对应 key 从 DEMO 中删除并删除页面调用点即可（docs/API-MAP.md 三色清单联动）。\n * 纯数据无 wx 依赖 —— 换 UI 框架可直接复用。 */\nconst DEMO = {\n  voice: '语音输入 · 演示版暂未开放',\n  pic: '图片倾诉 · 演示版暂未开放',\n  pressVoice: '按住我说话 · 语音倾诉演示',\n  audio: '音频播放 · 演示版',\n  mall: '跳转商家商城 · 演示版',\n  article: '文章详情 · 演示版',\n  column: '咨询师专栏 · 演示版',\n  book: '书籍详情 · 演示版',\n  payDone: '已跳转企业微信 · 演示结束',\n  pay: '开通陪跑 · 演示版暂未开放支付',\n  upgrade: '升级陪跑 · 见下方会员卡',\n  archive: '我的档案 · 演示版',\n  order: '我的订单 · 演示版',\n  booking: '我的预约 · 演示版',\n  invite: '邀请闺蜜 · 双方各得7天体验',\n  setting: '设置 · 演示版',\n  meditate: '3 分钟呼吸练习即将开始（演示）',\n  shareSave: '分享卡已保存（演示）'\n};\n\nmodule.exports = {\n  DEMO,\n  /* 统一取用：key 不存在时直接返回 key 本身，避免静默丢提示 */\n  t(key) { return DEMO[key] || key; }\n};\n","utils/grow-data.js":"/* 变化页数据（2026-10-09 从甲方排版基准原型移植，文案逐字照抄）\n * 来源：backend/docs/02-设计/甲方排版基准-西米演示-2026-10-09/西米-交互演示-粉蓝水彩版.html\n *\n * 数据现状（写入基准 README §七）：\n *   - 全部为**演示数值**：36 盏灯/18 亮、连续 12 天、3 张话术卡、7 次练习、3 条时间线\n *   - 「记录即点亮」需要真实记录域：后端 xixiData 只存 practices/cognitions，**没有灯海/话术卡域**\n *     → 本轮先本地 mock（与 USE_MOCK=true 现状一致），接真前需补数据域\n */\nconst HEAD = { title: '我的变化', day: '第 12 天' };\n\n/* 雾光灯海：原型 LAMP_TOTAL=46 / LAMP_ON=18，位置与大小是运行时随机（见 pages/grow/grow.js） */\nconst LAMP = {\n  total: 46,\n  on: 18,\n  cap: '盏灯亮着',\n  sub: '每一次记录、每一次练习，都会点亮一盏'\n};\n\nconst STATS = [\n  { v: '12', t: '连续天数' },\n  { v: '3', t: '话术卡' },\n  { v: '7', t: '次练习' }\n];\n\nconst POSTER = {\n  btn: '生成我的月度灯海图',\n  note: '分享的是你自己的变化，不是我们的广告。',\n  toast1: '海报生成中 · 10 月灯海图',\n  toast2: '已生成，可保存或分享（默认隐藏姓名与细节）'\n};\n\nconst SEC_RECENT = { t: '最近', x: '全部' };\n\nconst TIMELINE = [\n  { d: '今天 · 17:40', t: '和伴侣的对话演练 · 第 2 轮\\n换了个开头，他没那么快进入防御', k: '话术卡已存' },\n  { d: '昨天 · 23:10', t: '情绪日记：孩子不是我一个人的事', k: '书写疗愈 · 12 分钟' },\n  { d: '10 月 6 日', t: '呼吸练习 4-7-8 · 4 分钟\\n做完说\"胸口松了一点\"', k: '呼吸疗愈' }\n];\n\nmodule.exports = {\n  HEAD: HEAD, LAMP: LAMP, STATS: STATS, POSTER: POSTER,\n  SEC_RECENT: SEC_RECENT, TIMELINE: TIMELINE\n};\n","utils/heal-data.js":"/* 疗愈页数据（2026-10-09 从甲方排版基准原型移植，文案逐字照抄）\n * 来源：backend/docs/02-设计/甲方排版基准-西米演示-2026-10-09/西米-交互演示-粉蓝水彩版.html\n * 结构：练一练（4 类目 + 4 浮层）+ 学一学（分类 chips + 课程货架）\n *\n * 数据现状（写入基准 README §七）：\n *   - 课程：甲方只给了 3 门（货架写「全部课程 12 门」），其余 9 门**故意留空**，不编造\n *   - med/OH/breath/write 的文案均来自原型，可直接用\n *   - 类的「最近三次记录」承接话术是原型静态文案，接真实数据前先照原样\n */\n/* 大景：家里的雾山（本地资产，与首页同一批）。标题压在大景下沿——家里首页就是「图上压标题」 */\nconst HERO = 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/art-feat.jpg';\n\nconst HEAD = { title: '疗愈', sub: 'PRACTICE · 练一练 学一学' };\n\n/* 顶部承接条（原型 .rec） */\nconst REC = '你刚才说脑子停不下来——先做一轮呼吸，四分钟。\\n做完再想，会清楚一点。';\n\nconst SEC_PRACTICE = { t: '练一练', x: '随时可做' };\n\n/* 四类目：kind 指练习浮层类型（write|med|breath|oh）；bgc 是底色类名而不是字面渐变 ——\n * 字面渐变不跟皮肤走，类名在页面 wxss 里用令牌定义，皮肤一换四张卡一起换 */\nconst CATS = [\n  { kind: 'write', bgc: 'bg-pink', ic: '✎', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/goods-3.jpg', h4: '书写疗愈', p: '情绪日记。写给你自己，也写给我' },\n  { kind: 'med', bgc: 'bg-lav', ic: '◎', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/goods-2.jpg', h4: '冥想疗愈', p: '按你的状态，选一段声音或引导' },\n  { kind: 'breath', bgc: 'bg-peach', ic: '◍', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/goods-4.jpg', h4: '呼吸疗愈', p: '4-7-8 呼吸。心里反复想事时最有用' },\n  { kind: 'oh', bgc: 'bg-mint', ic: '❖', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/goods-1.jpg', h4: 'OH 卡', p: '抽一张，看看它让你想到什么' }\n];\n\n/* 学一学 */\nconst SEC_COURSE = { t: '学一学', x: '全部课程 12 门' };\nconst COURSE_FILTERS = ['为你推荐', '亲子', '亲密关系', '情绪管理', '自我成长'];\n\n/* 课程货架：只有甲方给的 3 门（thumbBg 同甲方原型的 bg-* 渐变） */\nconst COURSES = [\n  {\n    thumb: '亲', bgc: 'bg-pink', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/q3.jpg',\n    h5: '孩子说不听，怎么办',\n    who: '适合：每天为写作业、看手机跟孩子拉扯的妈妈',\n    meta: ['21 天', '·', '音频 + 练习'], try: '试听', price: '¥599'\n  },\n  {\n    thumb: '关', bgc: 'bg-lav', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/q2.jpg',\n    h5: '同一件事，不再吵第三次',\n    who: '适合：总在同一个点上和伴侣绕圈的人',\n    meta: ['14 天', '·', '含话术演练'], try: '试听', price: '¥499'\n  },\n  {\n    thumb: '边', bgc: 'bg-peach', img: 'cloud://cloudbase-d3giwlyte87aecc2e.636c-cloudbase-d3giwlyte87aecc2e-1485483652/xixi-art/q1.jpg',\n    h5: '和婆婆住在一起的分寸',\n    who: '适合：同住或频繁相处、边界被反复触碰的人',\n    meta: ['10 天', '·', '音频课'], try: '试听', price: '¥299'\n  }\n];\n\n/* ---------- 浮层：书写 ---------- */\nconst WRITE = {\n  title: '书写疗愈', sub: '情绪日记 · 写完我可以回你一句',\n  hint: '今天想记下什么？\\n不用条理，写乱一点也行。',\n  ph: '今天……', save: '写完，点亮一盏灯',\n  replyFilled: '我看到了。\\n我不评价，只说一句：你愿意把它写下来，这件事就已经在处理了。',\n  replyEmpty: '空白的也算——有些时候，写不出来本身就是状态。',\n  toast: '已记录 · 点亮一盏灯'\n};\n\n/* ---------- 浮层：冥想 ---------- */\nconst MED = {\n  title: '冥想疗愈', sub: '按你最近的状态排的',\n  rec: '最近三次记录里，「停不下来」出现了 4 次。\\n先试试最上面这段。',\n  list: [\n    { h5: '把念头放下来 · 12 分钟', p: '引导练习 · 适合睡前脑子停不下来' },\n    { h5: '雨声 · 40 分钟', p: '白噪音 · 适合需要一点声音陪着' },\n    { h5: '胸口松开一点 · 8 分钟', p: '身体扫描 · 适合堵着一口气的时候' },\n    { h5: '海边黄昏 · 40 分钟', p: '白噪音 · 适合放空' }\n  ]\n};\n\n/* ---------- 浮层：OH 卡 ---------- */\nconst OH = {\n  title: 'OH 卡', sub: '不解读，只问你',\n  face: '凭直觉\\n抽一张\\n\\n（点我）',\n  opened: '一扇\\n没关严的窗',\n  openedBg: 'linear-gradient(150deg,#F3E4E7,#E3D6EC 55%,#FBEBD9)',\n  idle: '今天免费 1 张',\n  q: [\n    '这张卡里，你最先注意到的是哪一部分？',\n    '如果画面里有个声音，它在说什么？',\n    '这张卡让你想起最近哪一天？',\n    '画面里缺了什么？那个缺失的东西，你熟悉吗？',\n    '如果给它起个名字，你会叫它什么？'\n  ],\n  toast: '已记录 · 点亮一盏灯'\n};\n\n/* ---------- 浮层：呼吸 4-7-8 ---------- */\nconst BREATH = {\n  title: '呼吸疗愈', sub: '4-7-8 · 吸气 4 秒 · 屏息 7 秒 · 呼气 8 秒',\n  ready: '准备', readyStep: '跟着圆走就好',\n  start: '开始', stop: '结束',\n  /* 一轮三相：吸气 4s → 屏住 7s → 呼气 8s（原型 setTimeout 4100/7000/8100 的差值） */\n  phases: [\n    { txt: '吸气', step: '4 秒 · 慢慢吸', hold: 4100, cls: 'in' },\n    { txt: '屏住', step: '7 秒 · 不用憋太满', hold: 7000, cls: '' },\n    { txt: '呼气', step: '8 秒 · 呼干净', hold: 8100, cls: 'out' }\n  ]\n};\n\nmodule.exports = {\n  HERO: HERO,\n  HEAD: HEAD, REC: REC, SEC_PRACTICE: SEC_PRACTICE, CATS: CATS,\n  SEC_COURSE: SEC_COURSE, COURSE_FILTERS: COURSE_FILTERS, COURSES: COURSES,\n  WRITE: WRITE, MED: MED, OH: OH, BREATH: BREATH\n};\n","utils/me-data.js":"/* 我的页 + 真人陪伴浮层数据（2026-10-09 从甲方排版基准原型移植，文案逐字照抄）\n * 来源：backend/docs/02-设计/甲方排版基准-西米演示-2026-10-09/西米-交互演示-粉蓝水彩版.html\n *\n * ⚠ 与后端模型的冲突（**未拍板，禁止静默采用**，已单列进基准 README §七）：\n *   1) 雾光能量：原型「688/年 · 每月 1500 能量 · 本月已用 932」\n *      后端现状：ENERGY_MAX = 100（core/config.js），会员 ¥5,800/年\n *   2) 真人陪伴价：原型「标准陪伴 ¥5,800 / 月起」\n *      后端现状：¥5,800 / 年（年卡），两者不是同一口径\n *   3) 昵称：原型写死「许女士」，基座 stores/user 有 nickname 字段 → 本轮优先读 store，空则回落原型值\n *   → 本轮全部走本地 mock（USE_MOCK=true），不接后端；拍板后再改。\n */\nconst PROFILE = {\n  name: '许女士',            /* 兜底值；页面优先读 stores/user.get('nickname') */\n  sub: '西米陪你 12 天 · 已记录 18 次',\n  link: '换头像'\n};\n\nconst ENERGY = {\n  lb: 'FOG LIGHT · 雾光能量',\n  vt: '雾光',  /* 竖排小字：家里「今日一句」那类装置的用法 */\n  amt: '688',\n  unit: '/ 年',\n  dg: '年卡 · 每月 1500 能量',\n  used: 932,\n  max: 1500,\n  pct: 62,                    /* 932/1500 ≈ 62% */\n  hint: '本月已用 932 / 1500'\n};\n\nconst COMPANION = {\n  t: '真人陪伴',\n  x: '了解 →',\n  text: '不是一次性的倾诉热线。是一个固定的人，陪你把这件事走完。',\n  tags: [\n    { t: '每周一对一时间', cls: 'tag-pink' },\n    { t: '全程可找到人', cls: 'tag-lav' },\n    { t: '不用从头讲起', cls: 'tag-mint' }\n  ]\n};\n\n/* 设置行（第 1 行是换头像，点击开浮层；后 3 行原型无行为，本轮 toast 占位） */\nconst ROWS = [\n  { key: 'avatar', ic: '✎', bgc: 'bg-pink', t: '我的头像', s: '12 个插画可选，随时换' },\n  { key: 'profile', ic: '☼', bgc: 'bg-peach', t: '我的资料', s: '让西米更懂你，全部可以跳过' },\n  { key: 'relation', ic: '✦', bgc: 'bg-lav', t: '关系档案', s: '伴侣、孩子、婆婆——演练时用得到' },\n  { key: 'remind', ic: '◔', bgc: 'bg-mint', t: '提醒设置', s: '不打扰的分寸' }\n];\n\n/* ---------- 浮层：真人陪伴 ---------- */\nconst OV_COMP = {\n  title: '真人陪伴', sub: '深度 · 长期 · 一个固定的人',\n  lead: '不是一次性的倾诉热线。\\n是一个固定的人，陪你把这件事走完。',\n  sec1: '你会得到',\n  gains: [\n    { n: '1', bgc: 'bg-pink', t: '每周一次一对一时间', s: '固定的那个小时，只属于你' },\n    { n: '2', bgc: 'bg-lav', t: '平时也找得到人', s: '卡住的时候，不用等到下周' },\n    { n: '3', bgc: 'bg-peach', t: '不用从头讲起', s: '你在西米这里说过的，她先看过摘要' },\n    { n: '4', bgc: 'bg-mint', t: '每周一件事，看得见进展', s: '不是聊完就散' }\n  ],\n  sec2: '什么情况下适合找她',\n  bullets: ['同一件事绕了很久，自己推不动', '身边没有能不带评判听你说完的人', '正站在一个要做决定的当口，不想一个人扛'],\n  note: '不合适、不想继续，随时可以停。你不欠任何人一次继续。',\n  cta: '看看陪伴师介绍',\n  foot: '标准陪伴 ¥5,800 / 月起 · 可先聊一次再决定'\n};\n\n/* ---------- 浮层：插画头像 ---------- */\nconst OV_AVATAR = {\n  title: '我的头像', sub: '都是插画，没有真人照片',\n  lead: '选一个像现在的你的。\\n不用想太久，随时能换。',\n  foot: '头像只属于你自己——它不参与任何分享内容，也不会被用来判断你是什么样的人。',\n  toast: '换好了 · '\n};\n\nmodule.exports = {\n  PROFILE: PROFILE, ENERGY: ENERGY, COMPANION: COMPANION, ROWS: ROWS,\n  OV_COMP: OV_COMP, OV_AVATAR: OV_AVATAR\n};\n","utils/mood.js":"/* 心情数据：表情脸 SVG data-uri + 月历计算（home / moodcal 共用） */\nconst GCM = { '平静':'#DCC6C0','委屈':'#C7D0DA','焦虑':'#E4D6BC','烦躁':'#DFBCB2','难过':'#CDC2D4' };\nconst FACE = {\n  '平静':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#DCC6C0\"/><path d=\"M7.6 10.4q1.2-1.4 2.5 0M13.9 10.4q1.2-1.4 2.5 0\" stroke=\"#fff\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M8.7 14.2q3.3 2.4 6.6 0\" stroke=\"#fff\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/>',\n  '委屈':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#C7D0DA\"/><path d=\"M7.3 9.7l2.5-1.5M16.7 9.7l-2.5-1.5\" stroke=\"#fff\" stroke-width=\"1.4\" fill=\"none\" stroke-linecap=\"round\"/><circle cx=\"8.8\" cy=\"11.8\" r=\".95\" fill=\"#fff\"/><circle cx=\"15.2\" cy=\"11.8\" r=\".95\" fill=\"#fff\"/><path d=\"M9.4 15.9q2.6-1.9 5.2 0\" stroke=\"#fff\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/>',\n  '焦虑':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#E4D6BC\"/><circle cx=\"8.6\" cy=\"10.6\" r=\"1.25\" fill=\"#fff\"/><circle cx=\"15.4\" cy=\"10.6\" r=\"1.25\" fill=\"#fff\"/><path d=\"M7.6 15.2l1.4-1.3 1.5 1.3 1.5-1.3 1.5 1.3 1.4-1.3\" stroke=\"#fff\" stroke-width=\"1.4\" fill=\"none\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>',\n  '烦躁':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#DFBCB2\"/><path d=\"M7 9.4l3 1.5M17 9.4l-3 1.5\" stroke=\"#fff\" stroke-width=\"1.5\" stroke-linecap=\"round\"/><circle cx=\"9\" cy=\"12.1\" r=\".95\" fill=\"#fff\"/><circle cx=\"15\" cy=\"12.1\" r=\".95\" fill=\"#fff\"/><path d=\"M9 16.4q3-2.3 6 0\" stroke=\"#fff\" stroke-width=\"1.5\" fill=\"none\" stroke-linecap=\"round\"/>',\n  '难过':'<circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#CDC2D4\"/><path d=\"M7.9 10.6q1.1-1.2 2.3 0M13.8 10.6q1.1-1.2 2.3 0\" stroke=\"#fff\" stroke-width=\"1.4\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M8.1 13.4c-1.1 1.5-.9 2.8.3 3.1s2.1-.8 1.3-2.2z\" fill=\"#fff\"/><path d=\"M10.2 17.1q2.2-1.7 4.4 0\" stroke=\"#fff\" stroke-width=\"1.4\" fill=\"none\" stroke-linecap=\"round\"/>'\n};\nconst NAMES = Object.keys(GCM);\n\nfunction b64(s) {\n  const CH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';\n  let out = '', buf = '';\n  for (let i = 0; i < s.length; i++) {\n    buf += String.fromCharCode(s.charCodeAt(i));\n    while (buf.length >= 3) {\n      const b = [buf.charCodeAt(0), buf.charCodeAt(1), buf.charCodeAt(2)];\n      out += CH[b[0] >> 2] + CH[((b[0] & 3) << 4) | (b[1] >> 4)] + CH[((b[1] & 15) << 2) | (b[2] >> 6)] + CH[b[2] & 63];\n      buf = buf.slice(3);\n    }\n  }\n  if (buf.length === 1) out += CH[buf.charCodeAt(0) >> 2] + CH[(buf.charCodeAt(0) & 3) << 4] + '==';\n  else if (buf.length === 2) {\n    const b = [buf.charCodeAt(0), buf.charCodeAt(1)];\n    out += CH[b[0] >> 2] + CH[((b[0] & 3) << 4) | (b[1] >> 4)] + CH[(b[1] & 15) << 2] + '=';\n  }\n  return out;\n}\nfunction svgUri(svg) {\n  /* base64 无需引号：WXML style 属性内双引号会截断 */\n  return 'url(data:image/svg+xml;base64,' + b64(svg) + ')';\n}\nfunction faceUri(name) {\n  return svgUri('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\">' + FACE[name] + '</svg>');\n}\nfunction plusUri() {\n  return svgUri('<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#A9939E\" stroke-width=\"1.7\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg>');\n}\n/* 返回当月日历 + 打卡历史（演示：确定性伪随机历史 + 当天真实打卡持久化） */\nfunction calendar() {\n  const now = new Date(), y = now.getFullYear(), mo = now.getMonth(), today = now.getDate();\n  const dim = new Date(y, mo + 1, 0).getDate(), first = (new Date(y, mo, 1).getDay() + 6) % 7;\n  const hist = {};\n  const key = 'xixi_mood_' + y + '_' + mo + '_' + today;\n  for (let d = 1; d <= today; d++) hist[d] = (d * 7 + mo * 3) % 5;\n  if (wx.getStorageSync(key) !== '') hist[today] = wx.getStorageSync(key);\n  const cells = [];\n  for (let i = 0; i < first; i++) cells.push({ fut: true, pad: true });\n  for (let d = 1; d <= dim; d++) cells.push({ d, mi: d <= today ? hist[d] : null, today: d === today, fut: d > today });\n  const dow = (now.getDay() + 6) % 7, WD = ['一','二','三','四','五','六','日'];\n  const week = [];\n  for (let i = 0; i < 7; i++) {\n    const d = today - dow + i;\n    week.push({ d, label: WD[i] + ' ' + d, today: i === dow, fut: i > dow,\n      mi: i > dow ? null : hist[d], name: i > dow ? null : NAMES[hist[d]] });\n  }\n  return {\n    today, month: mo + 1, hist,\n    ym: (mo + 1) + '月 · 星期' + '日一二三四五六'[now.getDay()],\n    monthTitle: (mo + 1) + '月 · 心情月历',\n    weekCap: (mo + 1) + '月' + (today - dow) + '日 – ' + (mo + 1) + '月' + (today - dow + 6) + '日',\n    cells, week\n  };\n}\nmodule.exports = { GCM, FACE, NAMES, faceUri, plusUri, calendar, moodKey };\nfunction moodKey() {\n  const now = new Date();\n  return 'xixi_mood_' + now.getFullYear() + '_' + now.getMonth() + '_' + now.getDate();\n}\n","utils/nav.js":"/* 跳转唯一真相（2026-10-09 四页接管导航时收拢）\n *\n * 为什么需要它：小程序里 **tab 页只能 wx.switchTab、非 tab 页只能 wx.navigateTo**，\n * 用错的一侧会静默失败（无报错、无跳转），四页接管 tabBar 后全站的页面归属都变了，\n * 原来散在各页的硬编码跳转必然踩这个坑。统一走这里，归属只在本文件维护一次。\n *\n * 纪律：\n *   - TABS 必须与 app.json 的 tabBar.list 逐条一致（顺序即 tab 索引，与 behaviors/tab.js 的 tab(n) 对应）\n *   - 新增/摘除 tab 时，只改 app.json + 本文件 + custom-tab-bar/index.js 三处\n *   - 页面里不要再直接写 wx.switchTab / wx.navigateTo（除本文件的实现与 launch/summary 这类流程跳转）\n */\nconst TABS = [\n  '/pages/chat/chat',   // 0 西米（打开即对话）\n  '/pages/heal/heal',   // 1 疗愈\n  '/pages/grow/grow',   // 2 变化\n  '/pages/me/me'        // 3 我的\n];\n\n/* 取路径部分（容忍 '?a=1' 查询串） */\nfunction pathOf(url) {\n  return String(url || '').split('?')[0];\n}\n\n/* 是否 tab 页 */\nfunction isTab(url) {\n  return TABS.indexOf(pathOf(url)) > -1;\n}\n\n/* 通用跳转：按归属自动选 switchTab / navigateTo\n * opts.replace = true 时用 redirectTo（关闭当前页） */\nfunction go(url, opts) {\n  const o = opts || {};\n  if (isTab(url)) {\n    wx.switchTab({ url: pathOf(url) });\n    return;\n  }\n  if (o.replace) {\n    wx.redirectTo({ url: url });\n    return;\n  }\n  wx.navigateTo({ url: url });\n}\n\n/* 返回：优先真实返回上一页；无上一页（冷启动直达）时回落到 fallback\n * 回落目标也按归属自动选跳转方式 —— 这是原来最容易静默失败的一处\n * （x-navbar 的默认 backUrl 曾指向 /pages/home/home 并用 switchTab，该页摘掉 tab 后必失败） */\nfunction back(fallback) {\n  wx.navigateBack({\n    fail: function () { if (fallback) go(fallback); }\n  });\n}\n\nmodule.exports = { TABS: TABS, isTab: isTab, go: go, back: back, pathOf: pathOf };\n"};